{
  "name": "LexiFlow - English Learning Platform",
  "description": "A production-ready adaptive English reading and vocabulary platform featuring CEFR-graded texts, instant translation, and an SRS-based mixed quiz system."
}

// Domain Entities

export type CEFRLevel = 'A1' | 'A2' | 'B1' | 'B2' | 'C1' | 'C2';

export interface User {
  id: string;
  email: string;
  name: string;
  languagePreference: 'TR' | 'EN';
  streak: number;
  xp: number;
}

export interface Book {
  id: string;
  title: string;
  author: string;
  level: CEFRLevel;
  coverUrl: string;
  content: string; // Storing raw text for this demo, in real prod this would be fetched lazily
  excerpt: string;
  totalWords: number;
}

export interface VocabularyWord {
  id: string;
  word: string;
  translation: string;
  definition: string;
  exampleSentence: string;
  type: string; // noun, verb, etc.
  level: CEFRLevel;
  sourceBookId: string;
  nextReviewDate: Date;
  strength: number; // 0-5 for SRS
}

export interface QuizQuestion {
  id: string;
  type: 'MC_EN_TR' | 'MC_TR_EN' | 'WRITE' | 'LISTEN';
  question: string;
  correctAnswer: string;
  options?: string[]; // For Multiple Choice
  wordReference: VocabularyWord;
}

export interface QuizResult {
  score: number;
  total: number;
  wrongWordIds: string[];
}

// Service Responses

export interface DefinitionResponse {
  word: string;
  phonetic?: string;
  meanings: {
    partOfSpeech: string;
    translation: string;
    definition: string;
    example: string;
  }[];
}

import { GoogleGenAI } from "@google/genai";
import { DefinitionResponse } from "../types";

// NOTE: In a real production app, this key should come from a secure backend proxy
// to avoid exposing it on the client. For this codebase, we use the env variable
// but provide a mock fallback if it is missing.
const API_KEY = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey: API_KEY });

export const getWordDefinition = async (word: string, contextSentence: string): Promise<DefinitionResponse> => {
  // Mock Fallback if no API Key (to make the app runnable for the user immediately)
  if (!API_KEY) {
    console.warn("Using mock dictionary because API_KEY is missing.");
    await new Promise(r => setTimeout(r, 600)); // Simulate network
    return {
      word: word,
      meanings: [
        {
          partOfSpeech: "noun/verb (Mock)",
          translation: `[TR] ${word}`,
          definition: `This is a simulated definition for "${word}". Add a valid Gemini API Key to get real AI-powered definitions.`,
          example: contextSentence
        }
      ]
    };
  }

  try {
    const prompt = `
      Analyze the English word "${word}" in the context of this sentence: "${contextSentence}".
      Provide a JSON response with:
      1. Turkish translation (most appropriate for context).
      2. English definition (simple, CEFR appropriate).
      3. Part of speech.
      4. Example sentence (different from context).

      Schema:
      {
        "word": "${word}",
        "phonetic": "/.../",
        "meanings": [
          {
            "partOfSpeech": "...",
            "translation": "...",
            "definition": "...",
            "example": "..."
          }
        ]
      }
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-latest',
      contents: prompt,
      config: {
        responseMimeType: 'application/json'
      }
    });

    const text = response.text;
    if (!text) throw new Error("Empty response from AI");

    return JSON.parse(text) as DefinitionResponse;

  } catch (error) {
    console.error("Gemini API Error:", error);
    // Fallback on error
    return {
      word: word,
      meanings: [{
        partOfSpeech: "unknown",
        translation: "Çeviri hatası",
        definition: "Could not retrieve definition at this time.",
        example: ""
      }]
    };
  }
};

import React, { useState } from 'react';
import { BookOpen, GraduationCap, LayoutDashboard, LogOut, Menu, User, X, Moon, Sun } from 'lucide-react';

interface LayoutProps {
  children: React.ReactNode;
  activePage: string;
  onNavigate: (page: string) => void;
  isDarkMode: boolean;
  toggleTheme: () => void;
}

const Layout: React.FC<LayoutProps> = ({ children, activePage, onNavigate, isDarkMode, toggleTheme }) => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const NavItem = ({ page, icon: Icon, label }: { page: string; icon: any; label: string }) => {
    const isActive = activePage === page || (activePage.startsWith(page) && page !== 'dashboard');
    return (
      <button
        onClick={() => {
          onNavigate(page);
          setIsMobileMenuOpen(false);
        }}
        className={`flex items-center w-full px-4 py-3 text-sm font-medium transition-colors rounded-lg mb-1 ${
          isActive
            ? 'bg-brand-50 text-brand-600 dark:bg-brand-900/20 dark:text-brand-400'
            : 'text-gray-600 hover:bg-gray-100 dark:text-gray-400 dark:hover:bg-gray-800'
        }`}
      >
        <Icon size={20} className="mr-3" />
        {label}
      </button>
    );
  };

  return (
    <div className={`min-h-screen flex ${isDarkMode ? 'dark' : ''}`}>
      {/* Mobile Sidebar Overlay */}
      {isMobileMenuOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-40 lg:hidden"
          onClick={() => setIsMobileMenuOpen(false)}
        />
      )}

      {/* Sidebar */}
      <aside className={`
        fixed lg:static inset-y-0 left-0 z-50 w-64 bg-white dark:bg-gray-900 border-r border-gray-200 dark:border-gray-800 transform transition-transform duration-200 ease-in-out
        ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}
      `}>
        <div className="h-full flex flex-col">
          <div className="p-6 flex items-center justify-between">
            <div className="flex items-center space-x-2">
              <div className="w-8 h-8 bg-brand-600 rounded-lg flex items-center justify-center text-white font-bold text-xl">
                L
              </div>
              <span className="text-xl font-bold text-gray-900 dark:text-white">LexiFlow</span>
            </div>
            <button onClick={() => setIsMobileMenuOpen(false)} className="lg:hidden text-gray-500">
              <X size={24} />
            </button>
          </div>

          <nav className="flex-1 px-4 py-4">
            <NavItem page="dashboard" icon={LayoutDashboard} label="Dashboard" />
            <NavItem page="library" icon={BookOpen} label="Library" />
            <NavItem page="vocabulary" icon={GraduationCap} label="Vocabulary" />
            <NavItem page="profile" icon={User} label="Profile" />
          </nav>

          <div className="p-4 border-t border-gray-200 dark:border-gray-800">
            <button 
              onClick={toggleTheme}
              className="flex items-center w-full px-4 py-3 text-sm font-medium text-gray-600 hover:bg-gray-100 dark:text-gray-400 dark:hover:bg-gray-800 rounded-lg mb-2"
            >
              {isDarkMode ? <Sun size={20} className="mr-3" /> : <Moon size={20} className="mr-3" />}
              {isDarkMode ? 'Light Mode' : 'Dark Mode'}
            </button>
            <button className="flex items-center w-full px-4 py-3 text-sm font-medium text-red-600 hover:bg-red-50 dark:text-red-400 dark:hover:bg-red-900/20 rounded-lg">
              <LogOut size={20} className="mr-3" />
              Sign Out
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 min-w-0 bg-gray-50 dark:bg-gray-950 overflow-y-auto h-screen">
        <header className="lg:hidden bg-white dark:bg-gray-900 border-b border-gray-200 dark:border-gray-800 p-4 flex items-center justify-between sticky top-0 z-30">
          <div className="flex items-center space-x-2">
            <div className="w-8 h-8 bg-brand-600 rounded-lg flex items-center justify-center text-white font-bold">L</div>
            <span className="font-bold text-gray-900 dark:text-white">LexiFlow</span>
          </div>
          <button onClick={() => setIsMobileMenuOpen(true)} className="text-gray-500">
            <Menu size={24} />
          </button>
        </header>

        <div className="p-4 lg:p-8 max-w-7xl mx-auto">
          {children}
        </div>
      </main>
    </div>
  );
};

export default Layout;

import React, { useState, useRef, useEffect } from 'react';
import { Book, VocabularyWord } from '../types';
import { getWordDefinition } from '../services/geminiService';
import { ArrowLeft, Loader2, Star, Volume2, X } from 'lucide-react';

interface BookReaderProps {
  book: Book;
  onBack: () => void;
  onSaveWord: (word: VocabularyWord) => void;
  savedWords: VocabularyWord[];
}

interface SelectionState {
  word: string;
  context: string;
  x: number;
  y: number;
}

const BookReader: React.FC<BookReaderProps> = ({ book, onBack, onSaveWord, savedWords }) => {
  const [selection, setSelection] = useState<SelectionState | null>(null);
  const [isLoadingDef, setIsLoadingDef] = useState(false);
  const [definition, setDefinition] = useState<any>(null);
  const textRef = useRef<HTMLDivElement>(null);

  // Helper to split text but keep punctuation accessible for display
  const tokenizeText = (text: string) => {
    // Split by spaces, newlines, but preserve punctuation attachment logic for UI
    // Simple regex for demo: match words or non-word characters
    return text.match(/([\w’']+)|([^\w\s]+)|(\s+)/g) || [];
  };

  const handleWordClick = async (word: string, event: React.MouseEvent) => {
    // Only process actual words
    if (!/\w/.test(word)) return;

    // Calculate position for popup
    const rect = (event.target as HTMLElement).getBoundingClientRect();
    const x = Math.min(rect.left, window.innerWidth - 320); // Prevent overflow right
    const y = rect.bottom + window.scrollY + 10;

    const fullSentence = getSentenceContext(book.content, word);

    setSelection({ word, context: fullSentence, x, y });
    setDefinition(null);
    setIsLoadingDef(true);

    // Fetch definition
    const def = await getWordDefinition(word, fullSentence);
    setDefinition(def);
    setIsLoadingDef(false);
  };

  // Simple heuristic to get context
  const getSentenceContext = (text: string, word: string) => {
    const index = text.indexOf(word);
    const start = text.lastIndexOf('.', index) + 1;
    let end = text.indexOf('.', index);
    if (end === -1) end = text.length;
    return text.slice(start, end).trim();
  };

  const handleSave = () => {
    if (!definition || !selection) return;

    const newWord: VocabularyWord = {
      id: Date.now().toString(),
      word: definition.word,
      translation: definition.meanings[0].translation,
      definition: definition.meanings[0].definition,
      exampleSentence: definition.meanings[0].example,
      type: definition.meanings[0].partOfSpeech,
      level: book.level,
      sourceBookId: book.id,
      nextReviewDate: new Date(),
      strength: 0
    };

    onSaveWord(newWord);
    setSelection(null); // Close popup
  };

  const isSaved = (word: string) => {
    return savedWords.some(w => w.word.toLowerCase() === word.toLowerCase());
  };

  const playAudio = (text: string) => {
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'en-US';
    window.speechSynthesis.speak(utterance);
  };

  return (
    <div className="relative min-h-[80vh]">
      {/* Header */}
      <div className="sticky top-0 bg-white/90 dark:bg-gray-900/90 backdrop-blur-sm border-b border-gray-200 dark:border-gray-800 p-4 flex items-center justify-between z-20">
        <button onClick={onBack} className="flex items-center text-gray-600 hover:text-brand-600 dark:text-gray-400">
          <ArrowLeft className="mr-2" size={20} />
          Library
        </button>
        <div className="text-center">
          <h2 className="font-bold text-gray-900 dark:text-white">{book.title}</h2>
          <span className="text-xs font-medium px-2 py-0.5 rounded bg-brand-100 text-brand-700">{book.level}</span>
        </div>
        <div className="w-20"></div> {/* Spacer */}
      </div>

      {/* Content */}
      <div ref={textRef} className="max-w-3xl mx-auto p-6 md:p-12 text-lg md:text-xl leading-relaxed font-serif text-gray-800 dark:text-gray-200">
        {tokenizeText(book.content).map((token, index) => {
          const isWord = /\w/.test(token);
          const saved = isWord && isSaved(token);
          return isWord ? (
            <span
              key={index}
              onClick={(e) => handleWordClick(token, e)}
              className={`cursor-pointer transition-colors duration-200 rounded px-0.5
                ${saved ? 'bg-yellow-100 dark:bg-yellow-900/30 text-yellow-800 dark:text-yellow-200 border-b-2 border-yellow-400' : 'hover:bg-brand-100 dark:hover:bg-brand-900/50 hover:text-brand-700'}
                ${selection?.word === token ? 'bg-brand-200 dark:bg-brand-800' : ''}
              `}
            >
              {token}
            </span>
          ) : (
            <span key={index}>{token}</span>
          );
        })}
      </div>

      {/* Definition Popup */}
      {selection && (
        <>
          <div 
            className="fixed inset-0 z-20 bg-transparent"
            onClick={() => setSelection(null)}
          />
          <div 
            className="fixed z-30 w-80 bg-white dark:bg-gray-800 rounded-xl shadow-2xl border border-gray-200 dark:border-gray-700 overflow-hidden animate-in fade-in zoom-in-95 duration-200"
            style={{ 
              top: Math.min(selection.y, window.innerHeight - 400),
              left: Math.max(10, Math.min(selection.x, window.innerWidth - 330))
            }}
          >
            <div className="p-4">
              <div className="flex justify-between items-start mb-2">
                <div>
                  <h3 className="text-xl font-bold text-gray-900 dark:text-white capitalize">{selection.word}</h3>
                  {definition?.phonetic && <span className="text-sm text-gray-500 font-mono">{definition.phonetic}</span>}
                </div>
                <div className="flex space-x-1">
                  <button onClick={() => playAudio(selection.word)} className="p-1.5 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full text-gray-500">
                    <Volume2 size={16} />
                  </button>
                  <button onClick={() => setSelection(null)} className="p-1.5 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full text-gray-400">
                    <X size={16} />
                  </button>
                </div>
              </div>

              {isLoadingDef ? (
                <div className="py-8 flex justify-center">
                  <Loader2 className="animate-spin text-brand-500" />
                </div>
              ) : (
                <div className="space-y-3">
                  {definition?.meanings.map((meaning: any, i: number) => (
                    <div key={i}>
                      <div className="flex items-center gap-2 mb-1">
                        <span className="text-xs font-bold uppercase tracking-wider text-brand-600 bg-brand-50 dark:bg-brand-900/30 px-1.5 py-0.5 rounded">
                          {meaning.partOfSpeech}
                        </span>
                        <span className="font-semibold text-gray-900 dark:text-gray-100">
                          {meaning.translation}
                        </span>
                      </div>
                      <p className="text-sm text-gray-600 dark:text-gray-300 mb-1 leading-snug">
                        {meaning.definition}
                      </p>
                      <p className="text-xs italic text-gray-500 dark:text-gray-400 border-l-2 border-gray-300 pl-2">
                        "{meaning.example}"
                      </p>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {!isLoadingDef && (
              <div className="p-3 bg-gray-50 dark:bg-gray-900/50 border-t border-gray-100 dark:border-gray-800">
                {isSaved(selection.word) ? (
                   <div className="flex items-center justify-center text-green-600 text-sm font-medium">
                     <Star size={16} className="fill-current mr-2" />
                     Saved to Vocabulary
                   </div>
                ) : (
                  <button 
                    onClick={handleSave}
                    className="w-full flex items-center justify-center px-4 py-2 bg-brand-600 hover:bg-brand-700 text-white rounded-lg text-sm font-medium transition-colors"
                  >
                    <Star size={16} className="mr-2" />
                    Add to Favorites
                  </button>
                )}
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
};

export default BookReader;

import React, { useState, useEffect } from 'react';
import { VocabularyWord, QuizQuestion, QuizResult } from '../types';
import { CheckCircle, XCircle, RefreshCcw, Trophy, Volume2, ArrowRight } from 'lucide-react';

interface QuizEngineProps {
  words: VocabularyWord[];
  onComplete: (result: QuizResult) => void;
  onExit: () => void;
}

const QuizEngine: React.FC<QuizEngineProps> = ({ words, onComplete, onExit }) => {
  const [questions, setQuestions] = useState<QuizQuestion[]>([]);
  const [currentIdx, setCurrentIdx] = useState(0);
  const [selectedOption, setSelectedOption] = useState<string | null>(null);
  const [textInput, setTextInput] = useState('');
  const [isAnswered, setIsAnswered] = useState(false);
  const [score, setScore] = useState(0);
  const [wrongIds, setWrongIds] = useState<string[]>([]);
  const [feedback, setFeedback] = useState<'correct' | 'wrong' | null>(null);

  useEffect(() => {
    generateQuiz();
  }, []);

  const generateQuiz = () => {
    // Basic SRS Logic: Prioritize words with low strength or older review dates
    // For demo: Random shuffle 5 words
    if (words.length === 0) return;

    const quizWords = [...words]
      .sort(() => 0.5 - Math.random())
      .slice(0, Math.min(5, words.length));

    const generatedQuestions: QuizQuestion[] = quizWords.map(word => {
      const typeSeed = Math.random();
      let type: QuizQuestion['type'] = 'MC_EN_TR';

      if (typeSeed > 0.75) type = 'WRITE';
      else if (typeSeed > 0.50) type = 'LISTEN';
      else if (typeSeed > 0.25) type = 'MC_TR_EN';

      // Generate Distractors (wrong options)
      const distractors = words
        .filter(w => w.id !== word.id)
        .sort(() => 0.5 - Math.random())
        .slice(0, 3)
        .map(w => type === 'MC_EN_TR' || type === 'LISTEN' ? w.translation : w.word);

      let options: string[] = [];
      let correctAnswer = '';
      let questionText = '';

      switch (type) {
        case 'MC_EN_TR':
          questionText = `What is the Turkish meaning of "${word.word}"?`;
          correctAnswer = word.translation;
          options = [...distractors, correctAnswer].sort(() => 0.5 - Math.random());
          break;
        case 'MC_TR_EN':
          questionText = `Which word means "${word.translation}"?`;
          correctAnswer = word.word;
          options = [...distractors, correctAnswer].sort(() => 0.5 - Math.random());
          break;
        case 'WRITE':
          questionText = `Type the English word for "${word.translation}"`;
          correctAnswer = word.word;
          break;
        case 'LISTEN':
          questionText = "Listen and select the correct meaning";
          correctAnswer = word.translation;
          options = [...distractors, correctAnswer].sort(() => 0.5 - Math.random());
          break;
      }

      return {
        id: Math.random().toString(),
        type,
        question: questionText,
        correctAnswer,
        options,
        wordReference: word
      };
    });

    setQuestions(generatedQuestions);
  };

  const playWordAudio = () => {
    const word = questions[currentIdx].wordReference.word;
    const ut = new SpeechSynthesisUtterance(word);
    ut.lang = 'en-US';
    window.speechSynthesis.speak(ut);
  };

  const handleSubmit = () => {
    const q = questions[currentIdx];
    let isCorrect = false;

    if (q.type === 'WRITE') {
      isCorrect = textInput.toLowerCase().trim() === q.correctAnswer.toLowerCase();
    } else {
      isCorrect = selectedOption === q.correctAnswer;
    }

    setFeedback(isCorrect ? 'correct' : 'wrong');
    setIsAnswered(true);

    if (isCorrect) {
      setScore(s => s + 1);
      // Play ding sound (optional)
    } else {
      setWrongIds(prev => [...prev, q.wordReference.id]);
    }
  };

  const handleNext = () => {
    if (currentIdx < questions.length - 1) {
      setCurrentIdx(c => c + 1);
      setSelectedOption(null);
      setTextInput('');
      setIsAnswered(false);
      setFeedback(null);
    } else {
      // Finish
      onComplete({
        score,
        total: questions.length,
        wrongWordIds: wrongIds
      });
    }
  };

  if (questions.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-64 text-center">
        <p className="text-gray-500 mb-4">No words in your vocabulary yet.</p>
        <button onClick={onExit} className="text-brand-600 font-medium hover:underline">Go read a book first!</button>
      </div>
    );
  }

  const q = questions[currentIdx];

  return (
    <div className="max-w-xl mx-auto bg-white dark:bg-gray-800 rounded-2xl shadow-xl overflow-hidden border border-gray-200 dark:border-gray-700">
      {/* Progress Bar */}
      <div className="w-full h-2 bg-gray-100 dark:bg-gray-700">
        <div 
          className="h-full bg-brand-500 transition-all duration-300"
          style={{ width: `${((currentIdx) / questions.length) * 100}%` }}
        />
      </div>

      <div className="p-8">
        <div className="flex justify-between items-center mb-6">
          <span className="text-sm font-medium text-gray-400">Question {currentIdx + 1} of {questions.length}</span>
          <span className="text-sm font-bold text-brand-600 bg-brand-50 px-2 py-1 rounded">
             {q.type.replace(/_/g, ' ')}
          </span>
        </div>

        <h3 className="text-2xl font-bold text-gray-900 dark:text-white mb-6 text-center">
          {q.question}
        </h3>

        {q.type === 'LISTEN' && (
          <div className="flex justify-center mb-6">
            <button 
              onClick={playWordAudio}
              className="w-20 h-20 rounded-full bg-brand-100 hover:bg-brand-200 text-brand-600 flex items-center justify-center transition-transform active:scale-95"
            >
              <Volume2 size={40} />
            </button>
          </div>
        )}

        {/* Answer Section */}
        <div className="space-y-3">
          {q.type === 'WRITE' ? (
            <input
              type="text"
              value={textInput}
              onChange={(e) => setTextInput(e.target.value)}
              disabled={isAnswered}
              placeholder="Type your answer..."
              className="w-full p-4 text-lg border-2 border-gray-200 dark:border-gray-600 rounded-xl focus:border-brand-500 focus:ring-0 bg-transparent dark:text-white"
              autoFocus
            />
          ) : (
            <div className="grid grid-cols-1 gap-3">
              {q.options?.map((opt, i) => {
                let btnClass = "p-4 text-left rounded-xl border-2 transition-all font-medium ";
                if (isAnswered) {
                  if (opt === q.correctAnswer) btnClass += "border-green-500 bg-green-50 text-green-700 dark:bg-green-900/30 dark:text-green-300";
                  else if (selectedOption === opt) btnClass += "border-red-500 bg-red-50 text-red-700 dark:bg-red-900/30 dark:text-red-300";
                  else btnClass += "border-gray-100 dark:border-gray-700 opacity-50";
                } else {
                  btnClass += selectedOption === opt 
                    ? "border-brand-500 bg-brand-50 dark:bg-brand-900/20 text-brand-700" 
                    : "border-gray-200 dark:border-gray-700 hover:border-brand-300 dark:hover:border-gray-600";
                }

                return (
                  <button
                    key={i}
                    onClick={() => !isAnswered && setSelectedOption(opt)}
                    className={btnClass}
                  >
                    {opt}
                  </button>
                );
              })}
            </div>
          )}
        </div>
      </div>

      {/* Footer / Feedback */}
      <div className="p-6 bg-gray-50 dark:bg-gray-900/50 border-t border-gray-100 dark:border-gray-800">
        {!isAnswered ? (
          <button
            onClick={handleSubmit}
            disabled={!selectedOption && !textInput}
            className="w-full py-3 bg-brand-600 hover:bg-brand-700 disabled:opacity-50 disabled:cursor-not-allowed text-white rounded-xl font-bold text-lg shadow-lg shadow-brand-500/30 transition-all"
          >
            Check Answer
          </button>
        ) : (
          <div className="animate-in slide-in-from-bottom-2 duration-300">
             <div className="flex items-center mb-4">
                {feedback === 'correct' ? (
                  <div className="flex items-center text-green-600 dark:text-green-400 font-bold text-lg">
                    <CheckCircle className="mr-2" size={24} />
                    Correct!
                  </div>
                ) : (
                  <div className="flex flex-col text-red-600 dark:text-red-400">
                    <div className="flex items-center font-bold text-lg">
                      <XCircle className="mr-2" size={24} />
                      Incorrect
                    </div>
                    <span className="text-sm text-gray-500 mt-1">Correct answer: <span className="font-bold">{q.correctAnswer}</span></span>
                  </div>
                )}
             </div>
             <button
              onClick={handleNext}
              className={`w-full py-3 rounded-xl font-bold text-lg text-white shadow-lg transition-all ${
                feedback === 'correct' ? 'bg-green-600 hover:bg-green-700 shadow-green-500/30' : 'bg-brand-600 hover:bg-brand-700 shadow-brand-500/30'
              }`}
             >
               {currentIdx === questions.length - 1 ? 'Finish Quiz' : 'Next Question'}
             </button>
          </div>
        )}
      </div>
    </div>
  );
};

