// Main App Component
const App = () => {
  const [currentPage, setCurrentPage] = useState('dashboard');
  const [user, setUser] = useState<User>(MOCK_USER);
  const [activeBook, setActiveBook] = useState<Book | null>(null);
  const [savedWords, setSavedWords] = useState<VocabularyWord[]>(MOCK_VOCAB);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isQuizActive, setIsQuizActive] = useState(false);

  // Theme toggle effect
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  const handleSaveWord = (word: VocabularyWord) => {
    setSavedWords(prev => [word, ...prev]);
  };

  const handleDeleteWord = (id: string) => {
    setSavedWords(prev => prev.filter(w => w.id !== id));
  };

  const handleQuizComplete = (result: QuizResult) => {
    // In a real app, send result to backend
    console.log("Quiz Result:", result);
    setUser(prev => ({ ...prev, xp: prev.xp + (result.score * 10) }));
    setIsQuizActive(false);
    alert(`Quiz Complete! Score: ${result.score}/${result.total}`);
  };

  // Render Logic
  const renderContent = () => {
    if (isQuizActive) {
      return (
        <div className="h-full flex flex-col items-center justify-center">
          <div className="w-full max-w-2xl mb-4 flex justify-between items-center">
            <h2 className="text-xl font-bold dark:text-white">Practice Session</h2>
            <button onClick={() => setIsQuizActive(false)} className="text-gray-500 hover:text-gray-700">Exit</button>
          </div>
          <div className="w-full">
            <QuizEngine words={savedWords} onComplete={handleQuizComplete} onExit={() => setIsQuizActive(false)} />
          </div>
        </div>
      );
    }

    if (activeBook) {
      return (
        <BookReader 
          book={activeBook} 
          onBack={() => setActiveBook(null)} 
          onSaveWord={handleSaveWord}
          savedWords={savedWords}
        />
      );
    }

    switch (currentPage) {
      case 'dashboard':
        return <Dashboard user={user} vocabCount={savedWords.length} onStartQuiz={() => setIsQuizActive(true)} />;
      case 'library':
        return <Library books={MOCK_BOOKS} onSelectBook={setActiveBook} />;
      case 'vocabulary':
        return <Vocabulary words={savedWords} onDelete={handleDeleteWord} />;
      case 'profile':
        return <div className="text-center py-20 dark:text-white">Profile settings coming soon.</div>;
      default:
        return <Dashboard user={user} vocabCount={savedWords.length} onStartQuiz={() => setIsQuizActive(true)} />;
    }
  };

  return (
    <Layout 
      activePage={currentPage} 
      onNavigate={(p) => {
        setCurrentPage(p);
        setActiveBook(null);
        setIsQuizActive(false);
      }}
      isDarkMode={isDarkMode}
      toggleTheme={() => setIsDarkMode(!isDarkMode)}
    >
      {renderContent()}
    </Layout>
  );
};

export default App;

