// --- Library Component ---
const Library = ({ 
  books, 
  progressMap, 
  onSelectBook, 
  onAddBook 
}: { 
  books: Book[], 
  progressMap: Record<string, BookStatus>,
  onSelectBook: (b: Book) => void,
  onAddBook: (b: Book) => void
}) => {
  const [isAdding, setIsAdding] = useState(false);
  const [newUrl, setNewUrl] = useState('');
  const [newTitle, setNewTitle] = useState('');

  const handleAddSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newUrl || !newTitle) return;

    // Create new book (simulated)
    const newBook: Book = {
      id: 'b-' + Date.now(),
      title: newTitle,
      author: 'Unknown Author',
      level: 'A1',
      coverUrl: newUrl,
      totalWords: 500,
      excerpt: 'A newly added book for your collection.',
      content: 'This is a placeholder content for the book you just added. In a real app, you would upload a PDF here.'
    };
    onAddBook(newBook);
    setIsAdding(false);
    setNewUrl('');
    setNewTitle('');
  };

  const getStatusBadge = (status?: BookStatus) => {
    switch(status) {
      case 'COMPLETED':
        return <span className="bg-green-100 text-green-700 px-2 py-1 rounded-md text-xs font-bold flex items-center"><CheckCircle size={12} className="mr-1"/> Completed</span>;
      case 'IN_PROGRESS':
        return <span className="bg-blue-100 text-blue-700 px-2 py-1 rounded-md text-xs font-bold flex items-center"><Clock size={12} className="mr-1"/> Continue</span>;
      default:
        return <span className="bg-gray-100 text-gray-500 px-2 py-1 rounded-md text-xs font-bold flex items-center"><CircleDashed size={12} className="mr-1"/> Not Started</span>;
    }
  };

  const getCardStyle = (status?: BookStatus) => {
    if (status === 'COMPLETED') return 'border-green-200 ring-2 ring-green-500/20';
    if (status === 'IN_PROGRESS') return 'border-blue-200 ring-2 ring-blue-500/20';
    return 'border-gray-200';
  };

  return (
    <div>
      <div className="flex justify-between items-center mb-8">
        <h1 className="text-3xl font-bold dark:text-white">Library</h1>
        <button 
          onClick={() => setIsAdding(true)}
          className="flex items-center px-4 py-2 bg-gray-900 text-white dark:bg-white dark:text-gray-900 rounded-lg font-medium hover:opacity-90 transition-opacity"
        >
          <Plus size={18} className="mr-2" />
          Add Book
        </button>
      </div>

      {isAdding && (
        <div className="mb-8 bg-white dark:bg-gray-800 p-6 rounded-2xl border border-gray-200 dark:border-gray-700 animate-in slide-in-from-top-4">
          <h3 className="font-bold text-lg mb-4 dark:text-white">Add New Book (Simulation)</h3>
          <form onSubmit={handleAddSubmit} className="flex gap-4 items-end flex-wrap">
             <div className="flex-1 min-w-[200px]">
               <label className="text-xs font-bold text-gray-500 uppercase">Book Title</label>
               <input 
                 value={newTitle}
                 onChange={e => setNewTitle(e.target.value)}
                 className="w-full mt-1 px-4 py-2 border rounded-lg dark:bg-gray-900 dark:border-gray-600 dark:text-white"
                 placeholder="Enter title..."
               />
             </div>
             <div className="flex-1 min-w-[200px]">
               <label className="text-xs font-bold text-gray-500 uppercase">Cover Image URL</label>
               <input 
                 value={newUrl}
                 onChange={e => setNewUrl(e.target.value)}
                 className="w-full mt-1 px-4 py-2 border rounded-lg dark:bg-gray-900 dark:border-gray-600 dark:text-white"
                 placeholder="https://..."
               />
             </div>
             <div className="flex gap-2">
               <button type="submit" className="px-6 py-2 bg-brand-600 text-white rounded-lg font-bold">Save</button>
               <button type="button" onClick={() => setIsAdding(false)} className="px-6 py-2 bg-gray-200 text-gray-700 rounded-lg font-bold">Cancel</button>
             </div>
          </form>
        </div>
      )}

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
        {books.map(book => {
          const status = progressMap[book.id] || 'NOT_STARTED';
          return (
            <div key={book.id} className={`bg-white dark:bg-gray-800 rounded-3xl overflow-hidden border shadow-sm hover:shadow-xl transition-all duration-300 group flex flex-col ${getCardStyle(status)}`}>
              <div className="h-48 bg-gray-200 dark:bg-gray-700 relative overflow-hidden">
                <img src={book.coverUrl} alt={book.title} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                <span className="absolute top-3 right-3 bg-black/60 backdrop-blur-md text-white text-xs font-bold px-3 py-1.5 rounded-full border border-white/20">
                  {book.level}
                </span>
                <div className="absolute bottom-3 left-3">
                  {getStatusBadge(status)}
                </div>
              </div>
              <div className="p-6 flex-1 flex flex-col">
                <h3 className="font-bold text-xl mb-1 dark:text-white line-clamp-1">{book.title}</h3>
                <p className="text-sm text-gray-500 dark:text-gray-400 mb-4">{book.author}</p>
                <p className="text-sm text-gray-600 dark:text-gray-300 line-clamp-3 mb-6 flex-1 leading-relaxed">{book.excerpt}</p>
                <button 
                  onClick={() => onSelectBook(book)}
                  className={`w-full py-3 rounded-xl font-bold transition-all shadow-md 
                    ${status === 'COMPLETED' 
                      ? 'bg-green-100 text-green-800 hover:bg-green-200 dark:bg-green-900/30 dark:text-green-300' 
                      : status === 'IN_PROGRESS' 
                        ? 'bg-brand-600 text-white hover:bg-brand-700 shadow-brand-500/20' 
                        : 'bg-gray-900 text-white hover:bg-gray-800 dark:bg-white dark:text-gray-900'
                    }`}
                >
                  {status === 'COMPLETED' ? 'Read Again' : status === 'IN_PROGRESS' ? 'Continue Reading' : 'Start Reading'}
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

