// --- Main App Component ---
const App = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [user, setUser] = useState<User>(MOCK_USER);
  const [currentPage, setCurrentPage] = useState('dashboard');
  const [activeBook, setActiveBook] = useState<Book | null>(null);
  const [savedWords, setSavedWords] = useState<VocabularyWord[]>(MOCK_VOCAB);
  const [books, setBooks] = useState<Book[]>(MOCK_BOOKS);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isQuizActive, setIsQuizActive] = useState(false);
  const [bookProgress, setBookProgress] = useState<Record<string, BookStatus>>({});

  // Theme toggle effect
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    setIsAuthenticated(true);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setActiveBook(null);
    setCurrentPage('dashboard');
  };

  const handleUpdateUser = (updatedUser: User) => {
    setUser(updatedUser);
  };

  const handleToggleLanguage = () => {
    setUser(prev => ({ 
      ...prev, 
      languagePreference: prev.languagePreference === 'TR' ? 'EN' : 'TR' 
    }));
  };

  const handleAddBook = (newBook: Book) => {
    setBooks(prev => [newBook, ...prev]);
  };

  const handleSaveWord = (word: VocabularyWord) => {
    setSavedWords(prev => [word, ...prev]);
  };

  const handleDeleteWord = (id: string) => {
    setSavedWords(prev => prev.filter(w => w.id !== id));
  };

  const handleStartBook = (book: Book) => {
    setActiveBook(book);
    // If not started, mark as in progress
    if (!bookProgress[book.id] || bookProgress[book.id] === 'NOT_STARTED') {
      setBookProgress(prev => ({
        ...prev,
        [book.id]: 'IN_PROGRESS'
      }));
    }
  };

  const handleCompleteBook = (bookId: string) => {
    setBookProgress(prev => ({
      ...prev,
      [bookId]: 'COMPLETED'
    }));
  };

  const handleStartQuiz = () => {
    if (savedWords.length < 10) {
      alert("You need to add at least 10 words to your favorites before taking a quiz.");
      return;
    }
    setIsQuizActive(true);
  };

  const handleQuizComplete = (result: QuizResult) => {
    console.log("Quiz Result:", result);
    setUser(prev => ({ ...prev, xp: prev.xp + (result.score * 10) }));
    setIsQuizActive(false);
  };

  if (!isAuthenticated) {
    return (
      <div className={isDarkMode ? 'dark' : ''}>
         <Auth onLogin={handleLogin} />
      </div>
    );
  }

  // Render Logic
  const renderContent = () => {
    if (isQuizActive) {
      return (
        <div className="h-full flex flex-col items-center justify-center">
          <div className="w-full max-w-2xl mb-6 flex justify-between items-center">
            <h2 className="text-2xl font-bold dark:text-white flex items-center">
              <Clock className="mr-3 text-brand-500" /> Practice Session
            </h2>
            <button onClick={() => setIsQuizActive(false)} className="px-4 py-2 rounded-lg bg-gray-100 hover:bg-gray-200 dark:bg-gray-800 dark:text-white text-gray-600 font-medium transition-colors">
              Exit Quiz
            </button>
          </div>
          <div className="w-full">
            <QuizEngine words={savedWords} onComplete={handleQuizComplete} onExit={() => setIsQuizActive(false)} />
          </div>
        </div>
      );
    }

    if (activeBook) {
      return (
        <BookReader 
          book={activeBook} 
          onBack={() => setActiveBook(null)} 
          onSaveWord={handleSaveWord}
          savedWords={savedWords}
          onCompleteBook={handleCompleteBook}
        />
      );
    }

    switch (currentPage) {
      case 'dashboard':
        return <Dashboard user={user} vocabCount={savedWords.length} onStartQuiz={handleStartQuiz} />;
      case 'library':
        return <Library books={books} progressMap={bookProgress} onSelectBook={handleStartBook} onAddBook={handleAddBook} />;
      case 'vocabulary':
        return <Vocabulary words={savedWords} onDelete={handleDeleteWord} />;
      case 'profile':
        return <Profile user={user} onUpdate={handleUpdateUser} />;
      default:
        return <Dashboard user={user} vocabCount={savedWords.length} onStartQuiz={handleStartQuiz} />;
    }
  };

  return (
    <Layout 
      activePage={currentPage} 
      onNavigate={(p) => {
        setCurrentPage(p);
        setActiveBook(null);
        setIsQuizActive(false);
      }}
      isDarkMode={isDarkMode}
      toggleTheme={() => setIsDarkMode(!isDarkMode)}
      currentLang={user.languagePreference}
      onToggleLang={handleToggleLanguage}
    >
      {renderContent()}
    </Layout>
  );
};

export default App;

