  // --- Plan Handlers ---
  const handleEditPlan = (p: PlanConfig) => {
    setTargetPlan(p);
    setIsEditingPlan(true);
  };

  const handleSavePlan = () => {
    if (!targetPlan.id) return;
    const updatedPlans = plans.map(p => p.id === targetPlan.id ? { ...p, ...targetPlan } as PlanConfig : p);
    savePlans(updatedPlans);
    setIsEditingPlan(false);
    refreshData();
