        <form onSubmit={handlePayment} className="space-y-6">
          <div>
            <label className="block text-sm font-bold text-gray-700 dark:text-gray-300 mb-2">Name on Card</label>
            <input 
              required
              value={name}
              onChange={e => setName(e.target.value)}
              className="w-full px-4 py-3 rounded-xl bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 focus:ring-4 focus:ring-brand-100 outline-none transition-all font-bold"
              placeholder="John Doe"
            />
          </div>

          <div>
            <label className="block text-sm font-bold text-gray-700 dark:text-gray-300 mb-2">Card Number</label>
            <div className="relative">
              <input 
                required
                value={cardNumber}
                onChange={e => setCardNumber(e.target.value.replace(/\D/g, '').substring(0, 16))}
                className="w-full pl-12 pr-4 py-3 rounded-xl bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 focus:ring-4 focus:ring-brand-100 outline-none transition-all font-mono"
                placeholder="0000 0000 0000 0000"
              />
              <CreditCard className="absolute left-4 top-3.5 text-gray-400" size={20} />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-6">
            <div>
              <label className="block text-sm font-bold text-gray-700 dark:text-gray-300 mb-2">Expiry Date</label>
              <input 
                required
                value={expiry}
                onChange={e => setExpiry(e.target.value)}
                className="w-full px-4 py-3 rounded-xl bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 focus:ring-4 focus:ring-brand-100 outline-none transition-all text-center"
                placeholder="MM/YY"
              />
            </div>
            <div>
              <label className="block text-sm font-bold text-gray-700 dark:text-gray-300 mb-2">CVC</label>
              <input 
                required
                value={cvc}
                onChange={e => setCvc(e.target.value.replace(/\D/g, '').substring(0, 3))}
                className="w-full px-4 py-3 rounded-xl bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 focus:ring-4 focus:ring-brand-100 outline-none transition-all text-center"
                placeholder="123"
              />
            </div>
          </div>

          <div className="flex items-center justify-center text-sm text-gray-500 mb-4">
            <Lock size={14} className="mr-2" />
            Payments are secure and encrypted.
          </div>

          <button 
            type="submit"
            disabled={isProcessing}
            className="w-full py-4 bg-gradient-to-r from-brand-600 to-brand-500 hover:from-brand-500 hover:to-brand-400 text-white font-black text-xl rounded-xl shadow-lg shadow-brand-500/30 transform transition-all hover:scale-[1.02] active:scale-95 disabled:opacity-70 disabled:scale-100"
          >
            {isProcessing ? (
              <span className="flex items-center justify-center"><Sparkles className="animate-spin mr-2" /> Processing...</span>
            ) : (
              `Pay $${currentPrice}`
            )}
          </button>
        </form>
      </div>
    </div>
  );
};

export default Pricing;

// Domain Entities

export type CEFRLevel = 'A1' | 'A2' | 'B1' | 'B2' | 'C1' | 'C2';
export type BookStatus = 'NOT_STARTED' | 'IN_PROGRESS' | 'COMPLETED';
export type UserRole = 'USER' | 'ADMIN';
export type SubscriptionStatus = 'TRIAL' | 'ACTIVE' | 'EXPIRED';
export type PlanType = 'FREE' | 'MONTHLY' | 'YEARLY';

export interface User {
  id: string;
  email: string;
  name: string;
  password?: string; 
  languagePreference: 'TR' | 'EN';
  role: UserRole;
  streak: number;
  xp: number;

  // Subscription
  subscriptionStatus: SubscriptionStatus;
  plan: PlanType;
  trialEndsAt: number; // Timestamp
  subscriptionEndsAt?: number; // Timestamp
}

export interface Book {
  id: string;
  title: string;
  author: string;
  level: CEFRLevel;
  coverUrl: string;
  content: string; 
  excerpt: string;
  totalWords: number;
  requiredPlan: PlanType; // Access Control
  archived: boolean; // Soft Delete
}

export interface UserBookProgress {
  bookId: string;
  status: BookStatus;
  lastPosition: number; // Percentage or paragraph index
  lastReadAt: Date;
}

export interface VocabularyWord {
  id: string;
  word: string;
  translation: string;
  definition: string;
  exampleSentence: string;
  type: string; // noun, verb, etc.
  level: CEFRLevel;
  sourceBookId: string;
  nextReviewDate: Date;
  strength: number; // 0-5 for SRS
}

export interface PlanConfig {
  id: PlanType;
  name: string;
  price: number;
  durationDays: number; // New field for configurable duration
  features: string[];
}

export interface QuizQuestion {
  id: string;
  type: 'MC_EN_TR' | 'MC_TR_EN' | 'WRITE' | 'LISTEN';
  question: string;
  correctAnswer: string;
  options?: string[]; // For Multiple Choice
  wordReference: VocabularyWord;
}

export interface QuizResult {
  score: number;
  total: number;
  wrongWordIds: string[];
}

// Service Responses

export interface DefinitionResponse {
  word: string;
  phonetic?: string;
  meanings: {
    partOfSpeech: string;
    translation: string;
    definition: string;
    example: string;
  }[];
}

import React, { useState } from 'react';
import { User } from '../types';
import { getUsers, saveUser, getUserByEmail } from '../services/storage';
import { Mail, Lock, User as UserIcon, ArrowRight, BookOpen } from 'lucide-react';

interface AuthProps {
  onLogin: (user: User) => void;
}

const Auth: React.FC<AuthProps> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!email.includes('@') || password.length < 4) {
      setError('Please provide a valid email and a password (min 4 chars).');
      return;
    }

    if (isLogin) {
      // LOGIN LOGIC
      const user = getUserByEmail(email);
      if (user && user.password === password) {
        onLogin(user);
      } else {
        setError('Invalid email or password.');
      }
    } else {
      // REGISTER LOGIC
      const existing = getUserByEmail(email);
      if (existing) {
        setError('This email is already registered.');
        return;
      }

      // Default to FREE PLAN (Restricted access)
      // Users must pay or admin must assign trial to see paid content
      const newUser: User = {
        id: 'u-' + Date.now(),
        email,
        name: name,
        password: password, 
        role: 'USER',
        languagePreference: 'TR',
        streak: 0,
        xp: 0,
        subscriptionStatus: 'ACTIVE', // Active on Free plan
        plan: 'FREE',
        trialEndsAt: 0 // No trial by default
      };

      saveUser(newUser);
      onLogin(newUser);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-[#F0F4F8] dark:bg-gray-900 px-4 font-sans relative overflow-hidden">
      {/* Background Blobs */}
      <div className="absolute top-0 left-0 w-96 h-96 bg-brand-300 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-blob"></div>
      <div className="absolute top-0 right-0 w-96 h-96 bg-fun-pink/30 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-blob animation-delay-2000"></div>

      <div className="max-w-md w-full bg-white dark:bg-gray-800 rounded-3xl shadow-2xl overflow-hidden relative z-10 border border-white/50 dark:border-gray-700">
        <div className="bg-gradient-to-tr from-brand-600 to-fun-pink p-10 text-center relative overflow-hidden">
           <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] opacity-10"></div>
           <div className="flex justify-center mb-4">
             <div className="w-16 h-16 bg-white/20 backdrop-blur-md rounded-2xl flex items-center justify-center text-white shadow-xl rotate-3">
                <BookOpen size={32} strokeWidth={3} />
             </div>
           </div>
           <h1 className="text-4xl font-black text-white mb-2 tracking-tight">ReadLex</h1>
           <p className="text-brand-100 font-bold">Start your learning journey!</p>
        </div>

        <div className="p-8">
          <h2 className="text-2xl font-black text-gray-800 dark:text-white mb-6 text-center">
            {isLogin ? 'Jump Back In!' : 'Join the Adventure'}
          </h2>

          {error && (
            <div className="mb-4 p-4 bg-red-50 text-red-600 rounded-xl text-sm font-bold flex items-center">
               <span className="mr-2">⚠️</span> {error}
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-4">
            {!isLogin && (
              <div className="relative group">
                <UserIcon className="absolute left-4 top-3.5 text-gray-400 group-focus-within:text-brand-500 transition-colors" size={20} />
                <input
                  type="text"
                  placeholder="Full Name"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  className="w-full pl-12 pr-4 py-3.5 rounded-2xl border-2 border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-gray-900 dark:text-white focus:border-brand-500 focus:ring-0 outline-none transition-all font-bold"
                  required
                />
              </div>
            )}

            <div className="relative group">
              <Mail className="absolute left-4 top-3.5 text-gray-400 group-focus-within:text-brand-500 transition-colors" size={20} />
              <input
                type="email"
                placeholder="Email Address"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full pl-12 pr-4 py-3.5 rounded-2xl border-2 border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-gray-900 dark:text-white focus:border-brand-500 focus:ring-0 outline-none transition-all font-bold"
                required
              />
            </div>

            <div className="relative group">
              <Lock className="absolute left-4 top-3.5 text-gray-400 group-focus-within:text-brand-500 transition-colors" size={20} />
              <input
                type="password"
                placeholder="Password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full pl-12 pr-4 py-3.5 rounded-2xl border-2 border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-gray-900 dark:text-white focus:border-brand-500 focus:ring-0 outline-none transition-all font-bold"
                required
              />
            </div>

            <button
              type="submit"
              className="w-full bg-brand-600 hover:bg-brand-700 text-white font-black text-lg py-4 rounded-2xl shadow-xl shadow-brand-500/30 transition-all transform hover:scale-[1.02] active:scale-95 flex items-center justify-center mt-6"
            >
              {isLogin ? 'Lets Go!' : 'Create Free Account'}
              <ArrowRight size={24} className="ml-2" />
            </button>
          </form>

          <div className="mt-8 text-center">
            <button
              onClick={() => setIsLogin(!isLogin)}
              className="text-sm text-gray-500 hover:text-brand-600 dark:text-gray-400 dark:hover:text-brand-400 font-bold transition-colors"
            >
              {isLogin ? "Don't have an account? Sign Up" : "Already have an account? Sign In"}
            </button>
          </div>

           <div className="mt-6 text-center text-xs text-gray-300 font-medium">
             <p>Demo Admin: admin@readlex.com / admin</p>
           </div>
        </div>
      </div>
    </div>
  );
};

