// --- Main App Component ---
const App = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [user, setUser] = useState<User | null>(null);
  const [currentPage, setCurrentPage] = useState('dashboard');
  const [activeBook, setActiveBook] = useState<Book | null>(null);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isQuizActive, setIsQuizActive] = useState(false);

  // Dynamic Data
  const [books, setBooks] = useState<Book[]>([]);
  const [savedWords, setSavedWords] = useState<VocabularyWord[]>([]);
  const [bookProgress, setBookProgress] = useState<Record<string, BookStatus>>({});
  const [plans, setPlans] = useState<PlanConfig[]>([]);

  // Initialization
  useEffect(() => {
    initStorage();
    setPlans(getPlans());
  }, []);

  useEffect(() => {
    if (isDarkMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [isDarkMode]);

  // Subscription Check
  useEffect(() => {
    if (user && user.subscriptionStatus === 'TRIAL') {
      if (Date.now() > user.trialEndsAt) {
         // Trial Expired
         setUser(u => u ? ({ ...u, subscriptionStatus: 'EXPIRED' }) : null);
      }
    }
  }, [user]);

  // Load User Data
  useEffect(() => {
    if (user) {
      setBooks(getBooks()); 
      setSavedWords(getUserVocab(user.id));
      setBookProgress(getUserProgress(user.id));
    }
  }, [user, currentPage]); 

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    setIsAuthenticated(true);
    // Redirect to pricing if expired immediately
    if (loggedInUser.subscriptionStatus === 'EXPIRED') {
      setCurrentPage('pricing');
    }
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setUser(null);
    setActiveBook(null);
    setCurrentPage('dashboard');
  };

  const handleUpdateUser = (updatedUser: User) => {
    setUser(updatedUser);
    saveUser(updatedUser); 
  };

  const handleToggleLanguage = () => {
    if (!user) return;
    const newUser = { 
      ...user, 
      languagePreference: user.languagePreference === 'TR' ? 'EN' : 'TR' as 'EN' | 'TR'
    };
    handleUpdateUser(newUser);
  };

  const handleSaveWord = (word: VocabularyWord) => {
    if (!user) return;
    const newWords = [word, ...savedWords];
    setSavedWords(newWords);
    saveUserVocab(user.id, newWords);
  };

  const handleDeleteWord = (id: string) => {
    if (!user) return;
    const newWords = savedWords.filter(w => w.id !== id);
    setSavedWords(newWords);
    saveUserVocab(user.id, newWords);
  };

  const handleStartBook = (book: Book) => {
    if (!user) return;
    setActiveBook(book);
    if (!bookProgress[book.id] || bookProgress[book.id] === 'NOT_STARTED') {
      const newProgress = { ...bookProgress, [book.id]: 'IN_PROGRESS' as BookStatus };
      setBookProgress(newProgress);
      saveUserProgress(user.id, newProgress);
    }
  };

  const handleCompleteBook = (bookId: string) => {
    if (!user) return;
    const newProgress = { ...bookProgress, [bookId]: 'COMPLETED' as BookStatus };
    setBookProgress(newProgress);
    saveUserProgress(user.id, newProgress);
  };

  const handleStartQuiz = () => {
    if (savedWords.length < 5) {
      alert("You need at least 5 words to start a quiz.");
      return;
    }
    setIsQuizActive(true);
  };

  const handleQuizComplete = (result: QuizResult) => {
    if (!user) return;
    const newXp = user.xp + (result.score * 10);
    const updatedUser = { ...user, xp: newXp };
    setUser(updatedUser);
    saveUser(updatedUser);
    setIsQuizActive(false);
  };

  const handleUpgrade = (plan: PlanType) => {
    if(!user) return;

    const planConfig = plans.find(p => p.id === plan);
    const durationDays = planConfig ? planConfig.durationDays : (plan === 'YEARLY' ? 365 : 30);

    // Upgrade Logic
    const updatedUser: User = {
      ...user,
      subscriptionStatus: 'ACTIVE',
      plan: plan,
      subscriptionEndsAt: Date.now() + durationDays * 24 * 60 * 60 * 1000
    };
    handleUpdateUser(updatedUser);
    setCurrentPage('dashboard');
    alert("Payment Successful! Welcome to ReadLex PRO.");
  };

  // Calculate stats
  const getDailyWordCount = () => {
    const today = new Date();
    today.setHours(0,0,0,0);
    const todayTs = today.getTime();

    return savedWords.filter(w => {
       const wordTime = parseInt(w.id);
       return wordTime >= todayTs;
    }).length;
  }

  if (!isAuthenticated || !user) {
    return (
      <div className={isDarkMode ? 'dark' : ''}>
         <Auth onLogin={handleLogin} />
      </div>
    );
  }

  // Force Pricing if Expired
  if (user.subscriptionStatus === 'EXPIRED' && currentPage !== 'pricing') {
    return (
      <Layout 
        activePage="pricing" 
        onNavigate={() => {}} 
        isDarkMode={isDarkMode} 
        toggleTheme={() => setIsDarkMode(!isDarkMode)} 
        currentUser={user} 
        onToggleLang={() => {}} 
        onLogout={handleLogout}
      >
        <Pricing user={user} onUpgrade={handleUpgrade} />
      </Layout>
    );
  }

  // Render Logic
  const renderContent = () => {
    if (isQuizActive) {
      return (
        <div className="h-full flex flex-col items-center justify-center">
          <div className="w-full max-w-2xl mb-6 flex justify-between items-center">
            <h2 className="text-2xl font-black dark:text-white flex items-center">
              <Clock className="mr-3 text-brand-500" /> Practice Session
            </h2>
            <button onClick={() => setIsQuizActive(false)} className="px-5 py-2 rounded-xl bg-gray-200 hover:bg-gray-300 dark:bg-gray-800 dark:text-white text-gray-700 font-bold transition-colors">
              Exit
            </button>
          </div>
          <div className="w-full">
            <QuizEngine words={savedWords} onComplete={handleQuizComplete} onExit={() => setIsQuizActive(false)} />
          </div>
        </div>
      );
    }

    if (activeBook) {
      return (
        <BookReader 
          book={activeBook} 
          onBack={() => setActiveBook(null)} 
          onSaveWord={handleSaveWord}
          savedWords={savedWords}
          onCompleteBook={handleCompleteBook}
        />
      );
    }

    switch (currentPage) {
      case 'dashboard':
        return <Dashboard user={user} vocabCount={savedWords.length} wordsAddedToday={getDailyWordCount()} onStartQuiz={handleStartQuiz} onUpgradeClick={() => setCurrentPage('pricing')} />;
      case 'library':
        return <Library books={books} progressMap={bookProgress} onSelectBook={handleStartBook} user={user} />;
      case 'vocabulary':
        return <VocabularyWrapper user={user} words={savedWords} onDelete={handleDeleteWord} />;
      case 'profile':
        return <Profile user={user} onUpdate={handleUpdateUser} />;
      case 'pricing':
        return <Pricing user={user} onUpgrade={handleUpgrade} />;
      case 'admin':
        if (user.role !== 'ADMIN') return <div className="p-10 text-center text-red-500 font-bold text-2xl">Access Denied</div>;
        return <AdminPanel currentUser={user} />;
      default:
        return <Dashboard user={user} vocabCount={savedWords.length} wordsAddedToday={getDailyWordCount()} onStartQuiz={handleStartQuiz} onUpgradeClick={() => setCurrentPage('pricing')} />;
    }
  };

  return (
    <Layout 
      activePage={currentPage} 
      onNavigate={(p) => {
        setCurrentPage(p);
        setActiveBook(null);
        setIsQuizActive(false);
      }}
      isDarkMode={isDarkMode}
      toggleTheme={() => setIsDarkMode(!isDarkMode)}
      currentUser={user}
      onToggleLang={handleToggleLanguage}
      onLogout={handleLogout}
    >
      {renderContent()}
    </Layout>
  );
};

export default App;

import React, { useState } from 'react';
import { User } from '../types';
import { getUsers, saveUser, getUserByEmail } from '../services/storage';
import { Mail, Lock, User as UserIcon, ArrowRight, BookOpen, Globe } from 'lucide-react';
import { t } from '../services/i18n';

interface AuthProps {
  onLogin: (user: User) => void;
}

const Auth: React.FC<AuthProps> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [error, setError] = useState('');
  const [lang, setLang] = useState<'TR' | 'EN'>('TR'); // Default language for Auth screen

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!email.includes('@') || password.length < 4) {
      setError('Please provide a valid email and a password (min 4 chars).');
      return;
    }

    if (isLogin) {
      // LOGIN LOGIC
      const user = getUserByEmail(email);
      if (user && user.password === password) {
        onLogin(user);
      } else {
        setError('Invalid email or password.');
      }
    } else {
      // REGISTER LOGIC
      const existing = getUserByEmail(email);
      if (existing) {
        setError('This email is already registered.');
        return;
      }

      // Default to FREE PLAN (Restricted access)
      const newUser: User = {
        id: 'u-' + Date.now(),
        email,
        name: name,
        password: password, 
        role: 'USER',
        languagePreference: lang, // Use selected language
        streak: 0,
        xp: 0,
        subscriptionStatus: 'ACTIVE', // Active on Free plan
        plan: 'FREE',
        trialEndsAt: 0 // No trial by default
      };

      saveUser(newUser);
      onLogin(newUser);
    }
  };

  const toggleLang = () => {
    setLang(prev => prev === 'TR' ? 'EN' : 'TR');
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-[#F0F4F8] dark:bg-gray-900 px-4 font-sans relative overflow-hidden">
      {/* Background Blobs */}
      <div className="absolute top-0 left-0 w-96 h-96 bg-brand-300 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-blob"></div>
      <div className="absolute top-0 right-0 w-96 h-96 bg-fun-pink/30 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-blob animation-delay-2000"></div>

      {/* Language Toggle (Top Right) */}
      <button 
        onClick={toggleLang}
        className="absolute top-6 right-6 z-20 flex items-center bg-white dark:bg-gray-800 px-4 py-2 rounded-full shadow-md hover:scale-105 transition-transform font-bold text-gray-700 dark:text-gray-200"
      >
        <Globe size={18} className="mr-2 text-brand-500" />
        {lang}
      </button>

      <div className="max-w-md w-full bg-white dark:bg-gray-800 rounded-3xl shadow-2xl overflow-hidden relative z-10 border border-white/50 dark:border-gray-700">
        <div className="bg-gradient-to-tr from-brand-600 to-fun-pink p-10 text-center relative overflow-hidden">
           <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] opacity-10"></div>
           <div className="flex justify-center mb-4">
             <div className="w-16 h-16 bg-white/20 backdrop-blur-md rounded-2xl flex items-center justify-center text-white shadow-xl rotate-3">
                <BookOpen size={32} strokeWidth={3} />
             </div>
           </div>
           <h1 className="text-4xl font-black text-white mb-2 tracking-tight">ReadLex</h1>
           <p className="text-brand-100 font-bold">{lang === 'TR' ? 'Öğrenme yolculuğuna başla!' : 'Start your learning journey!'}</p>
        </div>

        <div className="p-8">
          <h2 className="text-2xl font-black text-gray-800 dark:text-white mb-6 text-center">
            {isLogin 
              ? (lang === 'TR' ? 'Tekrar Hoş Geldin!' : 'Jump Back In!') 
              : (lang === 'TR' ? 'Maceraya Katıl' : 'Join the Adventure')}
          </h2>

          {error && (
            <div className="mb-4 p-4 bg-red-50 text-red-600 rounded-xl text-sm font-bold flex items-center">
               <span className="mr-2">⚠️</span> {error}
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-4">
            {!isLogin && (
              <div className="relative group">
                <UserIcon className="absolute left-4 top-3.5 text-gray-400 group-focus-within:text-brand-500 transition-colors" size={20} />
                <input
