import React, { useState } from 'react';
import { User } from '../types';
import { User as UserIcon, Mail, Settings, Shield, CreditCard, Calendar, Clock, Crown } from 'lucide-react';
import { t } from '../services/i18n';

interface ProfileProps {
  user: User;
  onUpdate: (updatedUser: User) => void;
}

const Profile: React.FC<ProfileProps> = ({ user, onUpdate }) => {
  const [name, setName] = useState(user.name);
  const [newPassword, setNewPassword] = useState('');
  const [isSaved, setIsSaved] = useState(false);
  const lang = user.languagePreference;

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    onUpdate({ ...user, name });
    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
    setNewPassword('');
  };

  const calculateDaysLeft = () => {
    // If Free plan and not Trial, it's unlimited (technically)
    if (user.plan === 'FREE' && user.subscriptionStatus !== 'TRIAL') return -1;

    const end = user.subscriptionStatus === 'TRIAL' ? user.trialEndsAt : user.subscriptionEndsAt;
    if (!end) return 0;
    const diff = end - Date.now();
    return Math.max(0, Math.ceil(diff / (1000 * 60 * 60 * 24)));
  };

  const daysLeft = calculateDaysLeft();

  return (
    <div className="max-w-3xl mx-auto space-y-6">
      <h1 className="text-3xl font-black dark:text-white">{t('profile', lang)}</h1>

      {/* Subscription Card */}
