            <h2 className="text-xl font-bold flex items-center mb-2">
              <Crown className="mr-2 text-yellow-400" /> 
              Current Subscription
            </h2>
            <div className="text-4xl font-black text-transparent bg-clip-text bg-gradient-to-r from-yellow-300 to-yellow-500 mb-1">
              {user.plan} PLAN
            </div>
            <p className="text-gray-300 text-sm font-medium opacity-80">
              Status: <span className={user.subscriptionStatus === 'ACTIVE' ? 'text-green-400' : 'text-orange-400'}>{user.subscriptionStatus}</span>
            </p>
          </div>

          <div className="mt-4 md:mt-0 bg-white/10 backdrop-blur-md rounded-xl p-4 min-w-[150px]">
            <div className="text-sm text-gray-300 font-bold uppercase mb-1 flex items-center">
              <Clock size={14} className="mr-1" /> Remaining
            </div>
            <div className="text-3xl font-bold">
               {daysLeft === -1 ? (lang === 'TR' ? '∞' : '∞') : `${daysLeft} ${lang === 'TR' ? 'Gün' : 'Days'}`}
            </div>
            <div className="text-xs text-gray-400 mt-1">
               {daysLeft === -1 
                 ? (lang === 'TR' ? 'Süresiz' : 'Unlimited') 
                 : `Expires: ${new Date(user.subscriptionStatus === 'TRIAL' ? user.trialEndsAt : user.subscriptionEndsAt || 0).toLocaleDateString()}`
               }
            </div>
          </div>
        </div>
      </div>

      <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-sm border border-gray-200 dark:border-gray-700 overflow-hidden">
        <div className="bg-brand-50 dark:bg-brand-900/20 p-8 flex items-center gap-6">
          <div className="w-20 h-20 bg-brand-200 dark:bg-brand-800 rounded-full flex items-center justify-center text-3xl font-bold text-brand-700 dark:text-brand-300 border-4 border-white dark:border-gray-800 shadow-md">
            {user.name.charAt(0)}
          </div>
          <div>
            <h2 className="text-2xl font-bold text-gray-900 dark:text-white">{user.name}</h2>
            <p className="text-gray-500 dark:text-gray-400 flex items-center mt-1">
              <Mail size={16} className="mr-2" /> {user.email}
            </p>
          </div>
        </div>

        <form onSubmit={handleSave} className="p-8 space-y-6">
          <div className="space-y-4">
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">{t('displayName', lang)}</label>
            <div className="relative">
              <UserIcon className="absolute left-3 top-3 text-gray-400" size={20} />
              <input
                type="text"
                value={name}
                onChange={(e) => setName(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 rounded-xl border border-gray-200 dark:border-gray-600 bg-gray-50 dark:bg-gray-900 dark:text-white focus:ring-2 focus:ring-brand-500 outline-none"
              />
            </div>
          </div>

          <div className="space-y-4 pt-4 border-t border-gray-100 dark:border-gray-700">
            <h3 className="text-lg font-bold text-gray-900 dark:text-white flex items-center">
              <Shield size={20} className="mr-2 text-brand-500" />
              {t('security', lang)}
            </h3>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">{t('changePassword', lang)}</label>
            <div className="relative">
              <Settings className="absolute left-3 top-3 text-gray-400" size={20} />
              <input
                type="password"
                placeholder={lang === 'TR' ? "Değiştirmek için yeni şifre girin" : "Enter new password to change"}
                value={newPassword}
                onChange={(e) => setNewPassword(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 rounded-xl border border-gray-200 dark:border-gray-600 bg-gray-50 dark:bg-gray-900 dark:text-white focus:ring-2 focus:ring-brand-500 outline-none"
              />
            </div>
            <p className="text-xs text-gray-500">{lang === 'TR' ? "Değiştirmek istemiyorsanız boş bırakın." : "Leave blank if you don't want to change it."}</p>
          </div>

          <div className="pt-4 flex items-center gap-4">
            <button
              type="submit"
              className="px-8 py-3 bg-brand-600 hover:bg-brand-700 text-white font-bold rounded-xl transition-all shadow-md shadow-brand-500/20"
            >
              {t('saveChanges', lang)}
            </button>
            {isSaved && (
              <span className="text-green-600 font-medium animate-in fade-in">{t('saved', lang)}</span>
            )}
          </div>
        </form>
      </div>
    </div>
  );
};

export default Profile;

import React, { useState } from 'react';
import { User } from '../types';
import { getUsers, saveUser, getUserByEmail } from '../services/storage';
import { Mail, Lock, User as UserIcon, ArrowRight, BookOpen, Globe } from 'lucide-react';
import { t } from '../services/i18n';

interface AuthProps {
  onLogin: (user: User) => void;
}

const Auth: React.FC<AuthProps> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [error, setError] = useState('');
  const [lang, setLang] = useState<'TR' | 'EN'>('TR'); // Default language

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!email.includes('@') || password.length < 4) {
      setError('Please provide a valid email and a password (min 4 chars).');
      return;
    }

    if (isLogin) {
      // LOGIN LOGIC
      const user = getUserByEmail(email);
      if (user && user.password === password) {
        onLogin(user);
      } else {
        setError('Invalid email or password.');
      }
    } else {
      // REGISTER LOGIC
      const existing = getUserByEmail(email);
      if (existing) {
        setError('This email is already registered.');
        return;
      }

      // NEW USER LOGIC: Start with 3-Day Trial giving Premium Access (e.g., MONTHLY equivalent)
      const THREE_DAYS_MS = 3 * 24 * 60 * 60 * 1000;

      const newUser: User = {
        id: 'u-' + Date.now(),
        email,
        name: name,
        password: password, 
        role: 'USER',
        languagePreference: lang, 
        streak: 0,
        xp: 0,
        subscriptionStatus: 'TRIAL', // Start as Trial
        plan: 'MONTHLY', // Give them Monthly privileges during trial
        trialEndsAt: Date.now() + THREE_DAYS_MS 
      };

      saveUser(newUser);
      onLogin(newUser);
    }
  };

  const toggleLang = () => {
    setLang(prev => prev === 'TR' ? 'EN' : 'TR');
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-[#F0F4F8] dark:bg-gray-900 px-4 font-sans relative overflow-hidden">
      {/* Background Blobs */}
      <div className="absolute top-0 left-0 w-96 h-96 bg-brand-300 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-blob"></div>
      <div className="absolute top-0 right-0 w-96 h-96 bg-fun-pink/30 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-blob animation-delay-2000"></div>

      {/* Language Toggle (Top Right) */}
      <button 
        onClick={toggleLang}
        className="absolute top-6 right-6 z-20 flex items-center bg-white dark:bg-gray-800 px-4 py-2 rounded-full shadow-md hover:scale-105 transition-transform font-bold text-gray-700 dark:text-gray-200 border border-gray-100 dark:border-gray-700"
      >
        <Globe size={18} className="mr-2 text-brand-500" />
        {lang === 'TR' ? 'Türkçe' : 'English'}
      </button>

      <div className="max-w-md w-full bg-white dark:bg-gray-800 rounded-3xl shadow-2xl overflow-hidden relative z-10 border border-white/50 dark:border-gray-700">
        <div className="bg-gradient-to-tr from-brand-600 to-fun-pink p-10 text-center relative overflow-hidden">
           <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] opacity-10"></div>
           <div className="flex justify-center mb-4">
             <div className="w-16 h-16 bg-white/20 backdrop-blur-md rounded-2xl flex items-center justify-center text-white shadow-xl rotate-3">
                <BookOpen size={32} strokeWidth={3} />
             </div>
           </div>
           <h1 className="text-4xl font-black text-white mb-2 tracking-tight">ReadLex</h1>
           <p className="text-brand-100 font-bold">{lang === 'TR' ? 'Öğrenme yolculuğuna başla!' : 'Start your learning journey!'}</p>
        </div>

        <div className="p-8">
          <h2 className="text-2xl font-black text-gray-800 dark:text-white mb-6 text-center">
            {isLogin 
              ? (lang === 'TR' ? 'Tekrar Hoş Geldin!' : 'Jump Back In!') 
              : (lang === 'TR' ? 'Maceraya Katıl' : 'Join the Adventure')}
          </h2>

          {error && (
            <div className="mb-4 p-4 bg-red-50 text-red-600 rounded-xl text-sm font-bold flex items-center">
               <span className="mr-2">⚠️</span> {error}
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-4">
            {!isLogin && (
              <div className="relative group">
                <UserIcon className="absolute left-4 top-3.5 text-gray-400 group-focus-within:text-brand-500 transition-colors" size={20} />
                <input
                  type="text"
                  placeholder={lang === 'TR' ? 'Ad Soyad' : 'Full Name'}
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  className="w-full pl-12 pr-4 py-3.5 rounded-2xl border-2 border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-gray-900 dark:text-white focus:border-brand-500 focus:ring-0 outline-none transition-all font-bold"
                  required
                />
              </div>
            )}

            <div className="relative group">
              <Mail className="absolute left-4 top-3.5 text-gray-400 group-focus-within:text-brand-500 transition-colors" size={20} />
              <input
                type="email"
                placeholder={lang === 'TR' ? 'E-posta Adresi' : 'Email Address'}
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full pl-12 pr-4 py-3.5 rounded-2xl border-2 border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-gray-900 dark:text-white focus:border-brand-500 focus:ring-0 outline-none transition-all font-bold"
                required
              />
            </div>

            <div className="relative group">
              <Lock className="absolute left-4 top-3.5 text-gray-400 group-focus-within:text-brand-500 transition-colors" size={20} />
              <input
                type="password"
