  plan: 'TRAILER',
  trialEndsAt: Date.now() + THREE_DAYS_MS,
  subscriptionEndsAt: Date.now() + THREE_DAYS_MS
};

// --- Helper Functions ---

const getFromStorage = <T>(key: string, defaultValue: T): T => {
  const stored = localStorage.getItem(key);
  return stored ? JSON.parse(stored) : defaultValue;
};

const saveToStorage = (key: string, value: any) => {
  localStorage.setItem(key, JSON.stringify(value));
};

// --- Initialization ---

export const initStorage = () => {
  const storedBooks = localStorage.getItem(BOOKS_KEY);
  if (!storedBooks) {
    saveToStorage(BOOKS_KEY, MOCK_BOOKS);
  }

  const storedUsers = localStorage.getItem(USERS_KEY);
  if (!storedUsers) {
    saveToStorage(USERS_KEY, [ADMIN_USER, DEFAULT_USER]);
  }

  const storedPlans = localStorage.getItem(PLANS_KEY);
  if (!storedPlans) {
    saveToStorage(PLANS_KEY, DEFAULT_PLANS);
  }
};

// --- User Services ---

export const getUsers = (): User[] => {
  return getFromStorage<User[]>(USERS_KEY, []);
};

export const saveUser = (user: User) => {
  const users = getUsers();
  const index = users.findIndex(u => u.id === user.id);

  if (index >= 0) {
    users[index] = user; 
  } else {
    users.push(user); 
  }

  saveToStorage(USERS_KEY, users);
};

export const deleteUser = (userId: string) => {
  const users = getUsers().filter(u => u.id !== userId);
  saveToStorage(USERS_KEY, users);
};

export const getUserByEmail = (email: string): User | undefined => {
  return getUsers().find(u => u.email.toLowerCase() === email.toLowerCase());
};

// --- Book Services ---

export const getBooks = (): Book[] => {
  return getFromStorage<Book[]>(BOOKS_KEY, []);
};

export const saveBook = (book: Book) => {
  const books = getBooks();
  const index = books.findIndex(b => b.id === book.id);

  if (index >= 0) {
    books[index] = book;
  } else {
    books.unshift(book);
  }

  saveToStorage(BOOKS_KEY, books);
};

export const deleteBook = (bookId: string) => {
  const books = getBooks().filter(b => b.id !== bookId);
  saveToStorage(BOOKS_KEY, books);
};

// --- Plan Services (Admin) ---

export const getPlans = (): PlanConfig[] => {
  return getFromStorage<PlanConfig[]>(PLANS_KEY, DEFAULT_PLANS);
};

export const savePlans = (plans: PlanConfig[]) => {
  saveToStorage(PLANS_KEY, plans);
};

// --- User Specific Data (Vocab & Progress) ---

export const getUserVocab = (userId: string): VocabularyWord[] => {
  return getFromStorage<VocabularyWord[]>(VOCAB_KEY + userId, []);
};

export const saveUserVocab = (userId: string, words: VocabularyWord[]) => {
  saveToStorage(VOCAB_KEY + userId, words);
};

export const getUserProgress = (userId: string): Record<string, BookStatus> => {
  return getFromStorage<Record<string, BookStatus>>(PROGRESS_KEY + userId, {});
};

export const saveUserProgress = (userId: string, progress: Record<string, BookStatus>) => {
  saveToStorage(PROGRESS_KEY + userId, progress);
};

import React, { useState, useEffect } from 'react';
import { User } from '../types';
import { User as UserIcon, Mail, Settings, Shield, Clock, Crown } from 'lucide-react';
import { t } from '../services/i18n';

interface ProfileProps {
  user: User;
  onUpdate: (updatedUser: User) => void;
}

const Profile: React.FC<ProfileProps> = ({ user, onUpdate }) => {
  const [name, setName] = useState(user.name);
  const [newPassword, setNewPassword] = useState('');
  const [isSaved, setIsSaved] = useState(false);
  const [timeLeft, setTimeLeft] = useState<{d: number, h: number, m: number} | null>(null);
  const lang = user.languagePreference;

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();

    // Create updated user object
    const updatedUser = { ...user, name };

    // Only update password if user typed something
    if (newPassword.trim().length > 0) {
      updatedUser.password = newPassword;
    }

    onUpdate(updatedUser);
    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
    setNewPassword(''); // Clear field after save
  };

  // Timer logic for live countdown
  useEffect(() => {
    const calculateTime = () => {
      // If Free plan (not trial), no countdown needed
      if (user.plan === 'FREE' && user.subscriptionStatus !== 'TRIAL') {
        setTimeLeft(null);
        return;
      }

      const end = user.subscriptionStatus === 'TRIAL' ? user.trialEndsAt : user.subscriptionEndsAt || 0;
      const now = Date.now();
      const diff = end - now;

      if (diff <= 0) {
        setTimeLeft({ d: 0, h: 0, m: 0 });
        return;
      }

      const d = Math.floor(diff / (1000 * 60 * 60 * 24));
      const h = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
      const m = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));

      setTimeLeft({ d, h, m });
    };

    calculateTime();
    const timer = setInterval(calculateTime, 60000); // Update every minute

    return () => clearInterval(timer);
  }, [user]);

  // Determine display name for the plan
  const getPlanDisplayName = () => {
    if (user.subscriptionStatus === 'TRIAL') return t('trialLabel', lang);
    if (user.plan === 'FREE') return t('freePlan', lang);
    if (user.plan === 'MONTHLY') return t('monthlyPlan', lang);
    if (user.plan === 'YEARLY') return t('yearlyPlan', lang);
    return user.plan;
  };

  return (
    <div className="max-w-3xl mx-auto space-y-6">
      <h1 className="text-3xl font-black dark:text-white">{t('profile', lang)}</h1>

      {/* Subscription Card */}
      <div className="bg-gradient-to-r from-gray-900 to-gray-800 dark:from-gray-800 dark:to-gray-900 rounded-2xl p-6 text-white shadow-xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-white/5 rounded-full -translate-y-1/2 translate-x-1/4 blur-3xl"></div>

        <div className="flex flex-col md:flex-row justify-between items-start md:items-center relative z-10">
          <div>
            <h2 className="text-xl font-bold flex items-center mb-2">
              <Crown className="mr-2 text-yellow-400" /> 
              {t('currentSubscription', lang)}
            </h2>
            <div className="text-4xl font-black text-transparent bg-clip-text bg-gradient-to-r from-yellow-300 to-yellow-500 mb-1 uppercase">
              {getPlanDisplayName()}
            </div>
            <p className="text-gray-300 text-sm font-medium opacity-80">
              {t('status', lang)}: <span className={user.subscriptionStatus === 'ACTIVE' || user.subscriptionStatus === 'TRIAL' ? 'text-green-400' : 'text-orange-400'}>{user.subscriptionStatus}</span>
            </p>
          </div>

          <div className="mt-4 md:mt-0 bg-white/10 backdrop-blur-md rounded-xl p-4 min-w-[180px]">
            <div className="text-sm text-gray-300 font-bold uppercase mb-1 flex items-center">
              <Clock size={14} className="mr-1" /> {t('remaining', lang)}
            </div>

            <div className="text-2xl font-bold font-mono">
               {timeLeft === null ? (
                 <span>∞ {t('unlimited', lang)}</span>
               ) : (
                 <div className="flex gap-2">
                    <div className="flex flex-col items-center">
                       <span>{timeLeft.d}</span>
                       <span className="text-[10px] uppercase opacity-60">{t('days', lang)}</span>
                    </div>
                    <span>:</span>
                    <div className="flex flex-col items-center">
                       <span>{timeLeft.h}</span>
