const PLANS_KEY = 'readlex_plans';
const VOCAB_KEY = 'readlex_vocab_'; 
const PROGRESS_KEY = 'readlex_progress_'; 

const THREE_DAYS_MS = 3 * 24 * 60 * 60 * 1000;

// Initial Admin User
const ADMIN_USER: User = {
