                 </td>
               </tr>
             ))}
             {filtered.length === 0 && (
               <tr><td colSpan={5} className="text-center py-20 text-gray-400 font-bold">{t('noWords', lang)}</td></tr>
             )}
           </tbody>
         </table>
       </div>
     </div>
   );
};

