             </div>
             <button onClick={onNavigateToLibrary} className="text-brand-600 font-bold hover:bg-brand-50 dark:hover:bg-gray-700 p-2 rounded-lg transition-colors">
                {t('viewLibrary', lang)} &rarr;
             </button>
          </div>

          {/* Scrollable Book Container with Drag Support */}
          <div 
