import { Book, User, VocabularyWord, BookStatus, PlanConfig } from '../types';
import { MOCK_BOOKS, DEFAULT_PLANS, MOCK_USER } from './data';
import { db } from './firebase';
import { 
  collection, 
  getDocs, 
  doc, 
  setDoc, 
  getDoc, 
  updateDoc, 
  deleteDoc, 
  query, 
  where 
} from 'firebase/firestore';

// Collection Names
const USERS_COL = 'users';
const BOOKS_COL = 'books';
const PLANS_COL = 'plans';
const VOCAB_COL = 'vocabulary';
const PROGRESS_COL = 'progress';

const SESSION_KEY = 'readlex_session_uid';

// --- Helper: LocalStorage Fallback (Sync) for when Firebase is not configured ---
// We keep this temporarily so the app doesn't break while you set up Firebase
const isFirebaseReady = () => !!db && db._app.options.apiKey !== "AIzaSy...";

// --- Initialization / Seeding ---

export const initStorage = async () => {
  if (!isFirebaseReady()) {
    console.log("Using LocalStorage Fallback");
    if (!localStorage.getItem('readlex_books')) localStorage.setItem('readlex_books', JSON.stringify(MOCK_BOOKS));
    if (!localStorage.getItem('readlex_plans')) localStorage.setItem('readlex_plans', JSON.stringify(DEFAULT_PLANS));
    return;
  }

  // Check if we need to seed books
  const booksSnapshot = await getDocs(collection(db, BOOKS_COL));
  if (booksSnapshot.empty) {
    console.log("Seeding Database with Mock Books...");
    for (const book of MOCK_BOOKS) {
      await setDoc(doc(db, BOOKS_COL, book.id), book);
    }
  }

  // Check if plans exist
  const plansSnapshot = await getDocs(collection(db, PLANS_COL));
  if (plansSnapshot.empty) {
    for (const plan of DEFAULT_PLANS) {
      await setDoc(doc(db, PLANS_COL, plan.id), plan);
    }
  }
};

// --- User Services ---

export const getUsers = async (): Promise<User[]> => {
  if (!isFirebaseReady()) {
      return JSON.parse(localStorage.getItem('readlex_users') || '[]');
  }
  const snapshot = await getDocs(collection(db, USERS_COL));
  return snapshot.docs.map(d => d.data() as User);
};

export const saveUser = async (user: User) => {
  if (!isFirebaseReady()) {
      const users = await getUsers();
      const idx = users.findIndex(u => u.id === user.id);
      if (idx >= 0) users[idx] = user; else users.push(user);
      localStorage.setItem('readlex_users', JSON.stringify(users));
      return;
  }
  await setDoc(doc(db, USERS_COL, user.id), user);
};

export const deleteUser = async (userId: string) => {
  if (!isFirebaseReady()) {
     const users = (await getUsers()).filter(u => u.id !== userId);
     localStorage.setItem('readlex_users', JSON.stringify(users));
     return;
  }
  await deleteDoc(doc(db, USERS_COL, userId));
};

export const getUserByEmail = async (email: string): Promise<User | undefined> => {
  if (!isFirebaseReady()) {
      return (await getUsers()).find(u => u.email.toLowerCase() === email.toLowerCase());
  }
  const q = query(collection(db, USERS_COL), where("email", "==", email));
  const snapshot = await getDocs(q);
  if (snapshot.empty) return undefined;
  return snapshot.docs[0].data() as User;
};

export const getUserById = async (id: string): Promise<User | undefined> => {
  if (!isFirebaseReady()) {
      return (await getUsers()).find(u => u.id === id);
  }
  const docRef = doc(db, USERS_COL, id);
  const docSnap = await getDoc(docRef);
  return docSnap.exists() ? (docSnap.data() as User) : undefined;
};

// --- Session Management ---

export const saveSession = (userId: string) => {
  localStorage.setItem(SESSION_KEY, userId);
};

export const getSession = (): string | null => {
  return localStorage.getItem(SESSION_KEY);
};

export const clearSession = () => {
  localStorage.removeItem(SESSION_KEY);
};

// --- Book Services ---

export const getBooks = async (): Promise<Book[]> => {
  if (!isFirebaseReady()) {
      return JSON.parse(localStorage.getItem('readlex_books') || '[]');
  }
  const snapshot = await getDocs(collection(db, BOOKS_COL));
  return snapshot.docs.map(d => d.data() as Book);
};

export const saveBook = async (book: Book) => {
  if (!isFirebaseReady()) {
      const books = await getBooks();
      const idx = books.findIndex(b => b.id === book.id);
      if (idx >= 0) books[idx] = book; else books.unshift(book);
      localStorage.setItem('readlex_books', JSON.stringify(books));
      return;
  }
  await setDoc(doc(db, BOOKS_COL, book.id), book);
};

export const deleteBook = async (bookId: string) => {
  if (!isFirebaseReady()) {
      const books = (await getBooks()).filter(b => b.id !== bookId);
      localStorage.setItem('readlex_books', JSON.stringify(books));
      return;
  }
  await deleteDoc(doc(db, BOOKS_COL, bookId));
};

// --- Plan Services ---

export const getPlans = async (): Promise<PlanConfig[]> => {
  if (!isFirebaseReady()) {
      return JSON.parse(localStorage.getItem('readlex_plans') || JSON.stringify(DEFAULT_PLANS));
  }
  const snapshot = await getDocs(collection(db, PLANS_COL));
  const plans = snapshot.docs.map(d => d.data() as PlanConfig);
  return plans.length > 0 ? plans : DEFAULT_PLANS;
};

export const savePlans = async (plans: PlanConfig[]) => {
  if (!isFirebaseReady()) {
      localStorage.setItem('readlex_plans', JSON.stringify(plans));
      return;
  }
  // Batch write or individual sets
  for (const plan of plans) {
      await setDoc(doc(db, PLANS_COL, plan.id), plan);
  }
};

// --- User Specific Data (Sub-collections or separate collections with ID) ---
// For simplicity in this tutorial, we use root collections with UserID keys or composite keys

export const getUserVocab = async (userId: string): Promise<VocabularyWord[]> => {
  if (!isFirebaseReady()) {
      return JSON.parse(localStorage.getItem('readlex_vocab_' + userId) || '[]');
  }
  const docRef = doc(db, VOCAB_COL, userId);
  const docSnap = await getDoc(docRef);
  return docSnap.exists() ? docSnap.data().words : [];
};

export const saveUserVocab = async (userId: string, words: VocabularyWord[]) => {
  if (!isFirebaseReady()) {
      localStorage.setItem('readlex_vocab_' + userId, JSON.stringify(words));
      return;
  }
  await setDoc(doc(db, VOCAB_COL, userId), { words });
};

export const getUserProgress = async (userId: string): Promise<Record<string, BookStatus>> => {
  if (!isFirebaseReady()) {
      return JSON.parse(localStorage.getItem('readlex_progress_' + userId) || '{}');
  }
  const docRef = doc(db, PROGRESS_COL, userId);
  const docSnap = await getDoc(docRef);
  return docSnap.exists() ? docSnap.data().progress : {};
};

export const saveUserProgress = async (userId: string, progress: Record<string, BookStatus>) => {
  if (!isFirebaseReady()) {
      localStorage.setItem('readlex_progress_' + userId, JSON.stringify(progress));
      return;
  }
  await setDoc(doc(db, PROGRESS_COL, userId), { progress });
};

