import { db } from './firebase';
import { 
  collection, 
  getDocs, 
  doc, 
  setDoc, 
  getDoc, 
  deleteDoc, 
  query, 
  where 
} from 'firebase/firestore';

// Collection Names
const USERS_COL = 'users';
const BOOKS_COL = 'books';
const PLANS_COL = 'plans';
const VOCAB_COL = 'vocabulary';
const PROGRESS_COL = 'progress';

const SESSION_KEY = 'readlex_session_uid';

// Helper to check if Firebase DB is initialized
const isFirebaseReady = () => !!db;

// --- Initialization / Seeding ---

export const initStorage = async () => {
  if (!isFirebaseReady()) {
    console.warn("Firebase not ready, falling back to local storage is disabled in production mode.");
    return;
  }

  try {
    // Check if we need to seed books
    const booksSnapshot = await getDocs(collection(db, BOOKS_COL));
    if (booksSnapshot.empty) {
      console.log("Seeding Database with Mock Books...");
      for (const book of MOCK_BOOKS) {
        await setDoc(doc(db, BOOKS_COL, book.id), book);
      }
    }

    // Check if plans exist
    const plansSnapshot = await getDocs(collection(db, PLANS_COL));
    if (plansSnapshot.empty) {
      console.log("Seeding Database with Default Plans...");
      for (const plan of DEFAULT_PLANS) {
        await setDoc(doc(db, PLANS_COL, plan.id), plan);
      }
    }
  } catch (error) {
    console.error("Error during storage initialization/seeding:", error);
  }
};

// --- User Services ---

export const getUsers = async (): Promise<User[]> => {
  if (!isFirebaseReady()) return [];
  const snapshot = await getDocs(collection(db, USERS_COL));
  return snapshot.docs.map(d => d.data() as User);
};

export const saveUser = async (user: User) => {
  if (!isFirebaseReady()) return;
  await setDoc(doc(db, USERS_COL, user.id), user);
};

export const deleteUser = async (userId: string) => {
  if (!isFirebaseReady()) return;
  await deleteDoc(doc(db, USERS_COL, userId));
};

export const getUserByEmail = async (email: string): Promise<User | undefined> => {
  if (!isFirebaseReady()) return undefined;
  const q = query(collection(db, USERS_COL), where("email", "==", email));
  const snapshot = await getDocs(q);
  if (snapshot.empty) return undefined;
  return snapshot.docs[0].data() as User;
};

export const getUserById = async (id: string): Promise<User | undefined> => {
  if (!isFirebaseReady()) return undefined;
  const docRef = doc(db, USERS_COL, id);
  const docSnap = await getDoc(docRef);
  return docSnap.exists() ? (docSnap.data() as User) : undefined;
};

