export const getWordDefinition = async (word: string, contextSentence: string): Promise<DefinitionResponse> => {
  const normalizedWord = word.toLowerCase().trim().replace(/[^\w\s]/gi, '');

  // 1. Check Cache (Fastest)
  if (definitionCache.has(normalizedWord)) {
    return definitionCache.get(normalizedWord)!;
  }

  // 2. Try Custom API
  if (API_KEY) {
    try {
      const response = await fetch(API_ENDPOINT, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${API_KEY}`,
          'X-API-Key': API_KEY // Attempting both common standards
        },
        body: JSON.stringify({
          word: word,
          context: contextSentence,
          targetLang: 'tr'
        })
      });

      if (!response.ok) {
        throw new Error(`API returned status: ${response.status}`);
      }

      const data = await response.json();

      // Map response to our internal DefinitionResponse format
      // This assumes the API returns a compatible structure. 
      // If it's a simple translation API, we wrap it.
      let result: DefinitionResponse;

      if (data.meanings) {
          result = data as DefinitionResponse;
      } else if (data.translation) {
          // Simple translation fallback wrapper
          result = {
              word: word,
              meanings: [{
                  partOfSpeech: data.type || 'unknown',
                  translation: data.translation,
                  definition: data.definition || 'Definition unavailable',
                  example: contextSentence
              }]
          };
      } else {
        throw new Error("Unexpected API response format");
      }

      // Cache the result
      definitionCache.set(normalizedWord, result);
      return result;

    } catch (error) {
      console.warn("Translation API failed, falling back to local dictionary:", error);
      // Fall through to local dictionary
    }
  } 

  // 3. Local Dictionary / Fallback (Reliable)
  const localDef = FALLBACK_DICT[normalizedWord];
  const fallbackResponse: DefinitionResponse = {
    word: word,
    meanings: [{
      partOfSpeech: localDef?.type || "unknown",
      translation: localDef?.translation || `[TR] ${word}`,
      definition: localDef?.definition || "Definition currently unavailable. Please check your internet connection or API settings.",
      example: contextSentence
    }]
  };

  // Cache the fallback too so we don't delay again
  definitionCache.set(normalizedWord, fallbackResponse);

  return fallbackResponse;
};

