let app: firebase.app.App | undefined;
let db: firebase.firestore.Firestore | undefined;
let auth: firebase.auth.Auth | undefined;
let googleProvider: firebase.auth.GoogleAuthProvider | undefined;

const isSupportedEnvironment = () => {
    // Basic check for browser environment
    if (typeof window === 'undefined') return false;

    // Firebase Auth specifically requires http, https, or chrome-extension protocols
    const protocol = window.location.protocol;
    if (!['http:', 'https:', 'chrome-extension:'].includes(protocol)) {
        console.warn(`Firebase environment check: Protocol '${protocol}' is not supported for Auth.`);
        return false;
    }

    return true; 
};

try {
    // We allow app initialization in more environments, but specific services might be skipped
    if (typeof window !== 'undefined') {
        if (!firebase.apps.length) {
            app = firebase.initializeApp(firebaseConfig);
        } else {
            app = firebase.app();
        }

        // Initialize Firestore - usually works in more places or fails gracefully
        try {
            db = firebase.firestore();
        } catch (dbError) {
            console.warn("Firebase Firestore init failed:", dbError);
        }

        // Initialize Auth - STRICT check for supported environment
        if (isSupportedEnvironment()) {
            try {
                auth = firebase.auth();
                googleProvider = new firebase.auth.GoogleAuthProvider();
            } catch (authError) {
                console.warn("Firebase Auth init failed:", authError);
            }
        } else {
             console.log("Skipping Firebase Auth initialization due to unsupported environment.");
        }

        if (db) {
             console.log("✅ Firebase bağlantısı başarılı! (ReadLex Web)");
        }
    }
} catch (e: any) {
