// Local Storage Keys
const LOCAL_KEYS = {
  USERS: 'readlex_users',
  BOOKS: 'readlex_books',
  PLANS: 'readlex_plans',
  VOCAB_PREFIX: 'readlex_vocab_',
  PROGRESS_PREFIX: 'readlex_progress_'
};

const SESSION_KEY = 'readlex_session_uid';

// Helper to check if Firebase DB is initialized
const isFirebaseReady = () => !!db;

// --- Initialization / Seeding ---

export const initStorage = async () => {
  // Define the required ADMIN user
  const adminUser: User = {
    id: 'admin-oguz',
    email: 'Oguzsekmen@readlex.com',
    name: 'Oguz Sekmen',
    password: 'Oguzsekmen', 
    avatarUrl: 'https://api.dicebear.com/9.x/avataaars/svg?seed=Oguz',
    languagePreference: 'TR',
    role: 'ADMIN',
    streak: 999,
    xp: 99999,
    dailyGoal: 50,
    lastVisitDate: Date.now(),
    subscriptionStatus: 'ACTIVE',
    plan: 'YEARLY', // Admin gets full access
    trialEndsAt: Date.now() + 365 * 24 * 60 * 60 * 1000,
    subscriptionEndsAt: Date.now() + 365 * 24 * 60 * 60 * 1000
  };

  if (!isFirebaseReady()) {
    console.warn("⚠️ Firebase not available. Falling back to LocalStorage.");

    // 1. Seed Local Books if empty
    if (!localStorage.getItem(LOCAL_KEYS.BOOKS)) {
        localStorage.setItem(LOCAL_KEYS.BOOKS, JSON.stringify(MOCK_BOOKS));
    }
    // 2. Seed Local Plans if empty
    if (!localStorage.getItem(LOCAL_KEYS.PLANS)) {
        localStorage.setItem(LOCAL_KEYS.PLANS, JSON.stringify(DEFAULT_PLANS));
    }

    // 3. Seed Admin User locally
    const usersStr = localStorage.getItem(LOCAL_KEYS.USERS);
    let localUsers: User[] = usersStr ? JSON.parse(usersStr) : [];

    // Check if admin exists by email
    const adminExists = localUsers.find(u => u.email === adminUser.email);
    if (!adminExists) {
        console.log("Creating Local Admin Account:", adminUser.email);
        localUsers.push(adminUser);
        localStorage.setItem(LOCAL_KEYS.USERS, JSON.stringify(localUsers));
    }
    return;
  }

  try {
    // 1. Seed Books in Firebase
    const booksSnapshot = await db!.collection(BOOKS_COL).get();
    if (booksSnapshot.empty) {
      console.log("Seeding Database with Mock Books...");
      for (const book of MOCK_BOOKS) {
        await db!.collection(BOOKS_COL).doc(book.id).set(book);
      }
    }

    // 2. Seed Plans in Firebase
    const plansSnapshot = await db!.collection(PLANS_COL).get();
    if (plansSnapshot.empty) {
      console.log("Seeding Database with Default Plans...");
      for (const plan of DEFAULT_PLANS) {
        await db!.collection(PLANS_COL).doc(plan.id).set(plan);
      }
    }

    // 3. Ensure Admin User Exists in Firebase
    const adminQuery = await db!.collection(USERS_COL).where('email', '==', adminUser.email).get();
    if (adminQuery.empty) {
        console.log("Creating Firebase Admin Account:", adminUser.email);
        // We use set with a specific ID to ensure consistency
        await db!.collection(USERS_COL).doc(adminUser.id).set(adminUser);
    } else {
        // Optional: Update admin role if it was somehow demoted
        const doc = adminQuery.docs[0];
        if (doc.data().role !== 'ADMIN') {
            await doc.ref.update({ role: 'ADMIN', plan: 'YEARLY' });
        }
    }

  } catch (error) {
    console.error("Error during storage initialization/seeding:", error);
  }
};

