// Helper to check if Firebase DB is initialized
const isFirebaseReady = () => !!db;

// --- ROBUST FALLBACK WRAPPER ---
// This function attempts the Firebase operation first.
// If it fails (e.g. Invalid API Key, Network Error), it silently executes the LocalStorage fallback.
async function withFallback<T>(
    firebaseOp: () => Promise<T>,
    localOp: () => T | Promise<T>
): Promise<T> {
    if (!isFirebaseReady()) {
        return localOp();
    }
    try {
        return await firebaseOp();
    } catch (err: any) {
        console.warn(`Firebase operation failed (${err.code || err.message}). Falling back to LocalStorage.`);
        return localOp();
    }
}

