        async () => await db!.collection(PROGRESS_COL).doc(userId).set({ progress }),
        async () => {
            localStorage.setItem(LOCAL_KEYS.PROGRESS_PREFIX + userId, JSON.stringify(progress));
        }
    );
};

import React, { useState } from 'react';
import { User } from '../types';
import { saveUser, getUserByEmail, getUserById } from '../services/storage';
import { auth, googleProvider } from '../services/firebase';
import { Mail, Lock, User as UserIcon, ArrowRight, BookOpen, Globe, Loader2 } from 'lucide-react';
import { t } from '../services/i18n';

interface AuthProps {
  onLogin: (user: User) => void;
}

const Auth: React.FC<AuthProps> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [lang, setLang] = useState<'TR' | 'EN'>('TR'); // Default language

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    try {
        if (!email.includes('@') || password.length < 4) {
        throw new Error('Please provide a valid email and a password (min 4 chars).');
        }

        if (isLogin) {
            // LOGIN LOGIC
            const user = await getUserByEmail(email);
            if (user && user.password === password) {
                onLogin(user);
            } else {
                throw new Error('Invalid email or password.');
            }
        } else {
            // REGISTER LOGIC
            const existing = await getUserByEmail(email);
            if (existing) {
                throw new Error('This email is already registered.');
            }

            // NEW USER LOGIC: Start with 'Trailer' plan (3 Days)
            const THREE_DAYS_MS = 3 * 24 * 60 * 60 * 1000;

            const newUser: User = {
                id: 'u-' + Date.now(),
                email,
                name: name,
                password: password,
                avatarUrl: `https://api.dicebear.com/9.x/adventurer/svg?seed=${name.replace(/\s/g,'')}`, // Default Avatar
                role: 'USER',
                languagePreference: lang, 
                streak: 0,
                xp: 0,
                dailyGoal: 25, // Start with 25 words goal
                lastVisitDate: Date.now(),
                subscriptionStatus: 'ACTIVE', // Active but with a short expiry (Trailer)
                plan: 'TRAILER', // Special Trailer Plan
                trialEndsAt: Date.now() + THREE_DAYS_MS,
                subscriptionEndsAt: Date.now() + THREE_DAYS_MS
            };

            await saveUser(newUser);
            onLogin(newUser);
        }
    } catch (err: any) {
        setError(err.message || "An error occurred");
    } finally {
        setIsLoading(false);
    }
  };

  const handleGoogleLogin = async () => {
    // Check if services are initialized
    if (!auth || !googleProvider) {
      setError("Google Servisi başlatılamadı. Lütfen e-posta ile giriş yapın.");
      return;
    }

    setIsLoading(true);
    setError('');

    try {
      // Use compat syntax: auth.signInWithPopup(provider)
      const result = await auth.signInWithPopup(googleProvider);
      const fbUser = result.user;

      if (!fbUser) throw new Error("No user returned from Google");

      // 1. Check if user exists in OUR database (by ID or Email)
      let appUser = await getUserById(fbUser.uid);

      if (!appUser && fbUser.email) {
         // Fallback: Check by email
         appUser = await getUserByEmail(fbUser.email);
      }

      // 2. If User doesn't exist, Register them
      if (!appUser) {
          const THREE_DAYS_MS = 3 * 24 * 60 * 60 * 1000;
          appUser = {
            id: fbUser.uid, // Use Firebase UID as our ID
            email: fbUser.email!,
            name: fbUser.displayName || 'Google User',
            avatarUrl: fbUser.photoURL || `https://api.dicebear.com/9.x/adventurer/svg?seed=${fbUser.uid}`,
            role: 'USER',
            languagePreference: lang,
            streak: 0,
            xp: 0,
            dailyGoal: 25,
            lastVisitDate: Date.now(),
            subscriptionStatus: 'ACTIVE',
            plan: 'TRAILER',
            trialEndsAt: Date.now() + THREE_DAYS_MS,
            subscriptionEndsAt: Date.now() + THREE_DAYS_MS
          };
          await saveUser(appUser);
      }

      // 3. Log them in
      onLogin(appUser);

    } catch (err: any) {
      console.error("Google Login Error:", err);
      if (err.code === 'auth/popup-closed-by-user') {
        setError('Giriş iptal edildi.');
      } else if (err.code === 'auth/operation-not-supported-in-this-environment') {
        setError('Google Login bu ortamda desteklenmiyor (HTTP/S gerekli).');
      } else if (err.code === 'auth/api-key-not-valid.-please-pass-a-valid-api-key.') {
        setError('Google Girişi Hatası: Geçersiz API Anahtarı. Lütfen "E-posta ile" giriş yapmayı deneyin.');
      } else {
        setError(err.message || "Google girişi başarısız.");
      }
    } finally {
      setIsLoading(false);
    }
  };

  const toggleLang = () => {
    setLang(prev => prev === 'TR' ? 'EN' : 'TR');
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-[#F0F4F8] dark:bg-gray-900 px-4 font-sans relative overflow-hidden">
      {/* Background Blobs */}
      <div className="absolute top-0 left-0 w-96 h-96 bg-brand-300 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-blob"></div>
      <div className="absolute top-0 right-0 w-96 h-96 bg-fun-pink/30 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-blob animation-delay-2000"></div>

      {/* Language Toggle (Top Right) */}
      <button 
        onClick={toggleLang}
        className="absolute top-6 right-6 z-20 flex items-center bg-white dark:bg-gray-800 px-4 py-2 rounded-full shadow-md hover:scale-105 transition-transform font-bold text-gray-700 dark:text-gray-200 border border-gray-100 dark:border-gray-700"
      >
        <Globe size={18} className="mr-2 text-brand-500" />
        {lang === 'TR' ? 'Türkçe' : 'English'}
      </button>

      <div className="max-w-md w-full bg-white dark:bg-gray-800 rounded-3xl shadow-2xl overflow-hidden relative z-10 border border-white/50 dark:border-gray-700">
        <div className="bg-gradient-to-tr from-brand-600 to-fun-pink p-10 text-center relative overflow-hidden">
           <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] opacity-10"></div>
           <div className="flex justify-center mb-4">
             <div className="w-16 h-16 bg-white/20 backdrop-blur-md rounded-2xl flex items-center justify-center text-white shadow-xl rotate-3">
                <BookOpen size={32} strokeWidth={3} />
             </div>
           </div>
           <h1 className="text-4xl font-black text-white mb-2 tracking-tight">ReadLex</h1>
           <p className="text-brand-100 font-bold">{lang === 'TR' ? 'Öğrenme yolculuğuna başla!' : 'Start your learning journey!'}</p>
        </div>

        <div className="p-8">
          <h2 className="text-2xl font-black text-gray-800 dark:text-white mb-6 text-center">
            {isLogin 
              ? (lang === 'TR' ? 'Tekrar Hoş Geldin!' : 'Jump Back In!') 
              : (lang === 'TR' ? 'Maceraya Katıl' : 'Join the Adventure')}
          </h2>

          {error && (
            <div className="mb-4 p-4 bg-red-50 text-red-600 rounded-xl text-sm font-bold flex items-center animate-pulse">
               <span className="mr-2">⚠️</span> {error}
            </div>
          )}

          <div className="space-y-4">
            {/* GOOGLE LOGIN BUTTON - Always visible, errors handled in click */}
            <button
              type="button"
              onClick={handleGoogleLogin}
              disabled={isLoading}
              className="w-full bg-white dark:bg-gray-700 border-2 border-gray-100 dark:border-gray-600 hover:bg-gray-50 dark:hover:bg-gray-600 text-gray-700 dark:text-white font-bold text-lg py-3.5 rounded-2xl transition-all transform hover:scale-[1.01] active:scale-95 flex items-center justify-center gap-3 relative"
            >
              <svg className="w-6 h-6" viewBox="0 0 24 24">
                <path
                  fill="#4285F4"
                  d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
                />
                <path
                  fill="#34A853"
                  d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
                />
                <path
                  fill="#FBBC05"
                  d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.84z"
                />
                <path
                  fill="#EA4335"
                  d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
                />
              </svg>
              <span>{lang === 'TR' ? 'Google ile Devam Et' : 'Continue with Google'}</span>
            </button>

            <div className="relative flex py-2 items-center">
                <div className="flex-grow border-t border-gray-200 dark:border-gray-700"></div>
                <span className="flex-shrink-0 mx-4 text-gray-400 text-sm font-bold">{lang === 'TR' ? 'veya e-posta ile' : 'or with email'}</span>
                <div className="flex-grow border-t border-gray-200 dark:border-gray-700"></div>
            </div>

            <form onSubmit={handleSubmit} className="space-y-4">
              {!isLogin && (
                <div className="relative group">
                  <UserIcon className="absolute left-4 top-3.5 text-gray-400 group-focus-within:text-brand-500 transition-colors" size={20} />
                  <input
                    type="text"
                    placeholder={lang === 'TR' ? 'Ad Soyad' : 'Full Name'}
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    className="w-full pl-12 pr-4 py-3.5 rounded-2xl border-2 border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-gray-900 dark:text-white focus:border-brand-500 focus:ring-0 outline-none transition-all font-bold"
                    required
                  />
                </div>
              )}

              <div className="relative group">
                <Mail className="absolute left-4 top-3.5 text-gray-400 group-focus-within:text-brand-500 transition-colors" size={20} />
                <input
                  type="email"
                  placeholder={lang === 'TR' ? 'E-posta Adresi' : 'Email Address'}
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="w-full pl-12 pr-4 py-3.5 rounded-2xl border-2 border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-gray-900 dark:text-white focus:border-brand-500 focus:ring-0 outline-none transition-all font-bold"
                  required
                />
              </div>

              <div className="relative group">
                <Lock className="absolute left-4 top-3.5 text-gray-400 group-focus-within:text-brand-500 transition-colors" size={20} />
                <input
                  type="password"
                  placeholder={lang === 'TR' ? 'Şifre' : 'Password'}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full pl-12 pr-4 py-3.5 rounded-2xl border-2 border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-gray-900 dark:text-white focus:border-brand-500 focus:ring-0 outline-none transition-all font-bold"
                  required
                />
              </div>

              <button
                type="submit"
                disabled={isLoading}
                className="w-full bg-brand-600 hover:bg-brand-700 text-white font-black text-lg py-4 rounded-2xl shadow-xl shadow-brand-500/30 transition-all transform hover:scale-[1.02] active:scale-95 flex items-center justify-center mt-2 disabled:opacity-70 disabled:scale-100"
              >
                {isLoading ? <Loader2 className="animate-spin" /> : (
                    <>
                      {isLogin 
                          ? (lang === 'TR' ? 'Giriş Yap' : 'Lets Go!') 
                          : (lang === 'TR' ? 'Ücretsiz Kayıt Ol' : 'Create Account')}
                      <ArrowRight size={24} className="ml-2" />
                    </>
                )}
              </button>
            </form>
          </div>

          <div className="mt-8 text-center">
            <button
              onClick={() => setIsLogin(!isLogin)}
              className="text-sm text-gray-500 hover:text-brand-600 dark:text-gray-400 dark:hover:text-brand-400 font-bold transition-colors"
            >
              {isLogin 
                ? (lang === 'TR' ? "Hesabın yok mu? Kayıt Ol" : "Don't have an account? Sign Up") 
                : (lang === 'TR' ? "Zaten hesabın var mı? Giriş Yap" : "Already have an account? Sign In")}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Auth;

