export const getWordDefinition = async (word: string, contextSentence: string): Promise<DefinitionResponse> => {
  const normalizedWord = word.toLowerCase().trim().replace(/[^\w\s]/gi, '');

  // 1. Check Cache (Fastest)
  if (definitionCache.has(normalizedWord)) {
    return definitionCache.get(normalizedWord)!;
  }

  // 2. Use Gemini AI for Translation & Definition
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Translate and define the word "${word}" based on its context in this sentence: "${contextSentence}".`,
      config: {
        systemInstruction: `You are an expert English-Turkish language teacher. 
        Your task is to provide:
        1. The best Turkish translation for the word in the given context.
        2. A simple English definition.
        3. The part of speech (noun, verb, adjective, etc.).

        Return the result ONLY as a JSON object matching this schema:
        {
          "translation": "Turkish word",
          "definition": "Simple English explanation",
          "partOfSpeech": "type"
        }`,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            translation: { type: Type.STRING },
            definition: { type: Type.STRING },
            partOfSpeech: { type: Type.STRING }
          },
          required: ["translation", "definition", "partOfSpeech"]
        }
      }
    });

    const resultData = JSON.parse(response.text || '{}');

    if (resultData.translation) {
      const result: DefinitionResponse = {
        word: word,
        meanings: [{
          partOfSpeech: resultData.partOfSpeech || 'unknown',
          translation: resultData.translation,
          definition: resultData.definition || `Turkish: ${resultData.translation}`,
          example: contextSentence
        }]
      };

      definitionCache.set(normalizedWord, result);
      return result;
    }
  } catch (error) {
    console.error("Gemini Translation failed:", error);
    // Fallback to local dictionary if Gemini fails
  }

  // 3. Final Fallback (Reliable Local Dict)
  const localDef = FALLBACK_DICT[normalizedWord];
  const fallbackResponse: DefinitionResponse = {
    word: word,
    meanings: [{
      partOfSpeech: localDef?.type || "unknown",
      translation: localDef?.translation || `[TR] ${word}`,
      definition: localDef?.definition || "Definition currently unavailable. Please check your internet connection.",
      example: contextSentence
    }]
  };

  definitionCache.set(normalizedWord, fallbackResponse);
  return fallbackResponse;
};

