        translation: localMatch.t,
        definition: localMatch.d,
        example: contextSentence
      }]
    };
  }

  // 2. CACHE LOOKUP: Check Persistent Storage (<1ms)
  if (definitionCache.has(normalizedWord)) {
    return definitionCache.get(normalizedWord)!;
  }

  // 3. AI LOOKUP: Only if not found locally (Fallthrough)
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Translate and define "${word}" in this context: "${contextSentence}".`,
      config: {
        systemInstruction: `Return JSON: {"t": "Turkish", "d": "English definition", "p": "part of speech"}. Be fast.`,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            t: { type: Type.STRING },
            d: { type: Type.STRING },
            p: { type: Type.STRING }
          },
          required: ["t", "d", "p"]
        }
      }
    });

    const data = JSON.parse(response.text || '{}');

    if (data.t) {
      const result: DefinitionResponse = {
        word: word,
        meanings: [{
          partOfSpeech: data.p || 'unknown',
          translation: data.t,
          definition: data.d || `Turkish: ${data.t}`,
          example: contextSentence
        }]
      };

      // Update cache and save to disk
      definitionCache.set(normalizedWord, result);
      saveToPersistentCache(definitionCache);

      return result;
    }
  } catch (error) {
    console.error("AI Translation error:", error);
  }

  // 4. FINAL FALLBACK: Dynamic translation attempt
  return {
    word: word,
    meanings: [{
      partOfSpeech: "unknown",
      translation: `[TR] ${word}`,
      definition: "No instant definition available.",
      example: contextSentence
    }]
  };
};

