import { GoogleGenAI, Type } from "@google/genai";
import { DefinitionResponse } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Session-based dictionary for the current book
let currentBookDict: Record<string, DefinitionResponse> = {};

/**
 * Prefetches translations for an entire block of text.
 * This runs in the background as soon as a book is opened.
 */
export const prefetchBookContent = async (text: string): Promise<void> => {
  // Extract unique words longer than 3 chars, excluding common stop words
  const stopWords = new Set(['this', 'that', 'with', 'from', 'they', 'them', 'there', 'their']);
  const words = Array.from(new Set(
    text.toLowerCase()
      .match(/\b[a-z]{4,}\b/g) || []
  )).filter(w => !stopWords.has(w)).slice(0, 40); // Process top 40 unique words

  if (words.length === 0) return;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Context: "${text.substring(0, 500)}..." 
      Analyze these words and provide Turkish translations and simple English definitions: ${words.join(', ')}`,
      config: {
        systemInstruction: `You are a dictionary engine. Return ONLY a JSON object where keys are the English words and values are objects: {"t": "Turkish", "d": "English definition", "p": "part of speech"}.`,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: words.reduce((acc: any, word) => {
            acc[word] = {
              type: Type.OBJECT,
              properties: {
                t: { type: Type.STRING },
                d: { type: Type.STRING },
                p: { type: Type.STRING }
              }
            };
            return acc;
          }, {})
        }
      }
    });

    const batchData = JSON.parse(response.text || '{}');

    // Map batch data to our internal format
    Object.keys(batchData).forEach(word => {
      const data = batchData[word];
      currentBookDict[word] = {
        word: word,
        meanings: [{
          partOfSpeech: data.p || 'noun',
          translation: data.t,
          definition: data.d,
          example: "" // Context is the book itself
        }]
      };
    });

    console.log(`🚀 Prefetched ${Object.keys(batchData).length} words for instant access.`);
  } catch (error) {
    console.error("Prefetch failed:", error);
  }
};

export const getWordDefinition = async (word: string, contextSentence: string): Promise<DefinitionResponse> => {
  const normalized = word.toLowerCase().trim().replace(/[^\w]/g, '');

  // 1. Instant Return from Prefetched Map (0ms)
  if (currentBookDict[normalized]) {
    return currentBookDict[normalized];
  }

  // 2. Fallback to single lookup if not prefetched
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Word: "${word}" Context: "${contextSentence}"`,
      config: {
        systemInstruction: `Return JSON: {"t": "Turkish", "d": "English definition", "p": "part of speech"}.`,
        responseMimeType: "application/json"
      }
    });

    const data = JSON.parse(response.text || '{}');
    const result: DefinitionResponse = {
      word: word,
      meanings: [{
        partOfSpeech: data.p || 'unknown',
        translation: data.t || word,
        definition: data.d || "",
        example: contextSentence
      }]
    };
    currentBookDict[normalized] = result;
    return result;
  } catch {
    return {
      word: word,
      meanings: [{ partOfSpeech: "unknown", translation: word, definition: "Not found", example: contextSentence }]
    };
  }
};

