import { GoogleGenAI, Type } from "@google/genai";
import { DefinitionResponse } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Local cache to ensure instant results for already seen words
let sessionCache: Record<string, DefinitionResponse> = {};

/**
 * Prefetches the most likely words in the text to reduce wait times.
 */
export const prefetchBookContent = async (text: string): Promise<void> => {
  const words = Array.from(new Set(
    text.toLowerCase().match(/\b[a-z]{4,}\b/g) || []
  )).slice(0, 30);

  if (words.length === 0) return;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Quickly translate these words to Turkish and provide short English definitions: ${words.join(', ')}`,
      config: {
        systemInstruction: `Return ONLY JSON. Format: {"word": {"t": "Turkish", "d": "Definition", "p": "noun/verb"}}. Keep it extremely concise.`,
        responseMimeType: "application/json"
      }
    });

    const data = JSON.parse(response.text || '{}');
    Object.keys(data).forEach(w => {
      sessionCache[w] = {
        word: w,
        meanings: [{
          partOfSpeech: data[w].p || 'noun',
          translation: data[w].t,
          definition: data[w].d,
          example: ""
        }]
      };
    });
  } catch (e) {
    console.warn("Prefetch ignored for speed.");
  }
};

export const getWordDefinition = async (word: string, contextSentence: string): Promise<DefinitionResponse> => {
  const normalized = word.toLowerCase().trim().replace(/[^\w]/g, '');

  // 1. Instant return from cache
  if (sessionCache[normalized]) {
    return sessionCache[normalized];
  }

  // 2. Direct API Call (Activated)
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Word: "${word}" Context: "${contextSentence}"`,
      config: {
        systemInstruction: `Return JSON: {"t": "Turkish", "d": "Short English definition", "p": "part of speech"}.`,
        responseMimeType: "application/json",
        temperature: 0.1 // For faster, deterministic results
      }
    });

    const data = JSON.parse(response.text || '{}');
    const result: DefinitionResponse = {
      word: word,
      meanings: [{
        partOfSpeech: data.p || 'unknown',
        translation: data.t || word,
        definition: data.d || "",
        example: contextSentence
      }]
    };

    sessionCache[normalized] = result;
    return result;
  } catch {
    return {
      word: word,
      meanings: [{ partOfSpeech: "unknown", translation: word, definition: "Translation error", example: contextSentence }]
    };
  }
};

