const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
const TRANSLATE_API_KEY = "ta_0efd6d7b0f43251b9c339cf41d2f3e168d3bba127ee40439a6ea5960";
const TRANSLATE_API_URL = "https://translateapi.ai/api/v1/translate/";

// Session-based cache for maximum performance
let sessionCache: Record<string, DefinitionResponse> = {};

/**
 * Fetches instant translation from TranslateAPI.ai
 */
async function fetchFastTranslation(text: string): Promise<string> {
  try {
    const response = await fetch(TRANSLATE_API_URL, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${TRANSLATE_API_KEY}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        text: text,
        target_language: "tr"
      })
    });
    const data = await response.json();
    // Assuming the API returns { translated_text: "..." } or similar based on standard patterns
    return data.translated_text || data.translation || text;
  } catch (error) {
    console.error("TranslateAPI error:", error);
    return text;
  }
}

export const prefetchBookContent = async (text: string): Promise<void> => {
  // We keep prefetching minimal to save API units, focusing on the most frequent 20 words
  const words = Array.from(new Set(
    text.toLowerCase().match(/\b[a-z]{4,}\b/g) || []
  )).slice(0, 20);

  if (words.length === 0) return;

  // Prefetch using the fast API for translations
  for (const word of words) {
    if (!sessionCache[word]) {
      const tr = await fetchFastTranslation(word);
      sessionCache[word] = {
        word: word,
        meanings: [{
          partOfSpeech: "word",
          translation: tr,
          definition: "Loading definition...",
          example: ""
        }]
      };
    }
  }
};

export const getWordDefinition = async (word: string, contextSentence: string): Promise<DefinitionResponse> => {
  const normalized = word.toLowerCase().trim().replace(/[^\w]/g, '');

  // 1. Instant return from cache (0ms)
  if (sessionCache[normalized] && sessionCache[normalized].meanings[0].definition !== "Loading definition...") {
    return sessionCache[normalized];
  }

  // 2. Fetch from Fast Translate API first (High speed)
  const fastTr = await fetchFastTranslation(word);

  // 3. Simultaneously get detailed definition from Gemini
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Define the word "${word}" in the context of: "${contextSentence}". Return JSON: {"definition": "short english description", "pos": "noun/verb/adj"}.`,
      config: {
        responseMimeType: "application/json",
        temperature: 0.1
      }
    });

    const data = JSON.parse(response.text || '{}');
    const result: DefinitionResponse = {
      word: word,
      meanings: [{
        partOfSpeech: data.pos || 'unknown',
        translation: fastTr, // Use the fast API result here
        definition: data.definition || "",
        example: contextSentence
      }]
    };

    sessionCache[normalized] = result;
    return result;
  } catch {
    return {
      word: word,
      meanings: [{ partOfSpeech: "unknown", translation: fastTr, definition: "Contextual definition unavailable", example: contextSentence }]
    };
  }
};

