import { GoogleGenAI } from "@google/genai";
import { DefinitionResponse } from "../types";

// Note: process.env.API_KEY is for Google Gemini. 
// The TranslateAPI.ai key is provided directly by the user.
const TRANSLATE_API_KEY = "ta_0efd6d7b0f43251b9c339cf41d2f3e168d3bba127ee40439a6ea5960";
const TRANSLATE_API_URL = "https://translateapi.ai/api/v1/translate/";

// Session-based cache for maximum performance
let sessionCache: Record<string, DefinitionResponse> = {};

/**
 * Fetches instant translation from TranslateAPI.ai
 */
async function fetchFastTranslation(text: string): Promise<string> {
  if (!text || text.length === 0) return text;

  try {
    const response = await fetch(TRANSLATE_API_URL, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${TRANSLATE_API_KEY}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        text: text,
        target_language: "tr"
      })
    });

    if (!response.ok) {
      const errorData = await response.text();
      console.error(`TranslateAPI HTTP Error: ${response.status}`, errorData);
      return text;
    }

    const data = await response.json();
    console.debug("TranslateAPI Raw Response:", data);

    // Robust field checking based on standard TranslateAPI.ai response formats
    return data.translated_text || data.translation || data.result || (data.data && data.data.translatedText) || text;
  } catch (error) {
    console.error("TranslateAPI Network/Fetch error:", error);
    return text;
  }
}

/**
 * Prefetches translations in background
 */
export const prefetchBookContent = async (text: string): Promise<void> => {
  const words = Array.from(new Set(
    text.toLowerCase().match(/\b[a-z]{4,}\b/g) || []
  )).slice(0, 15);

  if (words.length === 0) return;

  // Prefetch sequentially to avoid rate limiting and ensure stable calls
  for (const word of words) {
    if (!sessionCache[word]) {
      const tr = await fetchFastTranslation(word);
      if (tr !== word) {
        sessionCache[word] = {
          word: word,
          meanings: [{
            partOfSpeech: "word",
            translation: tr,
            definition: "Contextual definition loading...",
            example: ""
          }]
        };
      }
    }
  }
};

/**
 * Combined logic: Gets fast translation + Detailed Gemini context
 */
export const getWordDefinition = async (word: string, contextSentence: string): Promise<DefinitionResponse> => {
  const normalized = word.toLowerCase().trim().replace(/[^\w]/g, '');

  // 1. Instant return from cache (0ms)
  if (sessionCache[normalized] && sessionCache[normalized].meanings[0].definition !== "Contextual definition loading...") {
    return sessionCache[normalized];
  }

  // 2. Fetch from TranslateAPI.ai (High speed)
  const fastTr = await fetchFastTranslation(word);

  // 3. Gemini for English Context (if key is available)
  if (!process.env.API_KEY) {
     return {
        word: word,
        meanings: [{ partOfSpeech: "word", translation: fastTr, definition: "No AI context available.", example: contextSentence }]
     };
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Define word: "${word}" in sentence: "${contextSentence}". Format JSON: {"d": "Short English definition", "p": "noun/verb/adj"}.`,
      config: {
        responseMimeType: "application/json",
        temperature: 0.1
      }
    });

    const data = JSON.parse(response.text || '{}');
    const result: DefinitionResponse = {
      word: word,
      meanings: [{
        partOfSpeech: data.p || 'unknown',
        translation: fastTr,
        definition: data.d || "No definition found.",
        example: contextSentence
      }]
    };

    sessionCache[normalized] = result;
    return result;
  } catch (err) {
    console.error("Gemini Error:", err);
    return {
      word: word,
      meanings: [{ partOfSpeech: "unknown", translation: fastTr, definition: "Translation successful, context failed.", example: contextSentence }]
    };
  }
};

