import { GoogleGenAI } from "@google/genai";
import { DefinitionResponse } from "../types";

// Note: process.env.API_KEY is for Google Gemini. 
const DEEPL_API_KEY = "0f41027e-c3e5-4402-9b2e-7128debdd878:fx";
const DEEPL_API_URL = "https://api-free.deepl.com/v2/translate";

// Session-based cache for maximum performance
let sessionCache: Record<string, DefinitionResponse> = {};

/**
 * Fetches high-precision translation from DeepL API
 */
async function fetchDeepLTranslation(text: string): Promise<string> {
  if (!text || text.length === 0) return text;

  try {
    // DeepL Free API expects parameters in body or query. 
    // Using URLSearchParams for robust encoding.
    const params = new URLSearchParams();
    params.append('auth_key', DEEPL_API_KEY);
    params.append('text', text);
    params.append('target_lang', 'TR');

    const response = await fetch(DEEPL_API_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      body: params.toString()
    });

    if (!response.ok) {
      const errorText = await response.text();
      console.error(`DeepL Error ${response.status}:`, errorText);
      return text; // Fallback to original text
    }

    const data = await response.json();
    return data.translations?.[0]?.text || text;
  } catch (error) {
    console.error("DeepL Network Error:", error);
    return text;
  }
}

/**
 * Prefetches translations for the most frequent words in the text
 */
export const prefetchBookContent = async (text: string): Promise<void> => {
  const words = Array.from(new Set(
    text.toLowerCase().match(/\b[a-z]{4,}\b/g) || []
  )).slice(0, 20);

  if (words.length === 0) return;

  // Prefetch sequentially to respect free tier limits if any
  for (const word of words) {
    if (!sessionCache[word]) {
      const tr = await fetchDeepLTranslation(word);
      if (tr !== word) {
        sessionCache[word] = {
          word: word,
          meanings: [{
            partOfSpeech: "word",
            translation: tr,
            definition: "Contextual info loading...",
            example: ""
          }]
        };
      }
    }
