};

/**
 * Main function: Gets DeepL translation + Detailed Gemini context
 */
export const getWordDefinition = async (word: string, contextSentence: string): Promise<DefinitionResponse> => {
  const normalized = word.toLowerCase().trim().replace(/[^\w]/g, '');

  // 1. Instant return from cache (0ms)
  if (sessionCache[normalized] && sessionCache[normalized].meanings[0].definition !== "Contextual info loading...") {
    return sessionCache[normalized];
  }

  // 2. Fetch from DeepL (Highest speed/accuracy for Turkish)
  const turkishTranslation = await fetchDeepLTranslation(word);

  // 3. Get deeper context from Gemini
  if (!process.env.API_KEY) {
     return {
        word: word,
        meanings: [{ partOfSpeech: "word", translation: turkishTranslation, definition: "Gemini API key missing for English context.", example: contextSentence }]
     };
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Word: "${word}" in Context: "${contextSentence}". Return JSON: {"d": "Short English definition", "p": "noun/verb/adj/adv"}.`,
      config: {
        responseMimeType: "application/json",
        temperature: 0.1
      }
    });

    const data = JSON.parse(response.text || '{}');
    const result: DefinitionResponse = {
      word: word,
      meanings: [{
        partOfSpeech: data.p || 'unknown',
        translation: turkishTranslation,
        definition: data.d || "No English definition found.",
        example: contextSentence
      }]
    };

    sessionCache[normalized] = result;
    return result;
  } catch (err) {
    console.error("Gemini Error:", err);
    return {
      word: word,
      meanings: [{ partOfSpeech: "unknown", translation: turkishTranslation, definition: "Contextual analysis failed.", example: contextSentence }]
    };
  }
};

import { GoogleGenAI } from "@google/genai";
import { DefinitionResponse } from "../types";

// Note: process.env.API_KEY is for Google Gemini. 
const DEEPL_API_KEY = "0f41027e-c3e5-4402-9b2e-7128debdd878:fx";
const DEEPL_API_URL = "https://api-free.deepl.com/v2/translate";

// Session-based cache for maximum performance
let sessionCache: Record<string, DefinitionResponse> = {};

/**
 * DeepL API üzerinden yüksek hassasiyetli çeviri dener.
 * Not: Tarayıcı tabanlı fetch istekleri CORS nedeniyle DeepL tarafından engellenebilir.
 * Bu durumda sistem otomatik olarak Gemini yedeklemesine geçer.
 */
async function fetchDeepLTranslation(text: string): Promise<string | null> {
  if (!text || text.length === 0) return null;

  try {
    const params = new URLSearchParams();
    params.append('text', text);
    params.append('target_lang', 'TR');

    const response = await fetch(DEEPL_API_URL, {
      method: 'POST',
      headers: {
        'Authorization': `DeepL ${DEEPL_API_KEY}`,
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      body: params.toString()
    });

    if (!response.ok) {
      console.warn("DeepL API erişimi başarısız. Gemini yedeklemesi kullanılacak.");
      return null;
    }

    const data = await response.json();
    return data.translations?.[0]?.text || null;
  } catch (error) {
    // Genellikle CORS hatası burada yakalanır
    console.debug("DeepL CORS engeline takıldı. Gemini üzerinden çeviri yapılıyor.");
    return null;
  }
}

