/**
 * Ana Fonksiyon: DeepL (eğer mümkünse) + Gemini Bağlamsal Analiz
 */
export const getWordDefinition = async (word: string, contextSentence: string): Promise<DefinitionResponse> => {
  const normalized = word.toLowerCase().trim().replace(/[^\w]/g, '');

  // 1. Önbellekten anında getir (0ms)
  if (sessionCache[normalized]) {
    return sessionCache[normalized];
  }

  // 2. DeepL'den çeviri dener
  let turkishTranslation = await fetchDeepLTranslation(word);

  // 3. Gemini ile tam analiz (Çeviri, Tanım, Tür)
  if (!process.env.API_KEY) {
     return {
        word: word,
        meanings: [{ 
          partOfSpeech: "word", 
          translation: turkishTranslation || word, 
          definition: "AI analizi için API anahtarı eksik.", 
          example: contextSentence 
        }]
     };
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // Gemini'den hem çeviriyi hem tanımı tek seferde istiyoruz (Daha hızlı ve stabil)
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Kelime: "${word}"
Cümle: "${contextSentence}"

Görev: Bu kelimenin bu cümledeki anlamına göre Türkçe çevirisini, kısa İngilizce tanımını ve kelime türünü (noun/verb/adj vb.) ver.

YALNIZCA şu formatta JSON döndür:
{
  "tr": "Türkçe çeviri",
  "en": "Short English definition",
  "pos": "noun/verb/adj/adv"
}`,
      config: {
        responseMimeType: "application/json",
        temperature: 0.1
      }
    });

    const data = JSON.parse(response.text || '{}');

    // DeepL çalıştıysa onu kullan, çalışmadıysa Gemini'nin çevirisini kullan
    const finalTr = turkishTranslation || data.tr || word;

    const result: DefinitionResponse = {
      word: word,
      meanings: [{
        partOfSpeech: data.pos || 'unknown',
        translation: finalTr,
        definition: data.en || "Tanım bulunamadı.",
        example: contextSentence
      }]
    };

    sessionCache[normalized] = result;
    return result;
  } catch (err) {
    console.error("Gemini Analiz Hatası:", err);
    return {
      word: word,
      meanings: [{ 
        partOfSpeech: "unknown", 
        translation: turkishTranslation || word, 
        definition: "Bağlamsal analiz yapılamadı.", 
        example: contextSentence 
      }]
    };
  }
};

import { Book, User, VocabularyWord, BookStatus, PlanConfig } from '../types';
