            return docSnap.exists ? docSnap.data()?.progress : {};
        },
        () => {
            const progStr = localStorage.getItem(LOCAL_KEYS.PROGRESS_PREFIX + userId);
            return progStr ? JSON.parse(progStr) : {};
        }
