import { GoogleGenAI } from "@google/genai";
import { DefinitionResponse } from "../types";

// Note: process.env.API_KEY is for Google Gemini. 
const DEEPL_API_KEY = "0f41027e-c3e5-4402-9b2e-7128debdd878:fx";
const DEEPL_API_URL = "https://api-free.deepl.com/v2/translate";

// Kelime türlerini Türkçeleştirmek için eşleme tablosu
const posMap: Record<string, string> = {
  'noun': 'İsim',
  'verb': 'Fiil',
  'adjective': 'Sıfat',
  'adj': 'Sıfat',
  'adverb': 'Zarf',
  'adv': 'Zarf',
  'pronoun': 'Zamir',
  'preposition': 'Edat',
  'conjunction': 'Bağlaç',
  'interjection': 'Ünlem',
  'unknown': 'Bilinmiyor',
  'word': 'Kelime'
};

const translatePos = (pos: string): string => {
  const p = pos.toLowerCase().trim();
  return posMap[p] || pos;
};

// Session-based cache for maximum performance
let sessionCache: Record<string, DefinitionResponse> = {};

/**
 * DeepL API üzerinden yüksek hassasiyetli çeviri dener.
 */
async function fetchDeepLTranslation(text: string): Promise<string | null> {
  if (!text || text.length === 0) return null;

  try {
    const params = new URLSearchParams();
    params.append('text', text);
    params.append('target_lang', 'TR');

    const response = await fetch(DEEPL_API_URL, {
      method: 'POST',
      headers: {
        'Authorization': `DeepL ${DEEPL_API_KEY}`,
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      body: params.toString()
    });

    if (!response.ok) {
      return null;
    }

    const data = await response.json();
    return data.translations?.[0]?.text || null;
  } catch (error) {
    console.debug("DeepL erişimi kısıtlı (CORS). Gemini kullanılacak.");
    return null;
  }
}

/**
 * Ana Fonksiyon: DeepL + Gemini Bağlamsal Analiz
 */
export const getWordDefinition = async (word: string, contextSentence: string): Promise<DefinitionResponse> => {
  const normalized = word.toLowerCase().trim().replace(/[^\w]/g, '');

  if (sessionCache[normalized]) {
    return sessionCache[normalized];
  }

  // DeepL'den hızlı çeviri dener
  let turkishTranslation = await fetchDeepLTranslation(word);

  if (!process.env.API_KEY) {
     return {
        word: word,
        meanings: [{ 
          partOfSpeech: "Kelime", 
          translation: turkishTranslation || word, 
          definition: "Analiz için Gemini API anahtarı gerekli.", 
          example: contextSentence 
        }]
     };
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // Gemini'den hem çeviriyi hem tanımı tek seferde istiyoruz
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Kelime: "${word}"
Cümle içindeki kullanımı: "${contextSentence}"

Görev: Bu kelimenin bu cümledeki anlamına göre Türkçe çevirisini, kısa İngilizce tanımını ve kelime türünü (isim, fiil, sıfat, zarf) ver.

YALNIZCA şu formatta JSON döndür:
{
  "tr": "Türkçe çeviri",
  "en": "Short English definition",
  "pos": "isim/fiil/sıfat/zarf"
}`,
      config: {
        responseMimeType: "application/json",
        temperature: 0.1
      }
    });

    const data = JSON.parse(response.text || '{}');

    // POS değerini kontrol et ve Türkçeleştir
    const finalPos = translatePos(data.pos || 'unknown');
    const finalTr = turkishTranslation || data.tr || word;

    const result: DefinitionResponse = {
      word: word,
      meanings: [{
        partOfSpeech: finalPos,
        translation: finalTr,
        definition: data.en || "Tanım bulunamadı.",
        example: contextSentence
      }]
    };

    sessionCache[normalized] = result;
    return result;
  } catch (err) {
    console.error("Gemini Analiz Hatası:", err);
    return {
      word: word,
      meanings: [{ 
        partOfSpeech: "Bilinmiyor", 
        translation: turkishTranslation || word, 
        definition: "Bağlamsal analiz yapılamadı.", 
        example: contextSentence 
      }]
    };
  }
};
