import { GoogleGenAI } from "@google/genai";
import { DefinitionResponse } from "../types";

// DeepL Free API Ayarları
const DEEPL_API_KEY = "0f41027e-c3e5-4402-9b2e-7128debdd878:fx";
const DEEPL_API_URL = "https://api-free.deepl.com/v2/translate";

// Kelime türlerini Türkçeleştirmek için kapsamlı eşleme tablosu
const posMap: Record<string, string> = {
  'noun': 'İsim',
  'isim': 'İsim',
  'verb': 'Fiil',
  'fiil': 'Fiil',
  'adjective': 'Sıfat',
  'adj': 'Sıfat',
  'sıfat': 'Sıfat',
  'adverb': 'Zarf',
  'adv': 'Zarf',
  'zarf': 'Zarf',
  'pronoun': 'Zamir',
  'zamir': 'Zamir',
  'preposition': 'Edat',
  'edat': 'Edat',
  'conjunction': 'Bağlaç',
  'bağlaç': 'Bağlaç',
  'interjection': 'Ünlem',
  'ünlem': 'Ünlem',
  'unknown': 'Bilinmiyor',
  'bilinmiyor': 'Bilinmiyor',
  'word': 'Kelime'
};

/**
 * Kelime türünü (Part of Speech) kullanıcı dostu Türkçe karşılığına çevirir.
 */
export const translatePos = (pos: string | undefined): string => {
  if (!pos) return 'Kelime';
  const p = pos.toLowerCase().trim();
  return posMap[p] || (p.charAt(0).toUpperCase() + p.slice(1));
};

// Performans için oturum bazlı önbellek
let sessionCache: Record<string, DefinitionResponse> = {};

/**
 * DeepL API üzerinden çeviri dener. 
 * Not: Tarayıcı ortamında DeepL API doğrudan çağrıldığında CORS hatası verebilir.
 */
async function fetchDeepLTranslation(text: string): Promise<string | null> {
  if (!text || text.length === 0) return null;

  try {
    const params = new URLSearchParams();
    params.append('auth_key', DEEPL_API_KEY);
    params.append('text', text);
    params.append('target_lang', 'TR');

    const response = await fetch(DEEPL_API_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      body: params.toString()
    });

    if (!response.ok) return null;

    const data = await response.json();
    return data.translations?.[0]?.text || null;
  } catch (error) {
    // CORS kısıtlaması durumunda sessizce Gemini'ye devrediyoruz
    return null;
  }
}

/**
 * Gemini ve DeepL kullanarak bağlamsal analiz yapar.
 */
export const getWordDefinition = async (word: string, contextSentence: string): Promise<DefinitionResponse> => {
  const normalized = word.toLowerCase().trim().replace(/[^\w]/g, '');

  if (sessionCache[normalized]) {
    return sessionCache[normalized];
  }

  // DeepL'den hızlı çeviri dener
  let turkishTranslation = await fetchDeepLTranslation(word);

  // Gemini API Anahtarı kontrolü
  if (!process.env.API_KEY) {
     return {
        word: word,
        meanings: [{ 
          partOfSpeech: "Kelime", 
          translation: turkishTranslation || word, 
          definition: "Analiz için Gemini API anahtarı gerekli.", 
          example: contextSentence 
        }]
     };
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // Gemini'den bağlamsal analiz istenir
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Kelime: "${word}"
Cümle içindeki kullanımı: "${contextSentence}"

Görev: Bu kelimenin bu cümledeki anlamına göre Türkçe çevirisini, kısa İngilizce tanımını ve kelime türünü (noun, verb, adjective, adverb) ver.

YALNIZCA şu formatta JSON döndür:
{
  "tr": "Türkçe çeviri",
  "en": "Short English definition",
  "pos": "noun/verb/adjective/adverb"
}`,
      config: {
        responseMimeType: "application/json",
        temperature: 0.1
      }
    });

    const data = JSON.parse(response.text || '{}');

    // Tür ismini Türkçeleştir
    const finalPos = translatePos(data.pos);
    const finalTr = turkishTranslation || data.tr || word;

    const result: DefinitionResponse = {
      word: word,
      meanings: [{
        partOfSpeech: finalPos,
        translation: finalTr,
        definition: data.en || "Tanım bulunamadı.",
        example: contextSentence
      }]
    };

    sessionCache[normalized] = result;
    return result;
  } catch (err) {
    console.error("Gemini Analiz Hatası:", err);
    return {
      word: word,
      meanings: [{ 
        partOfSpeech: "Bilinmiyor", 
        translation: turkishTranslation || word, 
        definition: "Bağlamsal analiz yapılamadı.", 
        example: contextSentence 
      }]
    };
  }
};

