import { GoogleGenAI } from "@google/genai";
import { DefinitionResponse } from "../types";

// DeepL Free API Ayarları
const DEEPL_API_KEY = "0f41027e-c3e5-4402-9b2e-7128debdd878:fx";
const DEEPL_API_URL = "https://api-free.deepl.com/v2/translate";

// CORS Politikasını aşmak için kullanılacak proxy
const CORS_PROXY = "https://corsproxy.io/?";

// Kelime türlerini Türkçeleştirmek için kapsamlı eşleme tablosu
const posMap: Record<string, string> = {
  'noun': 'İsim',
  'verb': 'Fiil',
  'adjective': 'Sıfat',
  'adj': 'Sıfat',
  'adverb': 'Zarf',
  'adv': 'Zarf',
  'pronoun': 'Zamir',
  'preposition': 'Edat',
  'conjunction': 'Bağlaç',
  'interjection': 'Ünlem',
  'unknown': 'Kelime',
  'word': 'Kelime'
};

/**
 * Kelime türünü (POS) kullanıcı dostu Türkçe karşılığına çevirir.
 */
export const translatePos = (pos: string | undefined): string => {
  if (!pos) return 'Kelime';
  const p = pos.toLowerCase().trim();
  // Eğer zaten Türkçeyse direkt döndür
  if (Object.values(posMap).includes(p.charAt(0).toUpperCase() + p.slice(1))) {
      return p.charAt(0).toUpperCase() + p.slice(1);
  }
  return posMap[p] || (p.charAt(0).toUpperCase() + p.slice(1));
};

// Performans için oturum bazlı önbellek
let sessionCache: Record<string, DefinitionResponse> = {};

/**
 * DeepL API üzerinden çeviri dener (CORS Proxy kullanarak).
 */
async function fetchDeepLTranslation(text: string): Promise<string | null> {
  if (!text || text.length === 0) return null;

  try {
    const params = new URLSearchParams();
    params.append('auth_key', DEEPL_API_KEY);
    params.append('text', text);
    params.append('target_lang', 'TR');

    // CORS Proxy kullanarak DeepL'i tarayıcıdan çağırıyoruz
    const proxyUrl = `${CORS_PROXY}${encodeURIComponent(DEEPL_API_URL)}`;

    const response = await fetch(proxyUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      body: params.toString()
    });

    if (!response.ok) return null;

    const data = await response.json();
    return data.translations?.[0]?.text || null;
  } catch (error) {
    console.debug("DeepL Proxy Hatası veya Kısıtlaması. Gemini kullanılacak.");
    return null;
  }
}

/**
 * Gemini ve DeepL kullanarak bağlamsal analiz yapar.
 */
export const getWordDefinition = async (word: string, contextSentence: string): Promise<DefinitionResponse> => {
  const normalized = word.toLowerCase().trim().replace(/[^\w]/g, '');

  if (sessionCache[normalized]) {
    return sessionCache[normalized];
  }

  // DeepL'den çeviri dener (Hızlı sonuç için)
  let quickTranslation = await fetchDeepLTranslation(word);

  if (!process.env.API_KEY) {
     return {
        word: word,
        meanings: [{ 
          partOfSpeech: "Kelime", 
          translation: quickTranslation || word, 
          definition: "Analiz için Gemini API anahtarı gerekli.", 
          example: contextSentence 
        }]
     };
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // Gemini'den bağlamsal analiz istenir (Gemini çeviriyi DeepL'den daha zeki yapar)
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Word: "${word}"
Used in sentence: "${contextSentence}"

Task: Provide the context-aware Turkish translation for this word, its short English definition, and its word type (noun, verb, adjective, or adverb).

RETURN ONLY JSON:
{
  "tr": "Turkish translation (most suitable for the sentence)",
  "en": "Short English definition",
  "pos": "noun/verb/adjective/adverb"
}`,
      config: {
        responseMimeType: "application/json",
        temperature: 0.1
      }
    });

    const data = JSON.parse(response.text || '{}');

    // Tür ismini Türkçeleştir
    const finalPos = translatePos(data.pos);

    // Eğer Gemini'nin bağlamsal çevirisi varsa onu kullan, yoksa DeepL'i kullan
    const finalTr = data.tr || quickTranslation || word;

    const result: DefinitionResponse = {
      word: word,
      meanings: [{
        partOfSpeech: finalPos,
        translation: finalTr,
        definition: data.en || "Definition not found.",
        example: contextSentence
      }]
    };

    sessionCache[normalized] = result;
    return result;
  } catch (err) {
    console.error("Gemini Analysis Error:", err);
    return {
      word: word,
      meanings: [{ 
        partOfSpeech: "Kelime", 
        translation: quickTranslation || word, 
        definition: "Bağlamsal analiz şu an yapılamıyor.", 
        example: contextSentence 
      }]
    };
  }
};

