import { GoogleGenAI } from "@google/genai";
import { DefinitionResponse } from "../types";

// Kelime türlerini Türkçeleştirmek için eşleme tablosu
const posMap: Record<string, string> = {
  'noun': 'İsim',
  'verb': 'Fiil',
  'adjective': 'Sıfat',
  'adj': 'Sıfat',
  'adverb': 'Zarf',
  'adv': 'Zarf',
  'pronoun': 'Zamir',
  'preposition': 'Edat',
  'conjunction': 'Bağlaç',
  'interjection': 'Ünlem',
  'unknown': 'Kelime',
  'word': 'Kelime'
};

/**
 * Kelime türünü Türkçe karşılığına çevirir.
 */
export const translatePos = (pos: string | undefined): string => {
  if (!pos) return 'Kelime';
  const p = pos.toLowerCase().trim();
  if (Object.values(posMap).includes(p.charAt(0).toUpperCase() + p.slice(1))) {
      return p.charAt(0).toUpperCase() + p.slice(1);
  }
  return posMap[p] || (p.charAt(0).toUpperCase() + p.slice(1));
};

// Önbellek (Performans için)
let sessionCache: Record<string, DefinitionResponse> = {};

/**
 * Gemini 3 Flash kullanarak bağlamsal çeviri ve analiz yapar.
 */
export const getWordDefinition = async (word: string, contextSentence: string): Promise<DefinitionResponse> => {
  const normalized = word.toLowerCase().trim().replace(/[^\w]/g, '');

  if (sessionCache[normalized]) {
    return sessionCache[normalized];
  }

  if (!process.env.API_KEY) {
     return {
        word: word,
        meanings: [{ 
          partOfSpeech: "Hata", 
          translation: word, 
          definition: "Lütfen API anahtarınızı kontrol edin.", 
          example: contextSentence 
        }]
     };
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Word: "${word}"
Sentence context: "${contextSentence}"

Task: Translate this word to Turkish based on its context in the sentence. Provide a short English definition and its part of speech.

RETURN ONLY THIS JSON FORMAT:
{
  "tr": "Turkish translation",
  "en": "Short English definition",
  "pos": "noun/verb/adjective/adverb"
}`,
      config: {
        responseMimeType: "application/json",
        temperature: 0.1
      }
    });

    const textOutput = response.text;
    if (!textOutput) throw new Error("API'den yanıt alınamadı.");

    const data = JSON.parse(textOutput);

    const result: DefinitionResponse = {
      word: word,
      meanings: [{
        partOfSpeech: translatePos(data.pos),
        translation: data.tr || word,
        definition: data.en || "Tanım bulunamadı.",
        example: contextSentence
      }]
    };

    sessionCache[normalized] = result;
    return result;
  } catch (err: any) {
    console.error("Gemini Çeviri Hatası:", err);

    // Kota aşımı kontrolü (HTTP 429)
    const isQuotaError = err.message?.includes('429') || err.message?.includes('RESOURCE_EXHAUSTED');

    return {
      word: word,
      meanings: [{ 
        partOfSpeech: "Sistem", 
        translation: word, 
        definition: isQuotaError 
          ? "Günlük ücretsiz çeviri limitiniz doldu. Lütfen yarın tekrar deneyin veya kendi API anahtarınızı kullanın."
          : "Şu an çeviri yapılamıyor. Lütfen internet bağlantınızı kontrol edin.", 
        example: contextSentence 
      }]
    };
  }
};

