import { GoogleGenAI } from "@google/genai";
import { DefinitionResponse } from "../types";

// Genişletilmiş ve hassaslaştırılmış eşleme tablosu
const posMap: Record<string, string> = {
  'noun': 'İsim',
  'verb': 'Fiil',
  'adjective': 'Sıfat',
  'adj': 'Sıfat',
  'adverb': 'Zarf',
  'adv': 'Zarf',
  'pronoun': 'Zamir',
  'preposition': 'Edat',
  'conjunction': 'Bağlaç',
  'interjection': 'Ünlem',
  'phrasal verb': 'Deyimsel Fiil',
  'gerund': 'İsim-Fiil',
  'participle': 'Ortaç',
  'determiner': 'Belirleyici',
  'article': 'Tanımlık',
  'number': 'Sayı',
  'unknown': 'Kelime',
  'word': 'Kelime'
};

/**
 * Sözcük türünü normalize eder ve Türkçe karşılığını döndürür.
 */
export const translatePos = (pos: string | undefined): string => {
  if (!pos) return 'Kelime';

  // Temizlik ve normalizasyon
  const p = pos.toLowerCase().trim().replace(/[^a-z ]/g, '');

  // Doğrudan eşleşme kontrolü
  if (posMap[p]) return posMap[p];

  // Kısmi eşleşme kontrolü (örn: "proper noun" -> "noun")
  for (const key in posMap) {
    if (p.includes(key)) return posMap[key];
  }

  // Hiçbir şey bulunamazsa gelen veriyi formatla
  return p.charAt(0).toUpperCase() + p.slice(1);
};

let sessionCache: Record<string, DefinitionResponse> = {};

/**
 * Gemini 3 Flash kullanarak bağlamsal analiz yapar.
 */
export const getWordDefinition = async (word: string, contextSentence: string): Promise<DefinitionResponse> => {
  const normalized = word.toLowerCase().trim().replace(/[^\w]/g, '');

  if (sessionCache[normalized]) {
    return sessionCache[normalized];
  }

  if (!process.env.API_KEY) {
     return {
        word: word,
        meanings: [{ 
          partOfSpeech: "Hata", 
          translation: word, 
          definition: "Lütfen API anahtarınızı kontrol edin.", 
          example: contextSentence 
        }]
     };
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // Prompt, dilbilgisi rolüne odaklanacak şekilde güncellendi
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Context: "${contextSentence}"
Target Word: "${word}"

Analyze the target word based strictly on its grammatical role in the context sentence provided above.

Return ONLY JSON:
{
  "tr": "Turkish translation matching the context",
  "en": "Short English definition",
  "pos": "precise part of speech (e.g. noun, verb, phrasal verb, adjective, etc.)"
}`,
      config: {
        responseMimeType: "application/json",
        temperature: 0.1 // Daha tutarlı sonuçlar için düşük sıcaklık
      }
    });

    const textOutput = response.text;
    if (!textOutput) throw new Error("API'den yanıt alınamadı.");

    const data = JSON.parse(textOutput);

    const result: DefinitionResponse = {
      word: word,
      meanings: [{
        partOfSpeech: translatePos(data.pos),
        translation: data.tr || word,
        definition: data.en || "Tanım bulunamadı.",
        example: contextSentence
      }]
    };

    sessionCache[normalized] = result;
    return result;
  } catch (err: any) {
    console.error("Gemini Çeviri Hatası:", err);

    const isQuotaError = err.message?.includes('429') || err.message?.includes('RESOURCE_EXHAUSTED');

    return {
      word: word,
      meanings: [{ 
        partOfSpeech: "Sistem", 
        translation: word, 
        definition: isQuotaError 
          ? "Limit doldu. Lütfen biraz sonra tekrar deneyin."
          : "Çeviri şu an yapılamıyor.", 
        example: contextSentence 
      }]
    };
  }
};

