const posMap: Record<string, string> = {
  'noun': 'İsim',
  'verb': 'Fiil',
  'adjective': 'Sıfat',
  'adj': 'Sıfat',
  'adverb': 'Zarf',
  'adv': 'Zarf',
  'pronoun': 'Zamir',
  'preposition': 'Edat',
  'conjunction': 'Bağlaç',
  'interjection': 'Ünlem',
  'phrasal verb': 'Deyimsel Fiil',
  'gerund': 'İsim-Fiil',
  'participle': 'Ortaç',
  'determiner': 'Belirleyici',
  'article': 'Tanımlık',
  'number': 'Sayı',
  'unknown': 'Kelime',
  'word': 'Kelime'
};

export const translatePos = (pos: string | undefined): string => {
  if (!pos) return 'Kelime';
  const p = pos.toLowerCase().trim().replace(/[^a-z ]/g, '');
  if (posMap[p]) return posMap[p];
  for (const key in posMap) {
    if (p.includes(key)) return posMap[key];
  }
  return p.charAt(0).toUpperCase() + p.slice(1);
};

/**
 * Kelime çevirisini kalıcı önbellekten, DeepL'den veya Gemini'den getirir.
 * Sıralama: Cache -> DeepL -> Gemini
 */
export const getWordDefinition = async (word: string, contextSentence: string): Promise<DefinitionResponse> => {
  const normalized = word.toLowerCase().trim().replace(/[^\w]/g, '');

  // 1. ADIM: Kalıcı Önbelleği Kontrol Et (Maksimum Hız)
  const cached = await getCachedDefinition(normalized);
  if (cached) {
    if (cached.meanings && cached.meanings[0]) {
        cached.meanings[0].example = contextSentence;
    }
    return cached;
  }

  // 2. ADIM: DeepL ile Hızlı Çeviri (Yüksek Kalite & Hız)
  try {
      const deepLResult = await translateWithDeepL(word, contextSentence);
      if (deepLResult) {
          const result: DefinitionResponse = {
              word: word,
              meanings: [{
                  partOfSpeech: 'Kelime', // DeepL gramer bilgisi sağlamaz, genel atanır
                  translation: deepLResult,
                  definition: 'Çeviri DeepL ile yapıldı.', // İngilizce tanım sağlanmaz
                  example: contextSentence
              }]
          };

          // Sonucu önbelleğe kaydet
          await saveDefinitionToCache(normalized, result);
          return result;
      }
  } catch (deepLError) {
      console.warn("DeepL işleminde sorun oluştu, Gemini deneniyor...", deepLError);
  }

  // 3. ADIM: DeepL çalışmazsa Gemini'yi kullan (Fallback)
  if (!process.env.API_KEY) {
     return {
        word: word,
        meanings: [{ 
          partOfSpeech: "Hata", 
          translation: word, 
          definition: "API anahtarı eksik.", 
