// Bu yüzden manuel haritalama şimdilik pasif, ancak arayüz hatası vermemesi için tutuyoruz.
const posMap: Record<string, string> = {
  'noun': 'İsim',
  'verb': 'Fiil',
  'adjective': 'Sıfat',
  'adverb': 'Zarf',
  'pronoun': 'Zamir',
  'preposition': 'Edat',
  'conjunction': 'Bağlaç',
  'interjection': 'Ünlem',
  'unknown': 'Kelime',
  'word': 'Kelime'
};

export const translatePos = (pos: string | undefined): string => {
  if (!pos) return 'Kelime';
  if (Object.values(posMap).includes(pos)) return pos;
  const p = pos.toLowerCase().trim();
  return posMap[p] || 'Kelime';
};

/**
 * SADECE Google Translate API kullanılarak kelime çevirisi yapılır.
 * Gemini AI devre dışı bırakılmıştır.
 */
export const getWordDefinition = async (word: string, contextSentence: string): Promise<DefinitionResponse> => {
  const normalized = word.toLowerCase().trim().replace(/[^\w]/g, '');

  // 1. Önce Önbelleğe Bak (Hız ve Maliyet Tasarrufu)
  const cached = await getCachedDefinition(normalized);
  if (cached) {
    if (cached.meanings && cached.meanings[0]) {
        cached.meanings[0].example = contextSentence;
    }
    return cached;
  }

  // 2. Google Cloud Translation API Çağrısı
  try {
      const googleTranslation = await translateWithGoogle(word);

      if (googleTranslation) {
          const result: DefinitionResponse = {
              word: word,
              meanings: [{
                  partOfSpeech: 'Kelime', // Basic API tür bilgisi vermez
                  translation: googleTranslation,
                  definition: 'Google Translate Çevirisi', // Basic API İngilizce tanım vermez
                  example: contextSentence
              }]
          };

          // Sonucu kaydet
          await saveDefinitionToCache(normalized, result);
          return result;
      }
  } catch (googleError) {
      console.error("Google Translate Servisi Hatası:", googleError);
  }

  // 3. Hata Durumu
  return {
    word: word,
    meanings: [{ 
      partOfSpeech: "Hata", 
      translation: word, 
      definition: "Çeviri servisine ulaşılamadı.", 
      example: contextSentence 
    }]
  };
};

