export const translateWithGoogle = async (text: string): Promise<string | null> => {
  if (!text) return null;

  try {
    const response = await fetch(`${GOOGLE_TRANSLATE_API_URL}?key=${GOOGLE_TRANSLATE_API_KEY}`, {
      method: 'POST',
