  const normalized = word.toLowerCase().trim().replace(/[^\w]/g, '');

  // 1. Önce Önbelleğe Bak
  const cached = await getCachedDefinition(normalized);
  if (cached) {
    if (cached.meanings && cached.meanings[0]) {
        cached.meanings[0].example = contextSentence;
    }
    return cached;
  }

  // 2. Google Translate API Çağrısı
  try {
      const googleTranslation = await translateWithGoogle(word);

      const result: DefinitionResponse = {
          word: word,
          meanings: [{
              partOfSpeech: 'Kelime',
              translation: googleTranslation,
              definition: 'Çeviri (Google Translate)',
              example: contextSentence
          }]
      };

      await saveDefinitionToCache(normalized, result);
      return result;

  } catch (error: any) {
      console.error("Translation Service Error:", error);

      let errorTitle = "Çeviri Hatası";
      let errorDesc = "Çeviri servisine şu an ulaşılamıyor.";

      // Hata mesajı 'blocked' içeriyorsa kullanıcıya (geliştiriciye) yol göster
      if (error.message && error.message.includes('blocked')) {
          errorTitle = "API Erişimi Engellendi";
          errorDesc = "Google Cloud Console'da 'Cloud Translation API' etkinleştirilmeli ve faturalandırma hesabı bağlanmalıdır. (Hata Detayı: " + error.message + ")";
      } else if (error.message) {
          errorDesc = error.message;
