      // Hata durumunda UI bozulmaması için hata kartı döndür
      return {
        word: word,
        meanings: [{ 
          partOfSpeech: "⚠️ " + errorTitle, 
          translation: "---", 
          definition: errorDesc, 
          example: contextSentence 
        }]
      };
  }
};

