import { DefinitionResponse } from "../types";
import { getCachedDefinition, saveDefinitionToCache } from "./storage";
import { translateWithGoogle } from "./googleTranslateService";

const posMap: Record<string, string> = {
  'noun': 'İsim',
  'verb': 'Fiil',
  'adjective': 'Sıfat',
  'adverb': 'Zarf',
  'pronoun': 'Zamir',
  'preposition': 'Edat',
  'conjunction': 'Bağlaç',
  'interjection': 'Ünlem',
  'unknown': 'Kelime',
  'word': 'Kelime'
};

export const translatePos = (pos: string | undefined): string => {
  if (!pos) return 'Kelime';
  if (Object.values(posMap).includes(pos)) return pos;
  const p = pos.toLowerCase().trim();
  return posMap[p] || 'Kelime';
};

export const getWordDefinition = async (word: string, contextSentence: string): Promise<DefinitionResponse> => {
  const normalized = word.toLowerCase().trim().replace(/[^\w]/g, '');

  // 1. Önce Önbelleğe Bak
  const cached = await getCachedDefinition(normalized);
  if (cached) {
    if (cached.meanings && cached.meanings[0]) {
        cached.meanings[0].example = contextSentence;
    }
    return cached;
  }

  // 2. Google Translate API Çağrısı
  try {
      const googleTranslation = await translateWithGoogle(word);

      // AI Görsel URL oluştur (Pollinations.ai kullanarak)
      const seed = Math.floor(Math.random() * 1000);
      const imageUrl = `https://image.pollinations.ai/prompt/minimalist%20cute%20illustration%20of%20${encodeURIComponent(word)}?width=400&height=300&nologo=true&seed=${seed}`;

      const result: DefinitionResponse = {
          word: word,
          imageUrl: imageUrl,
          meanings: [{
              partOfSpeech: 'Kelime',
              translation: googleTranslation,
              definition: 'Çeviri (Google Translate)',
              example: contextSentence
          }]
      };

      await saveDefinitionToCache(normalized, result);
      return result;

  } catch (error: any) {
      console.error("Translation Service Error:", error);

      // Hata durumunda sessizce basit bir obje döndür, korkutucu uyarılar gösterme.
      return {
        word: word,
        meanings: [{ 
          partOfSpeech: "Kelime", 
          translation: "...", 
          definition: "Bağlantı sorunu.", 
          example: contextSentence 
        }]
      };
  }
};

