import React, { useState, useRef, useEffect } from 'react';
import { Book, VocabularyWord } from '../types';
import { getWordDefinition, prefetchBookContent, translatePos } from '../services/geminiService';
import { ArrowLeft, Loader2, Star, Volume2, X, CheckCircle, ZoomIn, ZoomOut, Type, ArrowRight, BookOpen } from 'lucide-react';

interface BookReaderProps {
  book: Book;
  initialChapterIndex: number;
  onBack: () => void;
  onSaveWord: (word: VocabularyWord) => void;
  savedWords: VocabularyWord[];
  onCompleteChapter: (bookId: string, chapterIndex: number) => void;
}

interface SelectionState {
  word: string;
  context: string;
  x: number;
  y: number;
}

const FONTS = [
  { name: 'Sans', class: 'font-sans' },
  { name: 'Serif', class: 'font-serif' },
  { name: 'Mono', class: 'font-mono' },
];

const BookReader: React.FC<BookReaderProps> = ({ book, initialChapterIndex, onBack, onSaveWord, savedWords, onCompleteChapter }) => {
  const [currentChapterIndex, setCurrentChapterIndex] = useState(initialChapterIndex);
  const [selection, setSelection] = useState<SelectionState | null>(null);
  const [isLoadingDef, setIsLoadingDef] = useState(false);
  const [definition, setDefinition] = useState<any>(null);
  const textRef = useRef<HTMLDivElement>(null);

  const [fontSize, setFontSize] = useState(19);
  const [currentFont, setCurrentFont] = useState(FONTS[0].class);
  const [showFontMenu, setShowFontMenu] = useState(false);

  const currentChapter = book.chapters[currentChapterIndex];
  const isLastChapter = currentChapterIndex === book.chapters.length - 1;

  useEffect(() => {
    // Scroll to top when chapter changes
    window.scrollTo(0, 0);
    prefetchBookContent(currentChapter.content);
  }, [currentChapterIndex, book.id]);

  const tokenizeText = (text: string) => {
    return text.match(/([\w’']+)|([^\w\s]+)|(\s+)/g) || [];
  };

  const handleWordClick = async (word: string, event: React.MouseEvent) => {
    if (!/\w/.test(word)) return;

    const rect = (event.target as HTMLElement).getBoundingClientRect();
    const x = Math.max(16, Math.min(rect.left + rect.width/2 - 160, window.innerWidth - 336)); 
    const y = rect.bottom + window.scrollY + 12;

    const fullSentence = getSentenceContext(currentChapter.content, word);

    setSelection({ word, context: fullSentence, x, y });
    setDefinition(null);
    setIsLoadingDef(true);

    try {
        const def = await getWordDefinition(word, fullSentence);
        setDefinition(def);
    } catch (err) {
        console.error("Dictionary Fetch Failed:", err);
    } finally {
        setIsLoadingDef(false);
    }
  };

  const getSentenceContext = (text: string, word: string) => {
    const index = text.indexOf(word);
    if (index === -1) return "";
    const start = Math.max(0, text.lastIndexOf('.', index) + 1);
    let end = text.indexOf('.', index);
    if (end === -1) end = text.length;
    return text.slice(start, end + 1).trim();
  };

  const handleSave = () => {
    if (!definition || !selection) return;

    const newWord: VocabularyWord = {
      id: Date.now().toString(),
      word: selection.word,
      translation: definition.meanings[0].translation,
      definition: definition.meanings[0].definition,
      exampleSentence: selection.context,
      type: definition.meanings[0].partOfSpeech, // Already translated in service
      level: book.level,
      sourceBookId: book.id,
      nextReviewDate: new Date(),
      strength: 0
    };

    onSaveWord(newWord);
    setSelection(null); 
  };

  const isSaved = (word: string) => {
    const norm = word.toLowerCase().trim();
    return savedWords.some(w => w.word.toLowerCase().trim() === norm);
  };

  const playAudio = (text: string) => {
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'en-US';
    window.speechSynthesis.speak(utterance);
  };

  const handleNext = () => {
    onCompleteChapter(book.id, currentChapterIndex);
    if (isLastChapter) {
        onBack(); // Go back to Chapter List (which will now show 100%)
    } else {
        setCurrentChapterIndex(prev => prev + 1);
    }
  };

  const paragraphs = currentChapter.content.split('\n').filter(p => p.trim() !== '');

  return (
    <div className="relative min-h-screen bg-[#fdfdfd] dark:bg-gray-950 pb-24">
      {/* Reader Controls */}
      <div className="sticky top-0 bg-white/90 dark:bg-gray-900/90 backdrop-blur-xl border-b border-gray-100 dark:border-gray-800 px-6 py-4 flex items-center justify-between z-30">
        <button onClick={onBack} className="flex items-center text-gray-600 hover:text-brand-600 dark:text-gray-300 font-bold transition-all">
          <ArrowLeft className="mr-2" size={20} />
          <span>Bölümler</span>
        </button>

        <div className="flex items-center gap-3">
          <div className="flex bg-gray-100 dark:bg-gray-800 rounded-xl p-1">
             <button onClick={() => setFontSize(Math.max(12, fontSize - 2))} className="p-2 text-gray-500 hover:text-brand-600"><ZoomOut size={16} /></button>
             <span className="px-2 flex items-center text-[10px] font-black text-gray-400 border-x border-gray-200 dark:border-gray-700">{fontSize}px</span>
             <button onClick={() => setFontSize(Math.min(42, fontSize + 2))} className="p-2 text-gray-500 hover:text-brand-600"><ZoomIn size={16} /></button>
          </div>
          <button 
            onClick={() => setShowFontMenu(!showFontMenu)} 
            className={`p-2 rounded-xl transition-all ${showFontMenu ? 'bg-brand-600 text-white' : 'bg-gray-100 dark:bg-gray-800 text-gray-500'}`}
          >
            <Type size={20} />
          </button>
        </div>
      </div>

      <div className="max-w-3xl mx-auto px-6 py-12">
        {showFontMenu && (
          <div className="mb-8 flex gap-3 justify-center bg-white dark:bg-gray-900 p-3 rounded-2xl shadow-xl border border-gray-100 dark:border-gray-800 animate-in fade-in slide-in-from-top-2">
             {FONTS.map(f => (
               <button 
                key={f.name}
                onClick={() => { setCurrentFont(f.class); setShowFontMenu(false); }}
                className={`px-5 py-2.5 rounded-xl text-sm font-black transition-all ${currentFont === f.class ? 'bg-brand-600 text-white shadow-lg' : 'hover:bg-gray-100 dark:hover:bg-gray-800 dark:text-gray-400'}`}
               >
                 {f.name}
               </button>
             ))}
          </div>
        )}

        <div className="bg-white dark:bg-gray-900 rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-gray-800 p-8 md:p-16">
          <header className="mb-12 text-center border-b border-gray-100 dark:border-gray-800 pb-8">
             <p className="text-brand-600 font-bold uppercase tracking-widest text-xs mb-2">Chapter {currentChapterIndex + 1}</p>
             <h1 className={`text-3xl md:text-4xl font-black text-gray-900 dark:text-white mb-2 ${currentFont}`}>{currentChapter.title}</h1>
             <p className="text-gray-400 text-xs font-black uppercase tracking-[0.3em]">{book.title}</p>
          </header>

          <article 
            ref={textRef} 
            className={`leading-relaxed text-gray-800 dark:text-gray-200 ${currentFont} transition-all duration-300`}
            style={{ fontSize: `${fontSize}px` }}
          >
            {paragraphs.map((paragraph, pIndex) => (
              <p key={pIndex} className="mb-10 text-justify">
                {tokenizeText(paragraph).map((token, index) => {
                  const isWord = /\w/.test(token);
                  const saved = isWord && isSaved(token);
                  const active = selection?.word === token;

                  return isWord ? (
                    <span
                      key={index}
                      onClick={(e) => handleWordClick(token, e)}
                      className={`cursor-pointer transition-all rounded-md px-0.5 inline-block
                        ${saved 
                          ? 'bg-yellow-100 dark:bg-yellow-900/40 text-yellow-900 dark:text-yellow-100 decoration-yellow-400/50 underline decoration-2 underline-offset-4' 
                          : 'hover:bg-brand-50 dark:hover:bg-brand-900/20 hover:text-brand-600'
                        }
                        ${active ? 'bg-brand-600 text-white scale-110 shadow-lg px-2 rounded-lg' : ''}
                      `}
                    >
                      {token}
                    </span>
                  ) : (
                    <span key={index}>{token}</span>
                  );
                })}
              </p>
            ))}
          </article>

          <footer className="mt-20 pt-16 border-t border-gray-50 dark:border-gray-800 text-center">
             <button
               onClick={handleNext}
               className="px-10 py-5 bg-gray-900 dark:bg-brand-600 text-white rounded-[2rem] font-black text-lg hover:scale-105 transition-all shadow-2xl active:scale-95 flex items-center justify-center mx-auto"
             >
               {isLastChapter ? (
                  <> <CheckCircle className="mr-3" /> Kitabı Bitir </>
               ) : (
                  <> Sonraki Bölüm <ArrowRight className="ml-3" /> </>
               )}
             </button>
          </footer>
        </div>
      </div>

      {/* Dictionary Popup */}
      {selection && (
        <>
          <div className="fixed inset-0 z-40 bg-black/5 lg:bg-transparent" onClick={() => setSelection(null)} />
          <div 
            className="fixed z-50 w-[320px] bg-white dark:bg-gray-800 rounded-[2rem] shadow-[0_40px_80px_-15px_rgba(0,0,0,0.2)] border border-gray-100 dark:border-gray-700 overflow-hidden animate-in zoom-in-95 duration-200"
            style={{ 
              top: Math.min(selection.y, window.innerHeight - 350),
              left: selection.x
            }}
          >
            <div className="p-6">
              <header className="flex justify-between items-start mb-2">
                <div>
                   <h3 className="text-2xl font-black text-gray-900 dark:text-white capitalize truncate pr-2">{selection.word}</h3>
                   <span className="text-[10px] font-black uppercase text-gray-400 tracking-wider">İngilizce</span>
                </div>
                <div className="flex gap-1 shrink-0">
                  <button onClick={() => playAudio(selection.word)} className="p-2.5 rounded-full text-brand-600 bg-brand-50 hover:bg-brand-100 transition-all"><Volume2 size={20} /></button>
                  <button onClick={() => setSelection(null)} className="p-2.5 rounded-full text-gray-400 hover:text-red-500 hover:bg-red-50 transition-all"><X size={20} /></button>
                </div>
              </header>

              {isLoadingDef ? (
                <div className="py-8 flex flex-col items-center justify-center">
                  <Loader2 className="animate-spin text-brand-500 mb-3" size={32} strokeWidth={3} />
                  <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">Çevriliyor...</p>
                </div>
              ) : (
                definition && (
                  <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-400">
                    {definition.meanings.map((meaning: any, i: number) => (
                      <div key={i} className="group">
                        <div className="mt-4 mb-4">
                           <span className="text-[10px] font-black uppercase text-brand-600 bg-brand-50 dark:bg-brand-900/30 px-2 py-0.5 rounded-lg mb-1 inline-block">
                            {translatePos(meaning.partOfSpeech)}
                          </span>
                           <div className="font-bold text-3xl text-brand-600 dark:text-brand-400 leading-tight">
                            {meaning.translation}
                          </div>
                        </div>

                        {/* Örnek Cümle ve Çevirisi */}
                        <div className="bg-gray-50 dark:bg-gray-900/50 p-3 rounded-xl border border-gray-100 dark:border-gray-700">
                           <p className="text-[10px] font-black text-gray-400 uppercase mb-1">Örnek Cümle</p>
                           <p className="text-sm text-gray-800 dark:text-gray-200 font-medium italic leading-relaxed mb-2">
                             "{meaning.example}"
                           </p>
                           {meaning.translatedExample && (
                               <p className="text-sm text-brand-600 dark:text-brand-400 font-medium leading-relaxed border-t border-gray-200 dark:border-gray-700 pt-2">
                                 {meaning.translatedExample}
                               </p>
                           )}
                        </div>
                      </div>
                    ))}

                    <button 
                      onClick={handleSave}
                      className={`w-full mt-2 py-4 rounded-xl font-black text-base transition-all
                        ${isSaved(selection.word) 
                          ? 'bg-green-50 text-green-600 shadow-inner' 
                          : 'bg-brand-600 text-white hover:bg-brand-700 shadow-xl shadow-brand-500/20 active:scale-95'}`}
                    >
                      {isSaved(selection.word) ? (
                        <span className="flex items-center justify-center gap-2"><CheckCircle size={18} /> Kaydedildi</span>
                      ) : (
                        <span className="flex items-center justify-center gap-2"><Star size={18} /> Deftere Ekle</span>
                      )}
                    </button>
                  </div>
                )
              )}
            </div>
          </div>
        </>
      )}
    </div>
  );
};

export default BookReader;

import React, { useState, useEffect } from 'react';
import { Book, User, CEFRLevel, PlanConfig, PlanType, SubscriptionStatus, Chapter } from '../types';
import { getBooks, saveBook, deleteBook, getUsers, saveUser, deleteUser, getPlans, savePlans } from '../services/storage';
import { Trash2, Edit, Plus, Users, Book as BookIcon, Save, X, Archive, DollarSign, Lock, CheckSquare, Square, Loader2, Search, List, ChevronRight } from 'lucide-react';
import { t } from '../services/i18n';

interface AdminPanelProps {
  currentUser: User;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ currentUser }) => {
  const [activeTab, setActiveTab] = useState<'BOOKS' | 'USERS' | 'PLANS'>('BOOKS');

  // Data
  const [books, setBooks] = useState<Book[]>([]);
  const [users, setUsersList] = useState<User[]>([]);
  const [plans, setPlansList] = useState<PlanConfig[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  // Search State
  const [userSearchTerm, setUserSearchTerm] = useState('');

  // Forms
  const [isEditingBook, setIsEditingBook] = useState(false);
  const [currentBook, setCurrentBook] = useState<Partial<Book>>({});
  const [activeChapterId, setActiveChapterId] = useState<string | null>(null);

  const [isEditingUser, setIsEditingUser] = useState(false);
  const [targetUser, setTargetUser] = useState<Partial<User>>({});

  const [isEditingPlan, setIsEditingPlan] = useState(false);
  const [targetPlan, setTargetPlan] = useState<Partial<PlanConfig>>({});
  const [planFeaturesText, setPlanFeaturesText] = useState(''); 

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = async () => {
    setIsLoading(true);
    const [b, u, p] = await Promise.all([getBooks(), getUsers(), getPlans()]);
    setBooks(b);
    setUsersList(u);
    setPlansList(p);
    setIsLoading(false);
  };

  // --- Book Handlers ---
  const handleEditBook = (book?: Book) => {
    const initBook = book ? { ...book } : { 
      id: '', title: '', author: '', level: 'A1', coverUrl: 'https://picsum.photos/300/450', chapters: [], excerpt: '', totalWords: 0, requiredPlan: ['FREE'], archived: false 
    };
    setCurrentBook(initBook);

    // Set active chapter to first one if exists
    if (initBook.chapters && initBook.chapters.length > 0) {
      setActiveChapterId(initBook.chapters[0].id);
    } else {
      setActiveChapterId(null);
    }

    setIsEditingBook(true);
  };

  const togglePlanForBook = (plan: PlanType) => {
    const currentPlans = currentBook.requiredPlan || [];
    if (currentPlans.includes(plan)) {
      setCurrentBook({ ...currentBook, requiredPlan: currentPlans.filter(p => p !== plan) });
    } else {
      setCurrentBook({ ...currentBook, requiredPlan: [...currentPlans, plan] });
    }
  };

  // Chapter Logic
  const handleAddChapter = () => {
    const newChapter: Chapter = {
      id: 'c-' + Date.now(),
      title: 'New Chapter',
      content: ''
    };
    const updatedChapters = [...(currentBook.chapters || []), newChapter];
    setCurrentBook({ ...currentBook, chapters: updatedChapters });
    setActiveChapterId(newChapter.id);
  };

  const handleDeleteChapter = (chapterId: string) => {
    if (!confirm("Delete this chapter?")) return;
    const updatedChapters = (currentBook.chapters || []).filter(c => c.id !== chapterId);
    setCurrentBook({ ...currentBook, chapters: updatedChapters });
    if (activeChapterId === chapterId) {
       setActiveChapterId(updatedChapters.length > 0 ? updatedChapters[0].id : null);
    }
  };

  const updateChapter = (id: string, field: keyof Chapter, value: string) => {
     const updatedChapters = (currentBook.chapters || []).map(c => {
        if (c.id === id) return { ...c, [field]: value };
        return c;
     });
     setCurrentBook({ ...currentBook, chapters: updatedChapters });
  };

  const handleSaveBook = async () => {
    if (!currentBook.title || (currentBook.chapters?.length === 0)) return alert("Title and at least one chapter required.");

    // Recalculate total words
    const totalWords = (currentBook.chapters || []).reduce((acc, c) => acc + c.content.split(' ').length, 0);

    const bookToSave: Book = {
      id: currentBook.id || 'b-' + Date.now(),
      title: currentBook.title!,
      author: currentBook.author || 'Unknown',
      level: currentBook.level as CEFRLevel,
      coverUrl: currentBook.coverUrl || '',
      chapters: currentBook.chapters || [],
      excerpt: currentBook.excerpt || (currentBook.chapters?.[0]?.content.substring(0, 100) || ''),
      totalWords: totalWords,
      requiredPlan: currentBook.requiredPlan && currentBook.requiredPlan.length > 0 ? currentBook.requiredPlan : ['FREE'],
      archived: currentBook.archived || false
    };

    await saveBook(bookToSave);
    setIsEditingBook(false);
    refreshData();
  };

  const handleArchiveBook = async (book: Book) => {
    const updatedBook = { ...book, archived: !book.archived };
    await saveBook(updatedBook);
    refreshData();
  };

  const handleDeleteBook = async (id: string) => {
    if (confirm(t('confirmDelete', currentUser.languagePreference))) {
      await deleteBook(id);
      refreshData();
    }
  };

  // --- User Handlers ---
  const handleEditUser = (u?: User) => {
    setTargetUser(u || {
      id: '', name: '', email: '', role: 'USER', password: '', plan: 'FREE', subscriptionStatus: 'ACTIVE'
    });
    setIsEditingUser(true);
  };

  const handleSaveUser = async () => {
    if (!targetUser.email || !targetUser.name) return alert(t('fillAllFields', currentUser.languagePreference));

    // Simple email check for new users
    if (!targetUser.id) {
       const exists = users.find(u => u.email === targetUser.email);
       if(exists) return alert(t('emailExists', currentUser.languagePreference));
    }

    // Determine end date based on plan
    let endAt = targetUser.subscriptionEndsAt || Date.now();
    if (targetUser.plan !== 'FREE') {
       const planConfig = plans.find(p => p.id === targetUser.plan);
       if (planConfig) {
         endAt = Date.now() + (planConfig.durationDays * 24 * 60 * 60 * 1000);
       }
    }

    const userToSave: User = {
      id: targetUser.id || 'u-' + Date.now(),
      email: targetUser.email!,
      name: targetUser.name!,
      // Ensure password isn't lost if input was cleared by accident
      password: targetUser.password || '123456',
      role: (targetUser.role as any) || 'USER',
      languagePreference: targetUser.languagePreference || 'TR',
      streak: targetUser.streak || 0,
      xp: targetUser.xp || 0,
      dailyGoal: targetUser.dailyGoal || 25,
      lastVisitDate: targetUser.lastVisitDate || Date.now(),
      subscriptionStatus: targetUser.subscriptionStatus || 'ACTIVE',
      plan: targetUser.plan || 'FREE',
      trialEndsAt: targetUser.trialEndsAt || 0,
      subscriptionEndsAt: endAt
    };

    await saveUser(userToSave);
    setIsEditingUser(false);
    refreshData();
  };

  const handleDeleteUser = async (id: string) => {
    if (id === currentUser.id) return alert("You cannot delete yourself.");
    if (confirm(t('confirmDelete', currentUser.languagePreference))) {
      await deleteUser(id);
      refreshData();
    }
  };

  // --- Plan Handlers ---
  const handleEditPlan = (p?: PlanConfig) => {
    if (p) {
        setTargetPlan(p);
        setPlanFeaturesText(p.features.join('\n'));
    } else {
        setTargetPlan({ id: '', name: '', price: 0, durationDays: 30, features: [] });
        setPlanFeaturesText('');
    }
    setIsEditingPlan(true);
  };

  const handleDeletePlan = async (id: string) => {
      if (confirm("Are you sure you want to delete this plan?")) {
          const updatedPlans = plans.filter(p => p.id !== id);
          await savePlans(updatedPlans);
          refreshData();
      }
  };

  const handleSavePlan = async () => {
    if (!targetPlan.name) return alert("Plan name is required");

    const featuresArray = planFeaturesText.split('\n').map(f => f.trim()).filter(f => f.length > 0);

    const planId = targetPlan.id || targetPlan.name?.toUpperCase().replace(/\s+/g, '_') || 'NEW_PLAN';

    const newPlanConfig: PlanConfig = {
        id: planId,
        name: targetPlan.name!,
        price: targetPlan.price || 0,
        durationDays: targetPlan.durationDays || 30,
        features: featuresArray
    };

    // Since Firebase update logic for plans is bulk in current storage.ts implementation for simplicity
    // We update the local array then save all
    let updatedPlans = [...plans];
    const index = updatedPlans.findIndex(p => p.id === planId);

    if (index >= 0) {
        updatedPlans[index] = newPlanConfig;
    } else {
        updatedPlans.push(newPlanConfig);
    }

    await savePlans(updatedPlans);
    setIsEditingPlan(false);
    refreshData();
  };

  const lang = currentUser.languagePreference;

  // Filter Users
  const filteredUsers = users.filter(u => 
    u.name.toLowerCase().includes(userSearchTerm.toLowerCase()) || 
    u.email.toLowerCase().includes(userSearchTerm.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h1 className="text-3xl font-bold dark:text-white flex items-center">
            {t('adminPanel', lang)}
            {isLoading && <Loader2 className="ml-3 animate-spin text-brand-500" />}
        </h1>
      </div>

      <div className="flex space-x-4 mb-6">
        <button 
          onClick={() => setActiveTab('BOOKS')}
          className={`px-6 py-3 rounded-xl font-bold flex items-center ${activeTab === 'BOOKS' ? 'bg-brand-600 text-white' : 'bg-white dark:bg-gray-800 text-gray-600 dark:text-gray-300'}`}
        >
          <BookIcon size={20} className="mr-2" /> {t('adminBooks', lang)}
        </button>
        <button 
          onClick={() => setActiveTab('USERS')}
          className={`px-6 py-3 rounded-xl font-bold flex items-center ${activeTab === 'USERS' ? 'bg-brand-600 text-white' : 'bg-white dark:bg-gray-800 text-gray-600 dark:text-gray-300'}`}
        >
          <Users size={20} className="mr-2" /> {t('adminUsers', lang)}
        </button>
        <button 
          onClick={() => setActiveTab('PLANS')}
          className={`px-6 py-3 rounded-xl font-bold flex items-center ${activeTab === 'PLANS' ? 'bg-brand-600 text-white' : 'bg-white dark:bg-gray-800 text-gray-600 dark:text-gray-300'}`}
        >
          <DollarSign size={20} className="mr-2" /> Paketler
        </button>
      </div>

      {/* --- BOOKS TAB --- */}
      {activeTab === 'BOOKS' && (
        <div className="bg-white dark:bg-gray-800 rounded-3xl p-6 border border-gray-100 dark:border-gray-700 shadow-sm">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-xl font-bold dark:text-white">Books List ({books.length})</h2>
            <button onClick={() => handleEditBook()} className="px-4 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg font-bold flex items-center">
              <Plus size={18} className="mr-2" /> {t('addBook', lang)}
            </button>
          </div>

          {isEditingBook ? (
            <div className="bg-gray-50 dark:bg-gray-900 p-6 rounded-2xl animate-in slide-in-from-top-4">
               <h3 className="font-bold text-lg mb-4 dark:text-white">{currentBook.id ? t('edit', lang) : t('addBook', lang)}</h3>
               <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
                 <div>
                   <label className="block text-sm font-bold text-gray-500 mb-1">{t('title', lang)}</label>
                   <input className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white" value={currentBook.title || ''} onChange={e => setCurrentBook({...currentBook, title: e.target.value})} />
                 </div>
                 <div>
