// --- Main App Component ---
const App = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [user, setUser] = useState<User | null>(null);
  const [currentPage, setCurrentPage] = useState('dashboard');

  // Selection State
  const [selectedBook, setSelectedBook] = useState<Book | null>(null);
  const [activeChapterIndex, setActiveChapterIndex] = useState<number | null>(null);

  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isQuizActive, setIsQuizActive] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  // Dynamic Data
  const [books, setBooks] = useState<Book[]>([]);
  const [savedWords, setSavedWords] = useState<VocabularyWord[]>([]);
  const [bookProgress, setBookProgress] = useState<Record<string, BookStatus>>({});
  const [plans, setPlans] = useState<PlanConfig[]>([]);

  // Initialization
  useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);
        await initStorage();
        const loadedPlans = await getPlans();
        setPlans(loadedPlans);

        // Restore Session
        const sessId = getSession();
        if (sessId) {
          const restoredUser = await getUserById(sessId);
          if (restoredUser) {
            setUser(restoredUser);
            setIsAuthenticated(true);
          }
        }
      } catch (e) {
        console.error("Initialization error:", e);
      } finally {
        setIsLoading(false);
      }
    };
    init();
  }, []);

  useEffect(() => {
    if (isDarkMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [isDarkMode]);

  // Subscription Check & Auto Downgrade Logic
  useEffect(() => {
    if (user && user.subscriptionStatus === 'TRIAL') {
      if (Date.now() > user.trialEndsAt) {
         // Trial Expired -> Downgrade to FREE instead of expiring
         const downgradedUser: User = { 
           ...user, 
           subscriptionStatus: 'ACTIVE', 
           plan: 'FREE',
           trialEndsAt: 0 
         };
         setUser(downgradedUser);
         saveUser(downgradedUser);
         alert("Your trial period has ended. You have been downgraded to the Free plan.");
      }
    } else if (user && user.subscriptionStatus === 'ACTIVE' && user.plan !== 'FREE' && user.subscriptionEndsAt) {
       // Paid Plan Expired -> Downgrade
       if (Date.now() > user.subscriptionEndsAt) {
         const downgradedUser: User = { 
           ...user, 
           subscriptionStatus: 'ACTIVE', 
           plan: 'FREE',
           subscriptionEndsAt: 0 
         };
         setUser(downgradedUser);
         saveUser(downgradedUser);
         alert("Your subscription has expired. You have been downgraded to the Free plan.");
       }
    }
  }, [user]);

  // Load User Data
  useEffect(() => {
    if (user) {
      const loadUserData = async () => {
        const [loadedBooks, loadedVocab, loadedProgress] = await Promise.all([
            getBooks(),
            getUserVocab(user.id),
            getUserProgress(user.id)
        ]);
        setBooks(loadedBooks);
        setSavedWords(loadedVocab);
        // Note: getUserProgress returns { [bookId]: status } currently.
        // We might need to update storage.ts to return full UserBookProgress objects eventually,
        // but for now we will adapt in component or use separate logic if complex.
        // Assuming current implementation returns simple map.
        setBookProgress(loadedProgress as any);
      };
      loadUserData();
    }
  }, [user, currentPage]); 

  // --- ADAPTIVE GOAL LOGIC ---
  useEffect(() => {
    if (!user) return;

    const checkGoals = async () => {
        // Check if we need to update goal based on YESTERDAY's performance
        const today = new Date();
        today.setHours(0,0,0,0);
        const todayTs = today.getTime();

        const lastVisit = new Date(user.lastVisitDate || 0);
        lastVisit.setHours(0,0,0,0);
        const lastVisitTs = lastVisit.getTime();

        if (lastVisitTs >= todayTs) return;

        // It's a new day. Let's look at YESTERDAY.
        const yesterday = new Date(today);
        yesterday.setDate(yesterday.getDate() - 1);
        const yesterdayTs = yesterday.getTime();

        let newGoal = user.dailyGoal || 25;
        let newStreak = user.streak;

        if (lastVisitTs === yesterdayTs) {
            const yesterdayEnd = todayTs;
            const wordsYesterday = savedWords.filter(w => {
            const t = parseInt(w.id);
            return t >= yesterdayTs && t < yesterdayEnd;
            }).length;

            const goalTarget = user.dailyGoal || 25;

            if (wordsYesterday >= goalTarget) {
                newGoal += 5;
            } else {
                newGoal = Math.max(25, newGoal - 5);
                newStreak = 0;
            }
        } else {
            newStreak = 0;
            newGoal = Math.max(25, newGoal - 5);
        }

        const updatedUser = {
            ...user,
            dailyGoal: newGoal,
            streak: newStreak,
            lastVisitDate: Date.now() 
        };

        handleUpdateUser(updatedUser);
    }

    // Only run this check if vocab has been loaded at least once
    if (savedWords.length > 0 || user.lastVisitDate === 0) {
        checkGoals();
    }

  }, [user?.id, savedWords.length]); 

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    setIsAuthenticated(true);
    saveSession(loggedInUser.id);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setUser(null);
    setSelectedBook(null);
    setActiveChapterIndex(null);
    setCurrentPage('dashboard');
    clearSession();
  };

  const handleUpdateUser = (updatedUser: User) => {
    setUser(updatedUser);
    saveUser(updatedUser); 
  };

  const handleToggleLanguage = () => {
    if (!user) return;
    const newUser = { 
      ...user, 
      languagePreference: user.languagePreference === 'TR' ? 'EN' : 'TR' as 'EN' | 'TR'
    };
    handleUpdateUser(newUser);
  };

  const handleSaveWord = (word: VocabularyWord) => {
    if (!user) return;
    const newWords = [word, ...savedWords];
    setSavedWords(newWords);
    saveUserVocab(user.id, newWords);

    // Real-time Streak Increment
    const wordsToday = getDailyWordCountInternal(newWords); 
    const currentGoal = user.dailyGoal || 25;

    if (wordsToday === currentGoal) {
       const newStreak = user.streak + 1;
       const newXp = user.xp + 50; 
       handleUpdateUser({ ...user, streak: newStreak, xp: newXp });
       alert(`Daily Goal Reached! Streak increased to ${newStreak}! +50 XP`);
    } else {
       handleUpdateUser({ ...user, xp: user.xp + 5 });
    }
  };

  const handleDeleteWord = (id: string) => {
    if (!user) return;
    const newWords = savedWords.filter(w => w.id !== id);
    setSavedWords(newWords);
    saveUserVocab(user.id, newWords);
  };

  const handleSelectBook = (book: Book) => {
    if (!user) return;
    setSelectedBook(book);
    setActiveChapterIndex(null); // Reset chapter selection to show list

    // Initialize progress if not started
    if (!bookProgress[book.id] || bookProgress[book.id] === 'NOT_STARTED') {
      const newProgress = { ...bookProgress, [book.id]: 'IN_PROGRESS' as BookStatus };
      setBookProgress(newProgress);
      saveUserProgress(user.id, newProgress);
    }
  };

  const handleSelectChapter = (chapterIndex: number) => {
    setActiveChapterIndex(chapterIndex);
  };

  const handleCompleteChapter = (bookId: string, chapterIndex: number) => {
    if (!user || !selectedBook) return;

    // Logic: If user completes the last chapter, mark book as COMPLETED.
    // Otherwise, we could track 'currentChapterIndex' in storage (future improvement).
    // For now, completion logic is simple.

    // Ensure chapters exist before checking length
    const chapters = selectedBook.chapters || [];
    if (chapters.length > 0 && chapterIndex === chapters.length - 1) {
        const newProgress = { ...bookProgress, [bookId]: 'COMPLETED' as BookStatus };
        setBookProgress(newProgress);
        saveUserProgress(user.id, newProgress);
    }
  };

  const handleStartQuiz = () => {
    if (savedWords.length < 5) {
      alert("You need at least 5 words to start a quiz.");
      return;
    }
    setIsQuizActive(true);
  };

  const handleQuizComplete = (result: QuizResult) => {
    if (!user) return;
    const newXp = user.xp + (result.score * 10);
    const updatedUser = { ...user, xp: newXp };
    setUser(updatedUser);
    saveUser(updatedUser);
    setIsQuizActive(false);
  };

  const handleUpgrade = (plan: PlanType) => {
    if(!user) return;

    const planConfig = plans.find(p => p.id === plan);
    const durationDays = planConfig ? planConfig.durationDays : (plan === 'YEARLY' ? 365 : 30);

    const updatedUser: User = {
      ...user,
      subscriptionStatus: 'ACTIVE',
      plan: plan,
      subscriptionEndsAt: Date.now() + durationDays * 24 * 60 * 60 * 1000
    };
    handleUpdateUser(updatedUser);
    setCurrentPage('dashboard');
    alert("Payment Successful! Welcome to ReadLex PRO.");
  };

  // Helper for internal use with passed list
  const getDailyWordCountInternal = (currentWords: VocabularyWord[]) => {
    const today = new Date();
    today.setHours(0,0,0,0);
    const todayTs = today.getTime();

    return currentWords.filter(w => {
       const wordTime = parseInt(w.id);
       return wordTime >= todayTs;
    }).length;
  }

  const getDailyWordCount = () => {
    return getDailyWordCountInternal(savedWords);
  }

  if (isLoading) {
      return (
          <div className="h-screen w-screen flex flex-col items-center justify-center bg-gray-50 dark:bg-gray-900">
             <Loader2 size={48} className="text-brand-600 animate-spin mb-4" />
             <p className="text-gray-500 font-bold animate-pulse">Loading ReadLex...</p>
          </div>
      );
  }

  if (!isAuthenticated || !user) {
    return (
      <div className={isDarkMode ? 'dark' : ''}>
         <Auth onLogin={handleLogin} />
      </div>
    );
  }

  // Render Logic
  const renderContent = () => {
    if (isQuizActive) {
      return (
        <div className="h-full flex flex-col items-center justify-center">
          <div className="w-full max-w-2xl mb-6 flex justify-between items-center">
            <h2 className="text-2xl font-black dark:text-white flex items-center">
              <Clock className="mr-3 text-brand-500" /> Practice Session
            </h2>
            <button onClick={() => setIsQuizActive(false)} className="px-5 py-2 rounded-xl bg-gray-200 hover:bg-gray-300 dark:bg-gray-800 dark:text-white text-gray-700 font-bold transition-colors">
              Exit
            </button>
          </div>
          <div className="w-full">
            <QuizEngine words={savedWords} onComplete={handleQuizComplete} onExit={() => setIsQuizActive(false)} />
          </div>
        </div>
      );
    }

    if (selectedBook) {
        if (activeChapterIndex !== null) {
            return (
                <BookReader 
                  book={selectedBook} 
                  initialChapterIndex={activeChapterIndex}
                  onBack={() => setActiveChapterIndex(null)} 
                  onSaveWord={handleSaveWord}
                  savedWords={savedWords}
                  onCompleteChapter={handleCompleteChapter}
                />
            );
        } else {
            return (
                <ChapterList 
                  book={selectedBook} 
                  // Mock progress object for now until storage is fully migrated
                  progress={{ 
                      bookId: selectedBook.id, 
                      status: bookProgress[selectedBook.id] || 'NOT_STARTED', 
                      // FIX: Safely access chapters.length using optional chaining and fallback
                      currentChapterIndex: bookProgress[selectedBook.id] === 'COMPLETED' ? (selectedBook.chapters?.length || 0) : 0, 
                      lastReadAt: new Date() 
                  }}
                  onSelectChapter={handleSelectChapter}
                  onBack={() => setSelectedBook(null)}
                />
            );
        }
    }

    switch (currentPage) {
      case 'dashboard':
        return (
          <Dashboard 
            user={user} 
            vocabCount={savedWords.length} 
            wordsAddedToday={getDailyWordCount()} 
            onStartQuiz={handleStartQuiz} 
            onUpgradeClick={() => setCurrentPage('pricing')} 
            books={books}
            bookProgress={bookProgress}
            onContinueBook={handleSelectBook}
            onNavigateToLibrary={() => setCurrentPage('library')}
          />
        );
      case 'library':
        return <Library books={books} progressMap={bookProgress} onSelectBook={handleSelectBook} user={user} />;
      case 'vocabulary':
        return <VocabularyWrapper user={user} words={savedWords} onDelete={handleDeleteWord} />;
      case 'profile':
        return <Profile user={user} onUpdate={handleUpdateUser} />;
      case 'pricing':
        return <Pricing user={user} onUpgrade={handleUpgrade} />;
      case 'admin':
        if (user.role !== 'ADMIN') return <div className="p-10 text-center text-red-500 font-bold text-2xl">Access Denied</div>;
        return <AdminPanel currentUser={user} />;
      default:
        return (
          <Dashboard 
            user={user} 
            vocabCount={savedWords.length} 
            wordsAddedToday={getDailyWordCount()} 
            onStartQuiz={handleStartQuiz} 
            onUpgradeClick={() => setCurrentPage('pricing')} 
            books={books}
            bookProgress={bookProgress}
            onContinueBook={handleSelectBook}
            onNavigateToLibrary={() => setCurrentPage('library')}
          />
        );
    }
  };

  return (
    <Layout 
      activePage={currentPage} 
      onNavigate={(p) => {
        setCurrentPage(p);
        setSelectedBook(null);
        setActiveChapterIndex(null);
        setIsQuizActive(false);
      }}
      isDarkMode={isDarkMode}
      toggleTheme={() => setIsDarkMode(!isDarkMode)}
      currentUser={user}
      onToggleLang={handleToggleLanguage}
      onLogout={handleLogout}
    >
      {renderContent()}
    </Layout>
  );
};

export default App;

// Fixed: Added React to imports to resolve namespace errors
import React, { useState, useRef, useEffect } from 'react';
import { Book, VocabularyWord } from '../types';
import { getWordDefinition, prefetchBookContent, translatePos } from '../services/geminiService';
import { ArrowLeft, Loader2, Star, Volume2, X, CheckCircle, ZoomIn, ZoomOut, Type, ArrowRight, BookOpen } from 'lucide-react';

interface BookReaderProps {
  book: Book;
  initialChapterIndex: number;
  onBack: () => void;
  onSaveWord: (word: VocabularyWord) => void;
  savedWords: VocabularyWord[];
  onCompleteChapter: (bookId: string, chapterIndex: number) => void;
}

interface SelectionState {
  word: string;
  context: string;
  x: number;
  y: number;
}

const FONTS = [
  { name: 'Sans', class: 'font-sans' },
  { name: 'Serif', class: 'font-serif' },
  { name: 'Mono', class: 'font-mono' },
];

const BookReader: React.FC<BookReaderProps> = ({ book, initialChapterIndex, onBack, onSaveWord, savedWords, onCompleteChapter }) => {
  const [currentChapterIndex, setCurrentChapterIndex] = useState(initialChapterIndex);
  const [selection, setSelection] = useState<SelectionState | null>(null);
  const [isLoadingDef, setIsLoadingDef] = useState(false);
  const [definition, setDefinition] = useState<any>(null);
  const textRef = useRef<HTMLDivElement>(null);

  const [fontSize, setFontSize] = useState(19);
  const [currentFont, setCurrentFont] = useState(FONTS[0].class);
  const [showFontMenu, setShowFontMenu] = useState(false);

  // Safely access chapters with fallback
  const chapters = book.chapters || [];

  // Early return if no chapters exist
  if (chapters.length === 0) {
    return (
        <div className="flex flex-col items-center justify-center h-screen bg-white dark:bg-gray-950 p-6">
            <h2 className="text-xl font-bold mb-4 dark:text-white">Content Unavailable</h2>
            <p className="mb-6 text-gray-500">This book has no chapters content.</p>
            <button onClick={onBack} className="px-4 py-2 bg-brand-600 text-white rounded-lg">Go Back</button>
        </div>
    );
  }

  const currentChapter = chapters[currentChapterIndex] || chapters[0];
  const isLastChapter = currentChapterIndex === chapters.length - 1;

  useEffect(() => {
    // Scroll to top when chapter changes
    window.scrollTo(0, 0);
    if(currentChapter) {
        prefetchBookContent(currentChapter.content);
    }
  }, [currentChapterIndex, book.id]);

  const tokenizeText = (text: string) => {
    return text.match(/([\w’']+)|([^\w\s]+)|(\s+)/g) || [];
  };

  const handleWordClick = async (word: string, event: React.MouseEvent) => {
    if (!/\w/.test(word)) return;

    const rect = (event.target as HTMLElement).getBoundingClientRect();
    const x = Math.max(16, Math.min(rect.left + rect.width/2 - 160, window.innerWidth - 336)); 
    const y = rect.bottom + window.scrollY + 12;

    const fullSentence = getSentenceContext(currentChapter.content, word);

    setSelection({ word, context: fullSentence, x, y });
    setDefinition(null);
    setIsLoadingDef(true);

    try {
        const def = await getWordDefinition(word, fullSentence);
        setDefinition(def);
    } catch (err) {
        console.error("Dictionary Fetch Failed:", err);
    } finally {
        setIsLoadingDef(false);
    }
  };

  const getSentenceContext = (text: string, word: string) => {
    const index = text.indexOf(word);
    if (index === -1) return "";
    const start = Math.max(0, text.lastIndexOf('.', index) + 1);
    let end = text.indexOf('.', index);
    if (end === -1) end = text.length;
    return text.slice(start, end + 1).trim();
  };

  const handleSave = () => {
    if (!definition || !selection) return;

    const newWord: VocabularyWord = {
      id: Date.now().toString(),
      word: selection.word,
      translation: definition.meanings[0].translation,
      definition: definition.meanings[0].definition,
      exampleSentence: selection.context,
      type: definition.meanings[0].partOfSpeech, // Already translated in service
      level: book.level,
      sourceBookId: book.id,
      nextReviewDate: new Date(),
      strength: 0
    };

    onSaveWord(newWord);
    setSelection(null); 
  };

  const isSaved = (word: string) => {
    const norm = word.toLowerCase().trim();
    return savedWords.some(w => w.word.toLowerCase().trim() === norm);
  };

  const playAudio = (text: string) => {
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'en-US';
    window.speechSynthesis.speak(utterance);
  };

  const handleNext = () => {
    onCompleteChapter(book.id, currentChapterIndex);
    if (isLastChapter) {
        onBack(); // Go back to Chapter List (which will now show 100%)
    } else {
        setCurrentChapterIndex(prev => prev + 1);
    }
  };

  const paragraphs = (currentChapter.content || '').split('\n').filter(p => p.trim() !== '');

  return (
    <div className="relative min-h-screen bg-[#fdfdfd] dark:bg-gray-950 pb-24">
      {/* Reader Controls */}
      <div className="sticky top-0 bg-white/90 dark:bg-gray-900/90 backdrop-blur-xl border-b border-gray-100 dark:border-gray-800 px-6 py-4 flex items-center justify-between z-30">
        <button onClick={onBack} className="flex items-center text-gray-600 hover:text-brand-600 dark:text-gray-300 font-bold transition-all">
          <ArrowLeft className="mr-2" size={20} />
          <span>Bölümler</span>
        </button>

        <div className="flex items-center gap-3">
          <div className="flex bg-gray-100 dark:bg-gray-800 rounded-xl p-1">
             <button onClick={() => setFontSize(Math.max(12, fontSize - 2))} className="p-2 text-gray-500 hover:text-brand-600"><ZoomOut size={16} /></button>
             <span className="px-2 flex items-center text-[10px] font-black text-gray-400 border-x border-gray-200 dark:border-gray-700">{fontSize}px</span>
             <button onClick={() => setFontSize(Math.min(42, fontSize + 2))} className="p-2 text-gray-500 hover:text-brand-600"><ZoomIn size={16} /></button>
          </div>
          <button 
            onClick={() => setShowFontMenu(!showFontMenu)} 
            className={`p-2 rounded-xl transition-all ${showFontMenu ? 'bg-brand-600 text-white' : 'bg-gray-100 dark:bg-gray-800 text-gray-500'}`}
          >
            <Type size={20} />
          </button>
        </div>
      </div>

      <div className="max-w-3xl mx-auto px-6 py-12">
        {showFontMenu && (
          <div className="mb-8 flex gap-3 justify-center bg-white dark:bg-gray-900 p-3 rounded-2xl shadow-xl border border-gray-100 dark:border-gray-800 animate-in fade-in slide-in-from-top-2">
             {FONTS.map(f => (
               <button 
                key={f.name}
                onClick={() => { setCurrentFont(f.class); setShowFontMenu(false); }}
                className={`px-5 py-2.5 rounded-xl text-sm font-black transition-all ${currentFont === f.class ? 'bg-brand-600 text-white shadow-lg' : 'hover:bg-gray-100 dark:hover:bg-gray-800 dark:text-gray-400'}`}
               >
                 {f.name}
               </button>
             ))}
          </div>
        )}

        <div className="bg-white dark:bg-gray-900 rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-gray-800 p-8 md:p-16">
          <header className="mb-12 text-center border-b border-gray-100 dark:border-gray-800 pb-8">
             <p className="text-brand-600 font-bold uppercase tracking-widest text-xs mb-2">Chapter {currentChapterIndex + 1}</p>
             <h1 className={`text-3xl md:text-4xl font-black text-gray-900 dark:text-white mb-2 ${currentFont}`}>{currentChapter.title}</h1>
             <p className="text-gray-400 text-xs font-black uppercase tracking-[0.3em]">{book.title}</p>
          </header>

          <article 
            ref={textRef} 
            className={`leading-relaxed text-gray-800 dark:text-gray-200 ${currentFont} transition-all duration-300`}
            style={{ fontSize: `${fontSize}px` }}
          >
            {paragraphs.map((paragraph, pIndex) => (
              <p key={pIndex} className="mb-10 text-justify">
                {tokenizeText(paragraph).map((token, index) => {
                  const isWord = /\w/.test(token);
                  const saved = isWord && isSaved(token);
                  const active = selection?.word === token;

                  return isWord ? (
                    <span
                      key={index}
                      onClick={(e) => handleWordClick(token, e)}
                      className={`cursor-pointer transition-all rounded-md px-0.5 inline-block
                        ${saved 
                          ? 'bg-yellow-100 dark:bg-yellow-900/40 text-yellow-900 dark:text-yellow-100 decoration-yellow-400/50 underline decoration-2 underline-offset-4' 
                          : 'hover:bg-brand-50 dark:hover:bg-brand-900/20 hover:text-brand-600'
                        }
                        ${active ? 'bg-brand-600 text-white scale-110 shadow-lg px-2 rounded-lg' : ''}
                      `}
                    >
                      {token}
                    </span>
                  ) : (
                    <span key={index}>{token}</span>
                  );
                })}
              </p>
            ))}
          </article>

          <footer className="mt-20 pt-16 border-t border-gray-50 dark:border-gray-800 text-center">
             <button
               onClick={handleNext}
               className="px-10 py-5 bg-gray-900 dark:bg-brand-600 text-white rounded-[2rem] font-black text-lg hover:scale-105 transition-all shadow-2xl active:scale-95 flex items-center justify-center mx-auto"
             >
               {isLastChapter ? (
                  <> <CheckCircle className="mr-3" /> Kitabı Bitir </>
               ) : (
                  <> Sonraki Bölüm <ArrowRight className="ml-3" /> </>
               )}
             </button>
          </footer>
        </div>
      </div>

      {/* Dictionary Popup */}
      {selection && (
        <>
          <div className="fixed inset-0 z-40 bg-black/5 lg:bg-transparent" onClick={() => setSelection(null)} />
          <div 
            className="fixed z-50 w-[320px] bg-white dark:bg-gray-800 rounded-[2rem] shadow-[0_40px_80px_-15px_rgba(0,0,0,0.2)] border border-gray-100 dark:border-gray-700 overflow-hidden animate-in zoom-in-95 duration-200"
            style={{ 
              top: Math.min(selection.y, window.innerHeight - 350),
              left: selection.x
            }}
          >
            <div className="p-6">
              <header className="flex justify-between items-start mb-2">
                <div>
                   <h3 className="text-2xl font-black text-gray-900 dark:text-white capitalize truncate pr-2">{selection.word}</h3>
                   <span className="text-[10px] font-black uppercase text-gray-400 tracking-wider">İngilizce</span>
                </div>
                <div className="flex gap-1 shrink-0">
                  <button onClick={() => playAudio(selection.word)} className="p-2.5 rounded-full text-brand-600 bg-brand-50 hover:bg-brand-100 transition-all"><Volume2 size={20} /></button>
                  <button onClick={() => setSelection(null)} className="p-2.5 rounded-full text-gray-400 hover:text-red-500 hover:bg-red-50 transition-all"><X size={20} /></button>
                </div>
              </header>

              {isLoadingDef ? (
                <div className="py-8 flex flex-col items-center justify-center">
                  <Loader2 className="animate-spin text-brand-500 mb-3" size={32} strokeWidth={3} />
                  <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">Çevriliyor...</p>
                </div>
              ) : (
                definition && (
                  <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-400">
                    {definition.meanings.map((meaning: any, i: number) => (
                      <div key={i} className="group">
                        <div className="mt-4 mb-4">
                           <span className="text-[10px] font-black uppercase text-brand-600 bg-brand-50 dark:bg-brand-900/30 px-2 py-0.5 rounded-lg mb-1 inline-block">
                            {translatePos(meaning.partOfSpeech)}
                          </span>
                           <div className="font-bold text-3xl text-brand-600 dark:text-brand-400 leading-tight">
                            {meaning.translation}
                          </div>
                        </div>

                        {/* Örnek Cümle ve Çevirisi */}
                        <div className="bg-gray-50 dark:bg-gray-900/50 p-3 rounded-xl border border-gray-100 dark:border-gray-700">
                           <p className="text-[10px] font-black text-gray-400 uppercase mb-1">Örnek Cümle</p>
                           <p className="text-sm text-gray-800 dark:text-gray-200 font-medium italic leading-relaxed mb-2">
                             "{meaning.example}"
                           </p>
                           {meaning.translatedExample && (
                               <p className="text-sm text-brand-600 dark:text-brand-400 font-medium leading-relaxed border-t border-gray-200 dark:border-gray-700 pt-2">
                                 {meaning.translatedExample}
                               </p>
                           )}
                        </div>
                      </div>
                    ))}

                    <button 
                      onClick={handleSave}
                      className={`w-full mt-2 py-4 rounded-xl font-black text-base transition-all
                        ${isSaved(selection.word) 
                          ? 'bg-green-50 text-green-600 shadow-inner' 
                          : 'bg-brand-600 text-white hover:bg-brand-700 shadow-xl shadow-brand-500/20 active:scale-95'}`}
                    >
                      {isSaved(selection.word) ? (
                        <span className="flex items-center justify-center gap-2"><CheckCircle size={18} /> Kaydedildi</span>
                      ) : (
                        <span className="flex items-center justify-center gap-2"><Star size={18} /> Deftere Ekle</span>
                      )}
                    </button>
                  </div>
                )
              )}
            </div>
          </div>
        </>
      )}
    </div>
  );
};

