export const savePlans = async (plans: PlanConfig[]) => {
    return withFallback(
        async () => {
            const batch = db!.batch();
            for (const plan of plans) {
                const ref = db!.collection(PLANS_COL).doc(plan.id);
                batch.set(ref, plan);
            }
            await batch.commit();
        },
        () => {
            localStorage.setItem(LOCAL_KEYS.PLANS, JSON.stringify(plans));
        }
    );
