           />
           <div className="flex-1 text-center md:text-left">
              <div className="inline-block px-3 py-1 bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-300 rounded-lg text-xs font-black uppercase mb-3 tracking-wider">
                {t('jumpBackIn', lang)}
              </div>
              <h2 className="text-2xl font-black dark:text-white mb-1">{activeBook.title}</h2>
              <p className="text-gray-500 dark:text-gray-400 mb-6 font-medium">{activeBook.author}</p>
              <button 
                onClick={() => onContinueBook(activeBook)}
                className="inline-flex items-center px-8 py-3 bg-brand-600 hover:bg-brand-700 text-white font-bold rounded-xl transition-all shadow-lg shadow-brand-500/20 group"
              >
                {t('continueReading', lang)}
                <ArrowRight className="ml-2 group-hover:translate-x-1 transition-transform" size={20} />
              </button>
           </div>
        </div>
      ) : (
        <div className="bg-white dark:bg-gray-800 rounded-[2rem] p-8 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex flex-col sm:flex-row sm:justify-between sm:items-end gap-4 mb-6">
             <div>
               <h2 className="text-3xl font-black dark:text-white flex items-center">
                 <BookOpen className="mr-3 text-brand-500" size={32} />
                 {t('exploreLibrary', lang)}
               </h2>
               <p className="text-gray-500 dark:text-gray-400 text-base font-medium mt-1 ml-11">{t('popularBooks', lang)}</p>
             </div>
             <button 
                onClick={onNavigateToLibrary} 
                className="self-start sm:self-auto text-brand-600 hover:text-brand-700 font-bold text-sm bg-brand-50 hover:bg-brand-100 dark:bg-gray-700 dark:text-brand-400 px-4 py-2 rounded-xl transition-all flex items-center"
             >
                {t('viewLibrary', lang)} <ArrowRight size={16} className="ml-2" />
             </button>
          </div>

          <div 
            ref={scrollContainerRef}
            onMouseDown={handleMouseDown}
            onMouseLeave={handleMouseLeave}
            onMouseUp={handleMouseUp}
            onMouseMove={handleMouseMove}
            className="flex gap-5 overflow-x-auto pb-4 cursor-grab active:cursor-grabbing scrollbar-hide snap-x"
          >
             {books.filter(b => !b.archived).map(book => (
               <div 
                  key={book.id} 
                  onClick={() => onContinueBook(book)} 
                  className="group min-w-[150px] w-[150px] md:min-w-[190px] md:w-[190px] flex-shrink-0 snap-center select-none cursor-pointer"
               >
                 <div className="relative rounded-2xl overflow-hidden shadow-lg shadow-gray-200 dark:shadow-none aspect-[2/3] mb-3 transform transition-transform duration-300 group-hover:-translate-y-1">
                    <div className="absolute inset-0 bg-black/0 group-hover:bg-black/5 z-10 transition-colors" />
                    <img src={book.coverUrl} className="w-full h-full object-cover" />
                    <span className={`absolute top-2 right-2 text-white text-[10px] font-bold px-2 py-1 rounded-md backdrop-blur-md shadow-sm z-20
                      ${book.level.startsWith('A') ? 'bg-green-500/90' : book.level.startsWith('B') ? 'bg-yellow-500/90' : 'bg-red-500/90'}`}>
                      {book.level}
                    </span>
                 </div>
                 <h3 className="font-bold text-gray-900 dark:text-white text-base leading-tight mb-0.5 truncate">{book.title}</h3>
                 <p className="text-xs text-gray-500 dark:text-gray-400 truncate">{book.author}</p>
               </div>
             ))}
          </div>
        </div>
      )}

      {/* --- Goals & Quiz Section --- */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <div className="bg-white dark:bg-gray-800 p-8 rounded-[2rem] border-2 border-gray-100 dark:border-gray-700 shadow-sm hover:shadow-xl transition-all duration-300">
          <h2 className="text-2xl font-black mb-6 dark:text-white flex items-center">
             <div className="w-8 h-8 rounded-lg bg-green-100 text-green-600 flex items-center justify-center mr-3">
               <CheckCircle size={20} />
             </div>
             {t('dailyGoal', lang)}
          </h2>
          <div className="flex items-center justify-between mb-3">
            <span className="text-gray-500 dark:text-gray-400 font-bold uppercase text-sm tracking-wide">{t('wordsLearned', lang)} (Today)</span>
            <span className="font-black text-2xl dark:text-white text-green-500">{wordsAddedToday} <span className="text-gray-300 text-lg">/ {dailyGoal}</span></span>
          </div>
          <div className="w-full bg-gray-100 dark:bg-gray-700 rounded-full h-5 overflow-hidden p-1">
            <div className="bg-green-500 h-full rounded-full transition-all duration-1000 shadow-sm" style={{ width: `${progressPercent}%` }}></div>
          </div>
          <p className="mt-4 text-gray-400 text-sm">
             {wordsAddedToday >= dailyGoal ? `Goal Reached! Tomorrow's goal: ${dailyGoal + 5}` : "Read books and save words to reach your goal."}
          </p>
        </div>

        <div className="bg-white dark:bg-gray-800 p-8 rounded-[2rem] border-2 border-gray-100 dark:border-gray-700 shadow-sm hover:shadow-xl hover:border-brand-200 dark:hover:border-brand-900 transition-all duration-300 flex flex-col justify-between group">
          <div>
            <h2 className="text-2xl font-black mb-2 dark:text-white flex items-center">
              <div className="w-8 h-8 rounded-lg bg-brand-100 text-brand-600 flex items-center justify-center mr-3">
                 <Clock size={20} />
              </div>
              {t('quickQuiz', lang)}
            </h2>
            <p className="text-gray-500 dark:text-gray-400 font-medium">{t('reviewWords', lang)} ({vocabCount})</p>
            {vocabCount < 5 && (
              <p className="text-red-500 text-sm mt-3 font-bold bg-red-50 inline-block px-3 py-1 rounded-lg">Need 5+ words to start</p>
            )}
          </div>
          <button 
            onClick={onStartQuiz}
            disabled={vocabCount < 5}
            className="mt-6 w-full py-4 bg-brand-600 text-white font-black rounded-2xl flex items-center justify-center transition-all shadow-lg shadow-brand-500/20 hover:bg-brand-700 hover:scale-[1.02] active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed disabled:shadow-none disabled:transform-none text-lg"
          >
            <Play size={24} className="mr-2 fill-current" />
            {t('startSession', lang)}
          </button>
        </div>
      </div>
    </div>
  );
};

// --- Main App Component ---
const App = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [user, setUser] = useState<User | null>(null);
  const [currentPage, setCurrentPage] = useState('dashboard');

  // Selection State
  const [selectedBook, setSelectedBook] = useState<Book | null>(null);
  const [activeChapterIndex, setActiveChapterIndex] = useState<number | null>(null);

  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isQuizActive, setIsQuizActive] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  // Dynamic Data
  const [books, setBooks] = useState<Book[]>([]);
  const [savedWords, setSavedWords] = useState<VocabularyWord[]>([]);
  // CHANGED: State now holds UserBookProgress objects
  const [bookProgress, setBookProgress] = useState<Record<string, UserBookProgress>>({});
  const [plans, setPlans] = useState<PlanConfig[]>([]);

  // Initialization
  useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);
        await initStorage();
        const loadedPlans = await getPlans();
        setPlans(loadedPlans);

        // Restore Session
        const sessId = getSession();
        if (sessId) {
          const restoredUser = await getUserById(sessId);
          if (restoredUser) {
            setUser(restoredUser);
            setIsAuthenticated(true);
          }
        }
      } catch (e) {
        console.error("Initialization error:", e);
      } finally {
        setIsLoading(false);
      }
    };
    init();
  }, []);

  useEffect(() => {
    if (isDarkMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [isDarkMode]);

  // Subscription Check & Auto Downgrade Logic
  useEffect(() => {
    if (user && user.subscriptionStatus === 'TRIAL') {
      if (Date.now() > user.trialEndsAt) {
         // Trial Expired -> Downgrade to FREE instead of expiring
         const downgradedUser: User = { 
           ...user, 
           subscriptionStatus: 'ACTIVE', 
           plan: 'FREE',
           trialEndsAt: 0 
         };
         setUser(downgradedUser);
         saveUser(downgradedUser);
         alert("Your trial period has ended. You have been downgraded to the Free plan.");
      }
    } else if (user && user.subscriptionStatus === 'ACTIVE' && user.plan !== 'FREE' && user.subscriptionEndsAt) {
       // Paid Plan Expired -> Downgrade
       if (Date.now() > user.subscriptionEndsAt) {
         const downgradedUser: User = { 
           ...user, 
           subscriptionStatus: 'ACTIVE', 
           plan: 'FREE',
           subscriptionEndsAt: 0 
         };
         setUser(downgradedUser);
         saveUser(downgradedUser);
         alert("Your subscription has expired. You have been downgraded to the Free plan.");
       }
    }
  }, [user]);

  // Load User Data
  useEffect(() => {
    if (user) {
      const loadUserData = async () => {
        const [loadedBooks, loadedVocab, loadedProgress] = await Promise.all([
            getBooks(),
            getUserVocab(user.id),
            getUserProgress(user.id)
        ]);
        setBooks(loadedBooks);
        setSavedWords(loadedVocab);
        // Note: getUserProgress returns { [bookId]: UserBookProgress }
        setBookProgress(loadedProgress);
      };
      loadUserData();
    }
  }, [user, currentPage]); 

  // --- ADAPTIVE GOAL LOGIC ---
  useEffect(() => {
    if (!user) return;

    const checkGoals = async () => {
        // Check if we need to update goal based on YESTERDAY's performance
        const today = new Date();
        today.setHours(0,0,0,0);
        const todayTs = today.getTime();

        const lastVisit = new Date(user.lastVisitDate || 0);
        lastVisit.setHours(0,0,0,0);
        const lastVisitTs = lastVisit.getTime();

        if (lastVisitTs >= todayTs) return;

        // It's a new day. Let's look at YESTERDAY.
        const yesterday = new Date(today);
        yesterday.setDate(yesterday.getDate() - 1);
        const yesterdayTs = yesterday.getTime();

        let newGoal = user.dailyGoal || 25;
        let newStreak = user.streak;

        if (lastVisitTs === yesterdayTs) {
            const yesterdayEnd = todayTs;
            const wordsYesterday = savedWords.filter(w => {
            const t = parseInt(w.id);
            return t >= yesterdayTs && t < yesterdayEnd;
            }).length;

            const goalTarget = user.dailyGoal || 25;

            if (wordsYesterday >= goalTarget) {
                newGoal += 5;
            } else {
                newGoal = Math.max(25, newGoal - 5);
                newStreak = 0;
            }
        } else {
            newStreak = 0;
            newGoal = Math.max(25, newGoal - 5);
        }

        const updatedUser = {
            ...user,
            dailyGoal: newGoal,
            streak: newStreak,
            lastVisitDate: Date.now() 
        };

        handleUpdateUser(updatedUser);
    }

    // Only run this check if vocab has been loaded at least once
    if (savedWords.length > 0 || user.lastVisitDate === 0) {
        checkGoals();
    }

  }, [user?.id, savedWords.length]); 

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    setIsAuthenticated(true);
    saveSession(loggedInUser.id);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setUser(null);
    setSelectedBook(null);
    setActiveChapterIndex(null);
    setCurrentPage('dashboard');
    clearSession();
  };

  const handleUpdateUser = (updatedUser: User) => {
    setUser(updatedUser);
    saveUser(updatedUser); 
  };

  const handleToggleLanguage = () => {
    if (!user) return;
    const newUser = { 
      ...user, 
      languagePreference: user.languagePreference === 'TR' ? 'EN' : 'TR' as 'EN' | 'TR'
    };
    handleUpdateUser(newUser);
  };

  const handleSaveWord = (word: VocabularyWord) => {
    if (!user) return;
    const newWords = [word, ...savedWords];
    setSavedWords(newWords);
    saveUserVocab(user.id, newWords);

    // Real-time Streak Increment
    const wordsToday = getDailyWordCountInternal(newWords); 
    const currentGoal = user.dailyGoal || 25;

    if (wordsToday === currentGoal) {
       const newStreak = user.streak + 1;
       const newXp = user.xp + 50; 
       handleUpdateUser({ ...user, streak: newStreak, xp: newXp });
       alert(`Daily Goal Reached! Streak increased to ${newStreak}! +50 XP`);
    } else {
       handleUpdateUser({ ...user, xp: user.xp + 5 });
    }
  };

  const handleDeleteWord = (id: string) => {
    if (!user) return;
    const newWords = savedWords.filter(w => w.id !== id);
    setSavedWords(newWords);
    saveUserVocab(user.id, newWords);
  };

  const handleSelectBook = (book: Book) => {
    if (!user) return;
    setSelectedBook(book);
    setActiveChapterIndex(null); // Reset chapter selection to show list

    // Initialize progress if not started
    if (!bookProgress[book.id]) {
      const newEntry: UserBookProgress = {
          bookId: book.id,
          status: 'IN_PROGRESS',
          currentChapterIndex: 0,
          lastReadAt: new Date()
      };
      const newProgress = { ...bookProgress, [book.id]: newEntry };
      setBookProgress(newProgress);
      saveUserProgress(user.id, newProgress);
    }
  };

  const handleSelectChapter = (chapterIndex: number) => {
    setActiveChapterIndex(chapterIndex);
  };

  const handleCompleteChapter = (bookId: string, chapterIndex: number) => {
    if (!user || !selectedBook) return;

    // Retrieve current progress or initialize default
    const currentProgress = bookProgress[bookId] || { 
        bookId, 
        status: 'IN_PROGRESS', 
        currentChapterIndex: 0, 
        lastReadAt: new Date() 
    };

    // If user finished chapterIndex, the NEXT chapter (chapterIndex + 1) should be unlocked.
    // So currentChapterIndex should become chapterIndex + 1.
    // We use Math.max to prevent regression if they re-read an old chapter.
    const nextChapterIndex = chapterIndex + 1;
    const newMaxIndex = Math.max(currentProgress.currentChapterIndex, nextChapterIndex);

    const chapters = selectedBook.chapters || [];
    let newStatus = currentProgress.status;

    // If we just finished the last chapter (index length-1), mark completed.
    if (chapters.length > 0 && chapterIndex >= chapters.length - 1) {
        newStatus = 'COMPLETED';
    }

    const newProgressEntry: UserBookProgress = {
        ...currentProgress,
        status: newStatus,
        currentChapterIndex: newMaxIndex,
        lastReadAt: new Date()
    };

    const newProgressMap = { ...bookProgress, [bookId]: newProgressEntry };
    setBookProgress(newProgressMap);
    saveUserProgress(user.id, newProgressMap);
  };

  const handleStartQuiz = () => {
    if (savedWords.length < 5) {
      alert("You need at least 5 words to start a quiz.");
      return;
    }
    setIsQuizActive(true);
  };

  const handleQuizComplete = (result: QuizResult) => {
    if (!user) return;
    const newXp = user.xp + (result.score * 10);
    const updatedUser = { ...user, xp: newXp };
    setUser(updatedUser);
    saveUser(updatedUser);
    setIsQuizActive(false);
  };

  const handleUpgrade = (plan: PlanType) => {
    if(!user) return;

    const planConfig = plans.find(p => p.id === plan);
    const durationDays = planConfig ? planConfig.durationDays : (plan === 'YEARLY' ? 365 : 30);

    const updatedUser: User = {
      ...user,
      subscriptionStatus: 'ACTIVE',
      plan: plan,
      subscriptionEndsAt: Date.now() + durationDays * 24 * 60 * 60 * 1000
    };
    handleUpdateUser(updatedUser);
    setCurrentPage('dashboard');
    alert("Payment Successful! Welcome to ReadLex PRO.");
  };

  // Helper for internal use with passed list
  const getDailyWordCountInternal = (currentWords: VocabularyWord[]) => {
    const today = new Date();
    today.setHours(0,0,0,0);
    const todayTs = today.getTime();

    return currentWords.filter(w => {
       const wordTime = parseInt(w.id);
       return wordTime >= todayTs;
    }).length;
  }

  const getDailyWordCount = () => {
    return getDailyWordCountInternal(savedWords);
  }

  if (isLoading) {
      return (
          <div className="h-screen w-screen flex flex-col items-center justify-center bg-gray-50 dark:bg-gray-900">
             <Loader2 size={48} className="text-brand-600 animate-spin mb-4" />
             <p className="text-gray-500 font-bold animate-pulse">Loading ReadLex...</p>
          </div>
      );
  }

  if (!isAuthenticated || !user) {
    return (
      <div className={isDarkMode ? 'dark' : ''}>
         <Auth onLogin={handleLogin} />
      </div>
    );
  }

  // Render Logic
  const renderContent = () => {
    if (isQuizActive) {
      return (
        <div className="h-full flex flex-col items-center justify-center">
          <div className="w-full max-w-2xl mb-6 flex justify-between items-center">
            <h2 className="text-2xl font-black dark:text-white flex items-center">
              <Clock className="mr-3 text-brand-500" /> Practice Session
            </h2>
            <button onClick={() => setIsQuizActive(false)} className="px-5 py-2 rounded-xl bg-gray-200 hover:bg-gray-300 dark:bg-gray-800 dark:text-white text-gray-700 font-bold transition-colors">
              Exit
            </button>
          </div>
          <div className="w-full">
            <QuizEngine words={savedWords} onComplete={handleQuizComplete} onExit={() => setIsQuizActive(false)} />
          </div>
        </div>
      );
    }

    if (selectedBook) {
        if (activeChapterIndex !== null) {
            return (
                <BookReader 
                  book={selectedBook} 
                  initialChapterIndex={activeChapterIndex}
                  onBack={() => setActiveChapterIndex(null)} 
                  onSaveWord={handleSaveWord}
                  savedWords={savedWords}
                  onCompleteChapter={handleCompleteChapter}
                />
            );
        } else {
            return (
                <ChapterList 
                  book={selectedBook} 
                  progress={bookProgress[selectedBook.id]} // Directly pass the object
                  onSelectChapter={handleSelectChapter}
                  onBack={() => setSelectedBook(null)}
                />
            );
        }
    }

    switch (currentPage) {
      case 'dashboard':
        return (
          <Dashboard 
            user={user} 
            vocabCount={savedWords.length} 
            wordsAddedToday={getDailyWordCount()} 
            onStartQuiz={handleStartQuiz} 
            onUpgradeClick={() => setCurrentPage('pricing')} 
            books={books}
            bookProgress={bookProgress}
            onContinueBook={handleSelectBook}
            onNavigateToLibrary={() => setCurrentPage('library')}
          />
        );
      case 'library':
        return <Library books={books} progressMap={bookProgress} onSelectBook={handleSelectBook} user={user} />;
      case 'vocabulary':
        return <VocabularyWrapper user={user} words={savedWords} onDelete={handleDeleteWord} />;
      case 'profile':
        return <Profile user={user} onUpdate={handleUpdateUser} />;
      case 'pricing':
        return <Pricing user={user} onUpgrade={handleUpgrade} />;
      case 'admin':
        if (user.role !== 'ADMIN') return <div className="p-10 text-center text-red-500 font-bold text-2xl">Access Denied</div>;
        return <AdminPanel currentUser={user} />;
      default:
        return (
          <Dashboard 
            user={user} 
            vocabCount={savedWords.length} 
            wordsAddedToday={getDailyWordCount()} 
            onStartQuiz={handleStartQuiz} 
            onUpgradeClick={() => setCurrentPage('pricing')} 
            books={books}
            bookProgress={bookProgress}
            onContinueBook={handleSelectBook}
            onNavigateToLibrary={() => setCurrentPage('library')}
          />
        );
    }
  };

  return (
    <Layout 
      activePage={currentPage} 
      onNavigate={(p) => {
        setCurrentPage(p);
        setSelectedBook(null);
        setActiveChapterIndex(null);
        setIsQuizActive(false);
      }}
      isDarkMode={isDarkMode}
      toggleTheme={() => setIsDarkMode(!isDarkMode)}
      currentUser={user}
      onToggleLang={handleToggleLanguage}
      onLogout={handleLogout}
    >
      {renderContent()}
    </Layout>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Book, BookStatus, CEFRLevel, User, PlanType, UserBookProgress } from '../types';
import { CheckCircle, Clock, CircleDashed, Lock, Sparkles } from 'lucide-react';
import { t } from '../services/i18n';

interface LibraryProps {
  books: Book[];
  progressMap: Record<string, UserBookProgress>;
  onSelectBook: (b: Book) => void;
  user: User;
}

const Library: React.FC<LibraryProps> = ({ 
  books, 
  progressMap, 
  onSelectBook,
  user
}) => {
  const [activeTab, setActiveTab] = useState<'ALL' | CEFRLevel>('ALL');

  const filteredBooks = useMemo(() => {
    // 1. Filter out archived books (users shouldn't see them)
    let visibleBooks = books.filter(b => !b.archived);

    // 2. Filter by Level Tab
    if (activeTab === 'ALL') return visibleBooks;
    return visibleBooks.filter(b => b.level === activeTab);
  }, [books, activeTab]);

  const canAccessBook = (bookPlans: PlanType[]): boolean => {
    // 1. "FREE" planındaki kitaplar HERKESE açıktır.
    // Kullanıcının planı ne olursa olsun (Expired, Trial, Monthly vb.) erişebilir.
    if (bookPlans.includes('FREE')) return true;

    const isTrial = user.subscriptionStatus === 'TRIAL';
    const isExpired = user.subscriptionStatus === 'EXPIRED';

    // 2. Trial allows everything
    if (isTrial) return true;

    // 3. Expired users act like Free users (or restricted to Free content)
    // Yukarıdaki 1. kural zaten FREE kontrolünü yaptığı için buraya düşen expired kullanıcılar reddedilir.
    if (isExpired) {
        return false;
    }

    // 4. Active users: Check if their plan is in the list
    return bookPlans.includes(user.plan);
  };

  const getStatusBadge = (status?: BookStatus) => {
    switch(status) {
      case 'COMPLETED':
        return <span className="bg-green-100 text-green-700 px-2 py-1 rounded-md text-xs font-bold flex items-center"><CheckCircle size={12} className="mr-1"/> {t('completed', user.languagePreference)}</span>;
      case 'IN_PROGRESS':
        return <span className="bg-blue-100 text-blue-700 px-2 py-1 rounded-md text-xs font-bold flex items-center"><Clock size={12} className="mr-1"/> {t('continueReading', user.languagePreference)}</span>;
      default:
        return <span className="bg-gray-100 text-gray-500 px-2 py-1 rounded-md text-xs font-bold flex items-center"><CircleDashed size={12} className="mr-1"/> {t('notStarted', user.languagePreference)}</span>;
    }
  };

  const getCardStyle = (status?: BookStatus) => {
    if (status === 'COMPLETED') return 'border-green-200 ring-2 ring-green-500/20';
    if (status === 'IN_PROGRESS') return 'border-blue-200 ring-2 ring-blue-500/20';
    return 'border-gray-200';
  };

  const tabs: ('ALL' | CEFRLevel)[] = ['ALL', 'A1', 'A2', 'B1', 'B2', 'C1', 'C2'];

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-bold dark:text-white">{t('library', user.languagePreference)}</h1>
      </div>

      {/* Filter Tabs */}
      <div className="flex flex-wrap gap-2 mb-8 border-b border-gray-200 dark:border-gray-700 pb-4">
        {tabs.map(tab => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-5 py-2 rounded-full text-sm font-bold transition-all ${
              activeTab === tab 
                ? 'bg-brand-600 text-white shadow-md shadow-brand-500/30' 
                : 'bg-white dark:bg-gray-800 text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 border border-gray-200 dark:border-gray-700'
            }`}
          >
            {tab === 'ALL' ? t('all', user.languagePreference) : tab}
          </button>
        ))}
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
        {filteredBooks.map(book => {
          const progress = progressMap[book.id];
          const status = progress?.status || 'NOT_STARTED';
          const isLocked = !canAccessBook(book.requiredPlan);

          return (
            <div key={book.id} className={`bg-white dark:bg-gray-800 rounded-3xl overflow-hidden border shadow-sm transition-all duration-300 group flex flex-col relative ${getCardStyle(status)} ${isLocked ? 'opacity-80' : 'hover:shadow-xl'}`}>

              {/* Lock Overlay */}
              {isLocked && (
                <div className="absolute inset-0 z-20 bg-gray-900/10 backdrop-blur-[2px] flex flex-col items-center justify-center text-center p-4">
                  <div className="bg-white dark:bg-gray-900 p-4 rounded-full shadow-2xl mb-3">
                    <Lock size={32} className="text-gray-400" />
                  </div>
                  <div className="bg-white dark:bg-gray-800 px-4 py-2 rounded-xl shadow-lg">
                    <p className="font-bold text-gray-800 dark:text-white text-sm">
                      {user.subscriptionStatus === 'EXPIRED' ? 'Subscription Expired' : 'Premium Access Required'}
                    </p>
                  </div>
                </div>
              )}

              <div className="h-48 bg-gray-200 dark:bg-gray-700 relative overflow-hidden">
                <img src={book.coverUrl} alt={book.title} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                <span className={`absolute top-3 right-3 text-white text-xs font-bold px-3 py-1.5 rounded-full border border-white/20 backdrop-blur-md
                  ${book.level.startsWith('A') ? 'bg-green-500/80' : book.level.startsWith('B') ? 'bg-yellow-500/80' : 'bg-red-500/80'}`}>
                  {book.level}
                </span>
                <div className="absolute bottom-3 left-3">
                  {getStatusBadge(status)}
                </div>
                {/* Only show Premium badge if it's NOT a purely free book */}
                {!(book.requiredPlan.includes('FREE')) && (
                  <div className="absolute top-3 left-3">
                     <span className="bg-gradient-to-r from-yellow-400 to-orange-500 text-white text-xs font-bold px-2 py-1 rounded flex items-center shadow-lg">
                       <Sparkles size={10} className="mr-1" /> PREMIUM
                     </span>
                  </div>
                )}
              </div>
              <div className="p-6 flex-1 flex flex-col">
                <h3 className="font-bold text-xl mb-1 dark:text-white line-clamp-1">{book.title}</h3>
                <p className="text-sm text-gray-500 dark:text-gray-400 mb-4">{book.author}</p>
                <p className="text-sm text-gray-600 dark:text-gray-300 line-clamp-3 mb-6 flex-1 leading-relaxed">{book.excerpt}</p>
                <button 
                  onClick={() => !isLocked && onSelectBook(book)}
                  disabled={isLocked}
                  className={`w-full py-3 rounded-xl font-bold transition-all shadow-md 
                    ${isLocked 
                      ? 'bg-gray-200 text-gray-400 cursor-not-allowed dark:bg-gray-700 dark:text-gray-500'
                      : status === 'COMPLETED' 
                        ? 'bg-green-100 text-green-800 hover:bg-green-200 dark:bg-green-900/30 dark:text-green-300' 
                        : status === 'IN_PROGRESS' 
                          ? 'bg-brand-600 text-white hover:bg-brand-700 shadow-brand-500/20' 
                          : 'bg-gray-900 text-white hover:bg-gray-800 dark:bg-white dark:text-gray-900'
                    }`}
                >
                  {isLocked ? 'Locked' : status === 'COMPLETED' ? t('readAgain', user.languagePreference) : status === 'IN_PROGRESS' ? t('continueReading', user.languagePreference) : t('startReading', user.languagePreference)}
                </button>
              </div>
            </div>
          );
        })}

        {filteredBooks.length === 0 && (
          <div className="col-span-full py-12 text-center text-gray-400">
            No books found for this level.
          </div>
        )}
      </div>
    </div>
  );
};

export default Library;

import React, { useState, useEffect } from 'react';
import { Book, User, CEFRLevel, PlanConfig, PlanType, SubscriptionStatus, Chapter } from '../types';
import { getBooks, saveBook, deleteBook, getUsers, saveUser, deleteUser, getPlans, savePlans } from '../services/storage';
import { Trash2, Edit, Plus, Users, Book as BookIcon, Save, X, Archive, DollarSign, Lock, CheckSquare, Square, Loader2, Search, List, ChevronRight } from 'lucide-react';
import { t } from '../services/i18n';

interface AdminPanelProps {
  currentUser: User;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ currentUser }) => {
  const [activeTab, setActiveTab] = useState<'BOOKS' | 'USERS' | 'PLANS'>('BOOKS');

  // Data
  const [books, setBooks] = useState<Book[]>([]);
  const [users, setUsersList] = useState<User[]>([]);
  const [plans, setPlansList] = useState<PlanConfig[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  // Search State
  const [userSearchTerm, setUserSearchTerm] = useState('');

  // Forms
  const [isEditingBook, setIsEditingBook] = useState(false);
  const [currentBook, setCurrentBook] = useState<Partial<Book>>({});
  const [activeChapterId, setActiveChapterId] = useState<string | null>(null);

  const [isEditingUser, setIsEditingUser] = useState(false);
  const [targetUser, setTargetUser] = useState<Partial<User>>({});

  const [isEditingPlan, setIsEditingPlan] = useState(false);
  const [targetPlan, setTargetPlan] = useState<Partial<PlanConfig>>({});
  const [planFeaturesText, setPlanFeaturesText] = useState(''); 

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = async () => {
    setIsLoading(true);
    const [b, u, p] = await Promise.all([getBooks(), getUsers(), getPlans()]);
    setBooks(b);
    setUsersList(u);
    setPlansList(p);
    setIsLoading(false);
  };

  // --- Book Handlers ---
  const handleEditBook = (book?: Book) => {
    const initBook = book ? { ...book } : { 
      id: '', 
      title: '', 
      author: '', 
      level: 'A1' as CEFRLevel, 
      coverUrl: 'https://picsum.photos/300/450', 
      chapters: [], 
      excerpt: '', 
      totalWords: 0, 
      requiredPlan: ['FREE'], 
      archived: false 
    };
    setCurrentBook(initBook);

    // Set active chapter to first one if exists
    if (initBook.chapters && initBook.chapters.length > 0) {
      setActiveChapterId(initBook.chapters[0].id);
    } else {
      setActiveChapterId(null);
    }

    setIsEditingBook(true);
  };

  const togglePlanForBook = (plan: PlanType) => {
    const currentPlans = currentBook.requiredPlan || [];
    if (currentPlans.includes(plan)) {
      setCurrentBook({ ...currentBook, requiredPlan: currentPlans.filter(p => p !== plan) });
    } else {
      setCurrentBook({ ...currentBook, requiredPlan: [...currentPlans, plan] });
    }
  };

  // Chapter Logic
  const handleAddChapter = () => {
    // FIX: Added random suffix to prevent duplicate IDs when adding quickly
    const newChapter: Chapter = {
      id: `c-${Date.now()}-${Math.floor(Math.random() * 10000)}`,
      title: 'New Chapter',
      content: ''
    };
    const updatedChapters = [...(currentBook.chapters || []), newChapter];
    setCurrentBook({ ...currentBook, chapters: updatedChapters });
    setActiveChapterId(newChapter.id);
  };

  const handleDeleteChapter = (chapterId: string) => {
    if (!window.confirm("Delete this chapter?")) return;

    const updatedChapters = (currentBook.chapters || []).filter(c => c.id !== chapterId);

    // Update book state
    setCurrentBook(prev => ({ ...prev, chapters: updatedChapters }));

    // Update active selection logic
    if (activeChapterId === chapterId) {
       setActiveChapterId(updatedChapters.length > 0 ? updatedChapters[0].id : null);
    }
  };

  const updateChapter = (id: string, field: keyof Chapter, value: string) => {
     const updatedChapters = (currentBook.chapters || []).map(c => {
        if (c.id === id) return { ...c, [field]: value };
        return c;
     });
     setCurrentBook({ ...currentBook, chapters: updatedChapters });
  };

  const handleSaveBook = async () => {
    if (!currentBook.title || (currentBook.chapters?.length === 0)) return alert("Title and at least one chapter required.");

    // Recalculate total words
    const totalWords = (currentBook.chapters || []).reduce((acc, c) => acc + c.content.split(' ').length, 0);

    const bookToSave: Book = {
      id: currentBook.id || 'b-' + Date.now(),
      title: currentBook.title!,
      author: currentBook.author || 'Unknown',
      level: currentBook.level as CEFRLevel,
      coverUrl: currentBook.coverUrl || '',
      chapters: currentBook.chapters || [],
      excerpt: currentBook.excerpt || (currentBook.chapters?.[0]?.content.substring(0, 100) || ''),
      totalWords: totalWords,
      requiredPlan: currentBook.requiredPlan && currentBook.requiredPlan.length > 0 ? currentBook.requiredPlan : ['FREE'],
      archived: currentBook.archived || false
    };

    await saveBook(bookToSave);
    setIsEditingBook(false);
    refreshData();
  };

  const handleArchiveBook = async (book: Book) => {
    const updatedBook = { ...book, archived: !book.archived };
    await saveBook(updatedBook);
    refreshData();
  };

  const handleDeleteBook = async (id: string) => {
    if (confirm(t('confirmDelete', currentUser.languagePreference))) {
      await deleteBook(id);
      refreshData();
    }
  };

  // --- User Handlers ---
  const handleEditUser = (u?: User) => {
    setTargetUser(u || {
      id: '', name: '', email: '', role: 'USER', password: '', plan: 'FREE', subscriptionStatus: 'ACTIVE'
    });
    setIsEditingUser(true);
  };

  const handleSaveUser = async () => {
    if (!targetUser.email || !targetUser.name) return alert(t('fillAllFields', currentUser.languagePreference));

    // Simple email check for new users
    if (!targetUser.id) {
       const exists = users.find(u => u.email === targetUser.email);
       if(exists) return alert(t('emailExists', currentUser.languagePreference));
    }

    // Determine end date based on plan
    let endAt = targetUser.subscriptionEndsAt || Date.now();
    if (targetUser.plan !== 'FREE') {
       const planConfig = plans.find(p => p.id === targetUser.plan);
       if (planConfig) {
         endAt = Date.now() + (planConfig.durationDays * 24 * 60 * 60 * 1000);
       }
    }

    const userToSave: User = {
      id: targetUser.id || 'u-' + Date.now(),
      email: targetUser.email!,
      name: targetUser.name!,
      // Ensure password isn't lost if input was cleared by accident
      password: targetUser.password || '123456',
      role: (targetUser.role as any) || 'USER',
      languagePreference: targetUser.languagePreference || 'TR',
      streak: targetUser.streak || 0,
      xp: targetUser.xp || 0,
      dailyGoal: targetUser.dailyGoal || 25,
      lastVisitDate: targetUser.lastVisitDate || Date.now(),
      subscriptionStatus: targetUser.subscriptionStatus || 'ACTIVE',
      plan: targetUser.plan || 'FREE',
      trialEndsAt: targetUser.trialEndsAt || 0,
      subscriptionEndsAt: endAt
    };

    await saveUser(userToSave);
    setIsEditingUser(false);
    refreshData();
  };

  const handleDeleteUser = async (id: string) => {
    if (id === currentUser.id) return alert("You cannot delete yourself.");
    if (confirm(t('confirmDelete', currentUser.languagePreference))) {
      await deleteUser(id);
      refreshData();
    }
  };

  // --- Plan Handlers ---
  const handleEditPlan = (p?: PlanConfig) => {
    if (p) {
        setTargetPlan(p);
        setPlanFeaturesText(p.features.join('\n'));
    } else {
        setTargetPlan({ id: '', name: '', price: 0, durationDays: 30, features: [] });
        setPlanFeaturesText('');
    }
    setIsEditingPlan(true);
  };

  const handleDeletePlan = async (id: string) => {
      if (confirm("Are you sure you want to delete this plan?")) {
          const updatedPlans = plans.filter(p => p.id !== id);
          await savePlans(updatedPlans);
          refreshData();
      }
  };

  const handleSavePlan = async () => {
    if (!targetPlan.name) return alert("Plan name is required");

    const featuresArray = planFeaturesText.split('\n').map(f => f.trim()).filter(f => f.length > 0);

    const planId = targetPlan.id || targetPlan.name?.toUpperCase().replace(/\s+/g, '_') || 'NEW_PLAN';

    const newPlanConfig: PlanConfig = {
        id: planId,
        name: targetPlan.name!,
        price: targetPlan.price || 0,
        durationDays: targetPlan.durationDays || 30,
        features: featuresArray
    };

    // Since Firebase update logic for plans is bulk in current storage.ts implementation for simplicity
    // We update the local array then save all
    let updatedPlans = [...plans];
    const index = updatedPlans.findIndex(p => p.id === planId);

    if (index >= 0) {
        updatedPlans[index] = newPlanConfig;
    } else {
        updatedPlans.push(newPlanConfig);
    }

    await savePlans(updatedPlans);
    setIsEditingPlan(false);
    refreshData();
  };

  const lang = currentUser.languagePreference;

  // Filter Users
  const filteredUsers = users.filter(u => 
    u.name.toLowerCase().includes(userSearchTerm.toLowerCase()) || 
    u.email.toLowerCase().includes(userSearchTerm.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h1 className="text-3xl font-bold dark:text-white flex items-center">
            {t('adminPanel', lang)}
            {isLoading && <Loader2 className="ml-3 animate-spin text-brand-500" />}
        </h1>
      </div>

      <div className="flex space-x-4 mb-6">
        <button 
          onClick={() => setActiveTab('BOOKS')}
          className={`px-6 py-3 rounded-xl font-bold flex items-center ${activeTab === 'BOOKS' ? 'bg-brand-600 text-white' : 'bg-white dark:bg-gray-800 text-gray-600 dark:text-gray-300'}`}
        >
          <BookIcon size={20} className="mr-2" /> {t('adminBooks', lang)}
        </button>
        <button 
          onClick={() => setActiveTab('USERS')}
          className={`px-6 py-3 rounded-xl font-bold flex items-center ${activeTab === 'USERS' ? 'bg-brand-600 text-white' : 'bg-white dark:bg-gray-800 text-gray-600 dark:text-gray-300'}`}
        >
          <Users size={20} className="mr-2" /> {t('adminUsers', lang)}
        </button>
        <button 
          onClick={() => setActiveTab('PLANS')}
          className={`px-6 py-3 rounded-xl font-bold flex items-center ${activeTab === 'PLANS' ? 'bg-brand-600 text-white' : 'bg-white dark:bg-gray-800 text-gray-600 dark:text-gray-300'}`}
        >
          <DollarSign size={20} className="mr-2" /> Paketler
        </button>
      </div>

      {/* --- BOOKS TAB --- */}
      {activeTab === 'BOOKS' && (
        <div className="bg-white dark:bg-gray-800 rounded-3xl p-6 border border-gray-100 dark:border-gray-700 shadow-sm">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-xl font-bold dark:text-white">Books List ({books.length})</h2>
            <button onClick={() => handleEditBook()} className="px-4 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg font-bold flex items-center">
              <Plus size={18} className="mr-2" /> {t('addBook', lang)}
            </button>
          </div>

          {isEditingBook ? (
            <div className="bg-gray-50 dark:bg-gray-900 p-6 rounded-2xl animate-in slide-in-from-top-4">
               <h3 className="font-bold text-lg mb-4 dark:text-white">{currentBook.id ? t('edit', lang) : t('addBook', lang)}</h3>
               <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
                 <div>
                   <label className="block text-sm font-bold text-gray-500 mb-1">{t('title', lang)}</label>
                   <input className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white" value={currentBook.title || ''} onChange={e => setCurrentBook({...currentBook, title: e.target.value})} />
                 </div>
                 <div>
                   <label className="block text-sm font-bold text-gray-500 mb-1">{t('author', lang)}</label>
                   <input className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white" value={currentBook.author || ''} onChange={e => setCurrentBook({...currentBook, author: e.target.value})} />
                 </div>
                 <div>
                   <label className="block text-sm font-bold text-gray-500 mb-1">{t('level', lang)}</label>
                   <select className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white" value={currentBook.level || 'A1'} onChange={e => setCurrentBook({...currentBook, level: e.target.value as CEFRLevel})}>
                      {['A1','A2','B1','B2','C1','C2'].map(l => <option key={l} value={l}>{l}</option>)}
                   </select>
                 </div>
                 <div>
                   <label className="block text-sm font-bold text-gray-500 mb-1">{t('coverUrl', lang)}</label>
                   <input className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white" value={currentBook.coverUrl || ''} onChange={e => setCurrentBook({...currentBook, coverUrl: e.target.value})} />
                 </div>
                 <div className="col-span-full">
                   <label className="block text-sm font-bold text-gray-500 mb-1">{t('excerpt', lang)}</label>
                   <input className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white" value={currentBook.excerpt || ''} onChange={e => setCurrentBook({...currentBook, excerpt: e.target.value})} />
                 </div>

                 <div className="col-span-full">
                   <label className="block text-sm font-bold text-gray-500 mb-2">Required Plans</label>
                   <div className="flex gap-4 flex-wrap">
                      {plans.map((plan) => (
                        <button
                          key={plan.id}
                          onClick={() => togglePlanForBook(plan.id)}
                          className={`flex items-center px-4 py-2 rounded-lg border-2 font-bold transition-all ${
                            (currentBook.requiredPlan || []).includes(plan.id)
                              ? 'border-brand-500 bg-brand-50 text-brand-700 dark:bg-brand-900/30 dark:text-brand-300'
                              : 'border-gray-200 dark:border-gray-700 text-gray-500 hover:border-gray-300'
                          }`}
                        >
                          {(currentBook.requiredPlan || []).includes(plan.id) ? (
                            <CheckSquare size={20} className="mr-2" />
                          ) : (
                            <Square size={20} className="mr-2" />
                          )}
                          {plan.name}
                        </button>
                      ))}
                   </div>
                 </div>
               </div>

               {/* CHAPTER MANAGEMENT */}
               <div className="border-t border-gray-200 dark:border-gray-700 pt-6">
                  <div className="flex justify-between items-center mb-4">
                     <h4 className="font-bold text-lg dark:text-white flex items-center"><List className="mr-2" /> Chapters</h4>
                     <button onClick={handleAddChapter} className="text-sm bg-brand-100 text-brand-600 px-3 py-1 rounded-lg font-bold hover:bg-brand-200 flex items-center">
                        <Plus size={14} className="mr-1" /> Add Chapter
                     </button>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                     {/* Chapter List Sidebar */}
                     <div className="space-y-2 max-h-[400px] overflow-y-auto pr-2">
                        {(currentBook.chapters || []).map((chapter, idx) => (
                           <div 
                             key={chapter.id}
                             onClick={() => setActiveChapterId(chapter.id)}
                             className={`p-3 rounded-lg border cursor-pointer flex justify-between items-center group ${
                                activeChapterId === chapter.id 
                                ? 'bg-brand-600 text-white border-brand-600' 
                                : 'bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700 hover:border-brand-300'
                             }`}
                           >
                              <div className="truncate pr-2">
                                 <span className="font-black text-xs opacity-70 mr-2">{idx + 1}.</span>
                                 <span className="font-bold text-sm">{chapter.title || 'Untitled'}</span>
                              </div>
                              <button 
                                type="button" 
                                onClick={(e) => { e.stopPropagation(); handleDeleteChapter(chapter.id); }} 
                                className={`p-1 rounded hover:bg-red-500 hover:text-white ${activeChapterId === chapter.id ? 'text-white/70' : 'text-gray-400'}`}
                              >
                                 <Trash2 size={14} />
                              </button>
                           </div>
                        ))}
                        {(currentBook.chapters || []).length === 0 && (
                           <p className="text-sm text-gray-400 text-center py-4">No chapters added.</p>
                        )}
                     </div>

                     {/* Chapter Editor */}
                     <div className="md:col-span-2 bg-white dark:bg-gray-800 p-4 rounded-xl border border-gray-200 dark:border-gray-700">
                        {activeChapterId ? (
                           (() => {
                              const chapter = (currentBook.chapters || []).find(c => c.id === activeChapterId);
                              if (!chapter) return null;
                              return (
                                 <div className="space-y-4">
                                    <div>
                                       <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Chapter Title</label>
                                       <input 
                                          className="w-full p-2 border rounded dark:bg-gray-900 dark:text-white font-bold" 
                                          value={chapter.title} 
                                          onChange={(e) => updateChapter(chapter.id, 'title', e.target.value)} 
                                       />
                                    </div>
                                    <div>
                                       <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Content</label>
                                       <textarea 
                                          rows={12} 
                                          className="w-full p-3 border rounded dark:bg-gray-900 dark:text-white font-mono text-sm leading-relaxed" 
                                          value={chapter.content} 
                                          onChange={(e) => updateChapter(chapter.id, 'content', e.target.value)} 
                                          placeholder="Enter chapter text..."
                                       />
                                    </div>
                                 </div>
                              );
                           })()
                        ) : (
                           <div className="h-full flex items-center justify-center text-gray-400 font-bold text-sm">Select or add a chapter</div>
                        )}
                     </div>
                  </div>
               </div>

               <div className="flex justify-end gap-3 mt-8 border-t border-gray-200 dark:border-gray-700 pt-4">
                 <button onClick={() => setIsEditingBook(false)} className="px-4 py-2 bg-gray-300 text-gray-800 rounded-lg font-bold">{t('cancel', lang)}</button>
                 <button onClick={handleSaveBook} className="px-4 py-2 bg-brand-600 text-white rounded-lg font-bold">{t('save', lang)}</button>
               </div>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-gray-50 dark:bg-gray-900/50">
                   <tr>
                     <th className="p-3">Img</th>
                     <th className="p-3">{t('title', lang)}</th>
                     <th className="p-3">Chapters</th>
                     <th className="p-3">Access</th>
                     <th className="p-3">Status</th>
                     <th className="p-3">{t('actions', lang)}</th>
                   </tr>
                </thead>
                <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                  {books.map(b => (
                    <tr key={b.id} className={b.archived ? 'opacity-50 bg-gray-50 dark:bg-gray-900' : ''}>
                      <td className="p-3"><img src={b.coverUrl} className="w-10 h-14 object-cover rounded" /></td>
                      <td className="p-3 font-bold dark:text-white">{b.title}</td>
                      <td className="p-3 dark:text-white">{b.chapters?.length || 0}</td>
                      <td className="p-3">
                        <div className="flex flex-wrap gap-1">
                          {b.requiredPlan.map(p => (
                             <span key={p} className={`px-2 py-1 rounded text-xs font-bold bg-blue-100 text-blue-700`}>
                               {p}
                             </span>
                          ))}
                        </div>
                      </td>
                      <td className="p-3">
                        {b.archived ? <span className="text-red-500 font-bold text-xs flex items-center"><Archive size={12} className="mr-1"/> Archived</span> : <span className="text-green-500 font-bold text-xs">Active</span>}
                      </td>
                      <td className="p-3 flex gap-2">
                        <button onClick={() => handleEditBook(b)} className="p-2 bg-blue-100 text-blue-600 rounded hover:bg-blue-200"><Edit size={16} /></button>
                        <button onClick={() => handleArchiveBook(b)} className="p-2 bg-yellow-100 text-yellow-600 rounded hover:bg-yellow-200" title="Archive/Unarchive">
                           <Archive size={16} />
                        </button>
                        <button onClick={() => handleDeleteBook(b.id)} className="p-2 bg-red-100 text-red-600 rounded hover:bg-red-200"><Trash2 size={16} /></button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {/* --- USERS TAB --- */}
      {activeTab === 'USERS' && (
        <div className="bg-white dark:bg-gray-800 rounded-3xl p-6 border border-gray-100 dark:border-gray-700 shadow-sm">
           <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
            <h2 className="text-xl font-bold dark:text-white whitespace-nowrap">User List ({users.length})</h2>
            <div className="flex gap-2 w-full md:w-auto">
                <div className="relative flex-1 md:w-64">
                    <Search className="absolute left-3 top-2.5 text-gray-400" size={18} />
                    <input 
                        type="text" 
                        placeholder="Search name or email..." 
                        value={userSearchTerm}
                        onChange={(e) => setUserSearchTerm(e.target.value)}
                        className="w-full pl-10 pr-4 py-2 border rounded-lg dark:bg-gray-900 dark:border-gray-700 dark:text-white outline-none focus:ring-2 focus:ring-brand-500"
                    />
                </div>
                <button onClick={() => handleEditUser()} className="px-4 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg font-bold flex items-center whitespace-nowrap">
                  <Plus size={18} className="mr-2" /> {t('addUser', lang)}
                </button>
            </div>
          </div>

          {isEditingUser ? (
             <div className="bg-gray-50 dark:bg-gray-900 p-6 rounded-2xl animate-in slide-in-from-top-4">
                <h3 className="font-bold text-lg mb-4 dark:text-white">{targetUser.id ? t('edit', lang) : t('addUser', lang)}</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-bold text-gray-500 mb-1">{t('email', lang)}</label>
                    <input className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white" value={targetUser.email || ''} onChange={e => setTargetUser({...targetUser, email: e.target.value})} disabled={!!targetUser.id} />
                  </div>
                  <div>
                    <label className="block text-sm font-bold text-gray-500 mb-1">{t('displayName', lang)}</label>
                    <input className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white" value={targetUser.name || ''} onChange={e => setTargetUser({...targetUser, name: e.target.value})} />
                  </div>
                  <div>
                    <label className="block text-sm font-bold text-gray-500 mb-1">{t('password', lang)}</label>
                    <input className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white" value={targetUser.password || ''} onChange={e => setTargetUser({...targetUser, password: e.target.value})} placeholder={targetUser.id ? "Leave blank to keep same" : "Required"} />
                  </div>
                   <div>
                   <label className="block text-sm font-bold text-gray-500 mb-1">{t('role', lang)}</label>
                   <select className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white" value={targetUser.role || 'USER'} onChange={e => setTargetUser({...targetUser, role: e.target.value as any})}>
                      <option value="USER">USER</option>
                      <option value="ADMIN">ADMIN</option>
                   </select>
                 </div>

                 <div className="col-span-full border-t border-gray-200 dark:border-gray-700 pt-4 mt-2">
                    <h4 className="font-bold text-brand-600 mb-3">Subscription Management</h4>
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-sm font-bold text-gray-500 mb-1">Plan</label>
                        <select className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white" value={targetUser.plan || 'FREE'} onChange={e => setTargetUser({...targetUser, plan: e.target.value as PlanType})}>
                           {plans.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                        </select>
                      </div>
                      <div>
                        <label className="block text-sm font-bold text-gray-500 mb-1">Status</label>
                        <select className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white" value={targetUser.subscriptionStatus || 'ACTIVE'} onChange={e => setTargetUser({...targetUser, subscriptionStatus: e.target.value as SubscriptionStatus})}>
                            <option value="ACTIVE">ACTIVE</option>
                            <option value="TRIAL">TRIAL</option>
                            <option value="EXPIRED">EXPIRED</option>
                        </select>
                      </div>
                    </div>
                 </div>

                </div>
                <div className="flex justify-end gap-3 mt-4">
                 <button onClick={() => setIsEditingUser(false)} className="px-4 py-2 bg-gray-300 text-gray-800 rounded-lg font-bold">{t('cancel', lang)}</button>
                 <button onClick={handleSaveUser} className="px-4 py-2 bg-brand-600 text-white rounded-lg font-bold">{t('save', lang)}</button>
               </div>
             </div>
          ) : (
             <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-gray-50 dark:bg-gray-900/50">
                   <tr>
                     <th className="p-3">{t('email', lang)}</th>
                     <th className="p-3">{t('displayName', lang)}</th>
                     <th className="p-3">Plan</th>
                     <th className="p-3">Status</th>
                     <th className="p-3">{t('actions', lang)}</th>
                   </tr>
                </thead>
                <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                  {filteredUsers.map(u => (
                    <tr key={u.id}>
                      <td className="p-3 dark:text-white">{u.email}</td>
                      <td className="p-3 font-bold dark:text-white">{u.name}</td>
                      <td className="p-3"><span className="bg-brand-50 text-brand-600 px-2 py-1 rounded text-xs font-bold">{u.plan}</span></td>
                       <td className="p-3"><span className={`px-2 py-1 rounded text-xs font-bold ${u.subscriptionStatus === 'ACTIVE' ? 'bg-green-100 text-green-600' : 'bg-orange-100 text-orange-600'}`}>{u.subscriptionStatus}</span></td>
                      <td className="p-3 flex gap-2">
                        <button onClick={() => handleEditUser(u)} className="p-2 bg-blue-100 text-blue-600 rounded hover:bg-blue-200"><Edit size={16} /></button>
                        {u.role !== 'ADMIN' && (
                           <button onClick={() => handleDeleteUser(u.id)} className="p-2 bg-red-100 text-red-600 rounded hover:bg-red-200"><Trash2 size={16} /></button>
                        )}
                      </td>
                    </tr>
                  ))}
                  {filteredUsers.length === 0 && (
                      <tr>
                          <td colSpan={5} className="p-8 text-center text-gray-500 font-bold">
                             No users found matching "{userSearchTerm}"
                          </td>
                      </tr>
                  )}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {/* --- PLANS TAB --- */}
      {activeTab === 'PLANS' && (
         <div className="bg-white dark:bg-gray-800 rounded-3xl p-6 border border-gray-100 dark:border-gray-700 shadow-sm">
             <div className="flex justify-between items-center mb-6">
                <h2 className="text-xl font-bold dark:text-white">Manage Subscription Plans</h2>
                <button onClick={() => handleEditPlan()} className="px-4 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg font-bold flex items-center">
                   <Plus size={18} className="mr-2" /> Add Plan
                </button>
            </div>

            {isEditingPlan ? (
              <div className="bg-gray-50 dark:bg-gray-900 p-6 rounded-2xl animate-in slide-in-from-top-4">
                  <h3 className="font-bold text-lg mb-4 dark:text-white">{targetPlan.id ? `Edit ${targetPlan.name}` : 'New Plan'}</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                     <div>
                        <label className="block text-sm font-bold text-gray-500 mb-1">Plan Name</label>
                        <input className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white" value={targetPlan.name} onChange={e => setTargetPlan({...targetPlan, name: e.target.value})} />
                     </div>
                     <div>
                        <label className="block text-sm font-bold text-gray-500 mb-1">Price</label>
                        <input type="number" step="0.01" className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white" value={targetPlan.price} onChange={e => setTargetPlan({...targetPlan, price: parseFloat(e.target.value)})} />
                     </div>
                     <div>
                        <label className="block text-sm font-bold text-gray-500 mb-1">Duration (Days)</label>
                        <input type="number" className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white" value={targetPlan.durationDays} onChange={e => setTargetPlan({...targetPlan, durationDays: parseInt(e.target.value)})} />
                     </div>
                     <div className="col-span-full">
                        <label className="block text-sm font-bold text-gray-500 mb-1">Features (One per line)</label>
                        <textarea 
                          rows={5}
                          className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white font-mono text-sm" 
                          value={planFeaturesText} 
                          onChange={e => setPlanFeaturesText(e.target.value)} 
                          placeholder="Unlimited Books&#10;Advanced Quizzes&#10;Offline Mode"
                        />
                     </div>
                  </div>
                  <div className="flex justify-end gap-3 mt-4">
                     <button onClick={() => setIsEditingPlan(false)} className="px-4 py-2 bg-gray-300 text-gray-800 rounded-lg font-bold">{t('cancel', lang)}</button>
                     <button onClick={handleSavePlan} className="px-4 py-2 bg-brand-600 text-white rounded-lg font-bold">{t('save', lang)}</button>
                  </div>
              </div>
            ) : (
               <div className="overflow-x-auto">
                 <table className="w-full text-left">
                   <thead className="bg-gray-50 dark:bg-gray-900/50">
                      <tr>
                        <th className="p-3">ID</th>
                        <th className="p-3">Name</th>
                        <th className="p-3">Price</th>
                        <th className="p-3">Duration</th>
                        <th className="p-3">Features Count</th>
                        <th className="p-3">Actions</th>
                      </tr>
                   </thead>
                   <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                     {plans.map(p => (
                       <tr key={p.id}>
                         <td className="p-3 font-mono text-sm dark:text-white">{p.id}</td>
                         <td className="p-3 font-bold dark:text-white">{p.name}</td>
                         <td className="p-3 text-brand-600 font-bold">${p.price}</td>
                         <td className="p-3 dark:text-gray-400">{p.durationDays} Days</td>
                         <td className="p-3 dark:text-gray-400">{p.features.length}</td>
                         <td className="p-3 flex gap-2">
                           <button onClick={() => handleEditPlan(p)} className="p-2 bg-blue-100 text-blue-600 rounded hover:bg-blue-200"><Edit size={16} /></button>
                           <button onClick={() => handleDeletePlan(p.id)} className="p-2 bg-red-100 text-red-600 rounded hover:bg-red-200"><Trash2 size={16} /></button>
                         </td>
                       </tr>
                     ))}
                   </tbody>
                 </table>
               </div>
            )}
         </div>
      )}
    </div>
  );
};

export default AdminPanel;

import React, { useState, useEffect } from 'react';
import { Book, User, CEFRLevel, PlanConfig, PlanType, SubscriptionStatus, Chapter } from '../types';
import { getBooks, saveBook, deleteBook, getUsers, saveUser, deleteUser, getPlans, savePlans } from '../services/storage';
import { Trash2, Edit, Plus, Users, Book as BookIcon, Save, X, Archive, DollarSign, Lock, CheckSquare, Square, Loader2, Search, List, ChevronRight } from 'lucide-react';
import { t } from '../services/i18n';

interface AdminPanelProps {
  currentUser: User;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ currentUser }) => {
  const [activeTab, setActiveTab] = useState<'BOOKS' | 'USERS' | 'PLANS'>('BOOKS');

  // Data
  const [books, setBooks] = useState<Book[]>([]);
  const [users, setUsersList] = useState<User[]>([]);
  const [plans, setPlansList] = useState<PlanConfig[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  // Search State
  const [userSearchTerm, setUserSearchTerm] = useState('');

  // Forms
  const [isEditingBook, setIsEditingBook] = useState(false);
  const [currentBook, setCurrentBook] = useState<Partial<Book>>({});
  const [activeChapterId, setActiveChapterId] = useState<string | null>(null);

  const [isEditingUser, setIsEditingUser] = useState(false);
  const [targetUser, setTargetUser] = useState<Partial<User>>({});

  const [isEditingPlan, setIsEditingPlan] = useState(false);
  const [targetPlan, setTargetPlan] = useState<Partial<PlanConfig>>({});
  const [planFeaturesText, setPlanFeaturesText] = useState(''); 

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = async () => {
    setIsLoading(true);
    const [b, u, p] = await Promise.all([getBooks(), getUsers(), getPlans()]);
    setBooks(b);
    setUsersList(u);
    setPlansList(p);
    setIsLoading(false);
  };

  // --- Book Handlers ---
  const handleEditBook = (book?: Book) => {
    const initBook = book ? { ...book } : { 
      id: '', 
      title: '', 
      author: '', 
      level: 'A1' as CEFRLevel, 
      coverUrl: 'https://picsum.photos/300/450', 
      chapters: [], 
      excerpt: '', 
      totalWords: 0, 
      requiredPlan: ['FREE'], 
      archived: false 
    };
    setCurrentBook(initBook);

    // Set active chapter to first one if exists
    if (initBook.chapters && initBook.chapters.length > 0) {
      setActiveChapterId(initBook.chapters[0].id);
    } else {
      setActiveChapterId(null);
    }

    setIsEditingBook(true);
  };

  const togglePlanForBook = (plan: PlanType) => {
    const currentPlans = currentBook.requiredPlan || [];
    if (currentPlans.includes(plan)) {
      setCurrentBook({ ...currentBook, requiredPlan: currentPlans.filter(p => p !== plan) });
    } else {
      setCurrentBook({ ...currentBook, requiredPlan: [...currentPlans, plan] });
    }
  };

  // Chapter Logic
  const handleAddChapter = () => {
    const newChapter: Chapter = {
      // Ensure completely unique ID even if clicked rapidly
      id: `c-${Date.now()}-${Math.floor(Math.random() * 99999)}`,
      title: 'New Chapter',
      content: ''
    };

    setCurrentBook(prevBook => {
        const updatedChapters = [...(prevBook.chapters || []), newChapter];
        return { ...prevBook, chapters: updatedChapters };
    });

    // Immediately select the new chapter
    setActiveChapterId(newChapter.id);
  };

  const handleDeleteChapter = (chapterId: string) => {
    if (!window.confirm("Delete this chapter?")) return;

    // Calculate new chapters based on current state
    const currentChapters = currentBook.chapters || [];
    const updatedChapters = currentChapters.filter(c => c.id !== chapterId);

    // Update Book State
    setCurrentBook(prev => ({ ...prev, chapters: updatedChapters }));

    // If the deleted chapter was active, switch to another one
    if (activeChapterId === chapterId) {
       const nextId = updatedChapters.length > 0 ? updatedChapters[0].id : null;
       setActiveChapterId(nextId);
    }
  };

  const updateChapter = (id: string, field: keyof Chapter, value: string) => {
     setCurrentBook(prev => {
        const updatedChapters = (prev.chapters || []).map(c => {
            if (c.id === id) return { ...c, [field]: value };
            return c;
        });
        return { ...prev, chapters: updatedChapters };
     });
  };

  const handleSaveBook = async () => {
    if (!currentBook.title || (currentBook.chapters?.length === 0)) return alert("Title and at least one chapter required.");

    // Recalculate total words
    const totalWords = (currentBook.chapters || []).reduce((acc, c) => acc + c.content.split(' ').length, 0);

    const bookToSave: Book = {
      id: currentBook.id || 'b-' + Date.now(),
      title: currentBook.title!,
      author: currentBook.author || 'Unknown',
      level: currentBook.level as CEFRLevel,
      coverUrl: currentBook.coverUrl || '',
      chapters: currentBook.chapters || [],
      excerpt: currentBook.excerpt || (currentBook.chapters?.[0]?.content.substring(0, 100) || ''),
      totalWords: totalWords,
      requiredPlan: currentBook.requiredPlan && currentBook.requiredPlan.length > 0 ? currentBook.requiredPlan : ['FREE'],
      archived: currentBook.archived || false
    };

    await saveBook(bookToSave);
    setIsEditingBook(false);
    refreshData();
  };

  const handleArchiveBook = async (book: Book) => {
    const updatedBook = { ...book, archived: !book.archived };
    await saveBook(updatedBook);
    refreshData();
  };

  const handleDeleteBook = async (id: string) => {
    if (confirm(t('confirmDelete', currentUser.languagePreference))) {
      await deleteBook(id);
      refreshData();
    }
  };

  // --- User Handlers ---
  const handleEditUser = (u?: User) => {
    setTargetUser(u || {
      id: '', name: '', email: '', role: 'USER', password: '', plan: 'FREE', subscriptionStatus: 'ACTIVE'
    });
    setIsEditingUser(true);
  };

  const handleSaveUser = async () => {
    if (!targetUser.email || !targetUser.name) return alert(t('fillAllFields', currentUser.languagePreference));

    // Simple email check for new users
    if (!targetUser.id) {
       const exists = users.find(u => u.email === targetUser.email);
       if(exists) return alert(t('emailExists', currentUser.languagePreference));
    }

    // Determine end date based on plan
    let endAt = targetUser.subscriptionEndsAt || Date.now();
    if (targetUser.plan !== 'FREE') {
       const planConfig = plans.find(p => p.id === targetUser.plan);
       if (planConfig) {
         endAt = Date.now() + (planConfig.durationDays * 24 * 60 * 60 * 1000);
       }
    }

    const userToSave: User = {
      id: targetUser.id || 'u-' + Date.now(),
      email: targetUser.email!,
      name: targetUser.name!,
      // Ensure password isn't lost if input was cleared by accident
      password: targetUser.password || '123456',
      role: (targetUser.role as any) || 'USER',
      languagePreference: targetUser.languagePreference || 'TR',
      streak: targetUser.streak || 0,
      xp: targetUser.xp || 0,
      dailyGoal: targetUser.dailyGoal || 25,
      lastVisitDate: targetUser.lastVisitDate || Date.now(),
      subscriptionStatus: targetUser.subscriptionStatus || 'ACTIVE',
      plan: targetUser.plan || 'FREE',
      trialEndsAt: targetUser.trialEndsAt || 0,
      subscriptionEndsAt: endAt
    };

    await saveUser(userToSave);
    setIsEditingUser(false);
    refreshData();
  };

  const handleDeleteUser = async (id: string) => {
    if (id === currentUser.id) return alert("You cannot delete yourself.");
    if (confirm(t('confirmDelete', currentUser.languagePreference))) {
      await deleteUser(id);
      refreshData();
    }
  };

  // --- Plan Handlers ---
  const handleEditPlan = (p?: PlanConfig) => {
    if (p) {
        setTargetPlan(p);
        setPlanFeaturesText(p.features.join('\n'));
    } else {
        setTargetPlan({ id: '', name: '', price: 0, durationDays: 30, features: [] });
        setPlanFeaturesText('');
    }
    setIsEditingPlan(true);
  };

  const handleDeletePlan = async (id: string) => {
      if (confirm("Are you sure you want to delete this plan?")) {
          const updatedPlans = plans.filter(p => p.id !== id);
          await savePlans(updatedPlans);
          refreshData();
      }
  };

  const handleSavePlan = async () => {
    if (!targetPlan.name) return alert("Plan name is required");

    const featuresArray = planFeaturesText.split('\n').map(f => f.trim()).filter(f => f.length > 0);

    const planId = targetPlan.id || targetPlan.name?.toUpperCase().replace(/\s+/g, '_') || 'NEW_PLAN';

    const newPlanConfig: PlanConfig = {
        id: planId,
        name: targetPlan.name!,
        price: targetPlan.price || 0,
        durationDays: targetPlan.durationDays || 30,
        features: featuresArray
    };

    // Since Firebase update logic for plans is bulk in current storage.ts implementation for simplicity
    // We update the local array then save all
    let updatedPlans = [...plans];
    const index = updatedPlans.findIndex(p => p.id === planId);

    if (index >= 0) {
        updatedPlans[index] = newPlanConfig;
    } else {
        updatedPlans.push(newPlanConfig);
    }

    await savePlans(updatedPlans);
    setIsEditingPlan(false);
    refreshData();
  };

  const lang = currentUser.languagePreference;

  // Filter Users
  const filteredUsers = users.filter(u => 
    u.name.toLowerCase().includes(userSearchTerm.toLowerCase()) || 
    u.email.toLowerCase().includes(userSearchTerm.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h1 className="text-3xl font-bold dark:text-white flex items-center">
            {t('adminPanel', lang)}
            {isLoading && <Loader2 className="ml-3 animate-spin text-brand-500" />}
        </h1>
      </div>

      <div className="flex space-x-4 mb-6">
        <button 
          onClick={() => setActiveTab('BOOKS')}
          className={`px-6 py-3 rounded-xl font-bold flex items-center ${activeTab === 'BOOKS' ? 'bg-brand-600 text-white' : 'bg-white dark:bg-gray-800 text-gray-600 dark:text-gray-300'}`}
        >
          <BookIcon size={20} className="mr-2" /> {t('adminBooks', lang)}
        </button>
        <button 
          onClick={() => setActiveTab('USERS')}
          className={`px-6 py-3 rounded-xl font-bold flex items-center ${activeTab === 'USERS' ? 'bg-brand-600 text-white' : 'bg-white dark:bg-gray-800 text-gray-600 dark:text-gray-300'}`}
        >
          <Users size={20} className="mr-2" /> {t('adminUsers', lang)}
        </button>
        <button 
          onClick={() => setActiveTab('PLANS')}
          className={`px-6 py-3 rounded-xl font-bold flex items-center ${activeTab === 'PLANS' ? 'bg-brand-600 text-white' : 'bg-white dark:bg-gray-800 text-gray-600 dark:text-gray-300'}`}
        >
          <DollarSign size={20} className="mr-2" /> Paketler
        </button>
      </div>

      {/* --- BOOKS TAB --- */}
      {activeTab === 'BOOKS' && (
        <div className="bg-white dark:bg-gray-800 rounded-3xl p-6 border border-gray-100 dark:border-gray-700 shadow-sm">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-xl font-bold dark:text-white">Books List ({books.length})</h2>
            <button onClick={() => handleEditBook()} className="px-4 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg font-bold flex items-center">
              <Plus size={18} className="mr-2" /> {t('addBook', lang)}
            </button>
          </div>

          {isEditingBook ? (
            <div className="bg-gray-50 dark:bg-gray-900 p-6 rounded-2xl animate-in slide-in-from-top-4">
               <h3 className="font-bold text-lg mb-4 dark:text-white">{currentBook.id ? t('edit', lang) : t('addBook', lang)}</h3>
               <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
                 <div>
                   <label className="block text-sm font-bold text-gray-500 mb-1">{t('title', lang)}</label>
                   <input className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white" value={currentBook.title || ''} onChange={e => setCurrentBook({...currentBook, title: e.target.value})} />
                 </div>
                 <div>
                   <label className="block text-sm font-bold text-gray-500 mb-1">{t('author', lang)}</label>
                   <input className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white" value={currentBook.author || ''} onChange={e => setCurrentBook({...currentBook, author: e.target.value})} />
                 </div>
                 <div>
                   <label className="block text-sm font-bold text-gray-500 mb-1">{t('level', lang)}</label>
                   <select className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white" value={currentBook.level || 'A1'} onChange={e => setCurrentBook({...currentBook, level: e.target.value as CEFRLevel})}>
                      {['A1','A2','B1','B2','C1','C2'].map(l => <option key={l} value={l}>{l}</option>)}
                   </select>
                 </div>
                 <div>
                   <label className="block text-sm font-bold text-gray-500 mb-1">{t('coverUrl', lang)}</label>
                   <input className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white" value={currentBook.coverUrl || ''} onChange={e => setCurrentBook({...currentBook, coverUrl: e.target.value})} />
                 </div>
                 <div className="col-span-full">
                   <label className="block text-sm font-bold text-gray-500 mb-1">{t('excerpt', lang)}</label>
                   <input className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white" value={currentBook.excerpt || ''} onChange={e => setCurrentBook({...currentBook, excerpt: e.target.value})} />
                 </div>

                 <div className="col-span-full">
                   <label className="block text-sm font-bold text-gray-500 mb-2">Required Plans</label>
                   <div className="flex gap-4 flex-wrap">
                      {plans.map((plan) => (
                        <button
                          key={plan.id}
                          onClick={() => togglePlanForBook(plan.id)}
                          className={`flex items-center px-4 py-2 rounded-lg border-2 font-bold transition-all ${
                            (currentBook.requiredPlan || []).includes(plan.id)
                              ? 'border-brand-500 bg-brand-50 text-brand-700 dark:bg-brand-900/30 dark:text-brand-300'
                              : 'border-gray-200 dark:border-gray-700 text-gray-500 hover:border-gray-300'
                          }`}
                        >
                          {(currentBook.requiredPlan || []).includes(plan.id) ? (
                            <CheckSquare size={20} className="mr-2" />
                          ) : (
                            <Square size={20} className="mr-2" />
                          )}
                          {plan.name}
                        </button>
                      ))}
                   </div>
                 </div>
               </div>

               {/* CHAPTER MANAGEMENT */}
               <div className="border-t border-gray-200 dark:border-gray-700 pt-6">
                  <div className="flex justify-between items-center mb-4">
                     <h4 className="font-bold text-lg dark:text-white flex items-center"><List className="mr-2" /> Chapters</h4>
                     <button 
                       type="button" 
                       onClick={handleAddChapter} 
                       className="text-sm bg-brand-100 text-brand-600 px-3 py-1 rounded-lg font-bold hover:bg-brand-200 flex items-center"
                     >
                        <Plus size={14} className="mr-1" /> Add Chapter
                     </button>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                     {/* Chapter List Sidebar */}
                     <div className="space-y-2 max-h-[400px] overflow-y-auto pr-2">
                        {(currentBook.chapters || []).map((chapter, idx) => (
                           <div 
                             key={chapter.id}
                             onClick={() => setActiveChapterId(chapter.id)}
                             className={`p-3 rounded-lg border cursor-pointer flex justify-between items-center group ${
                                activeChapterId === chapter.id 
                                ? 'bg-brand-600 text-white border-brand-600' 
                                : 'bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700 hover:border-brand-300'
                             }`}
                           >
                              <div className="truncate pr-2">
                                 <span className="font-black text-xs opacity-70 mr-2">{idx + 1}.</span>
                                 <span className="font-bold text-sm">{chapter.title || 'Untitled'}</span>
                              </div>
                              <button 
                                type="button" 
                                onClick={(e) => { e.stopPropagation(); handleDeleteChapter(chapter.id); }} 
                                className={`p-1 rounded hover:bg-red-500 hover:text-white ${activeChapterId === chapter.id ? 'text-white/70' : 'text-gray-400'}`}
                              >
                                 <Trash2 size={14} />
                              </button>
                           </div>
                        ))}
                        {(currentBook.chapters || []).length === 0 && (
                           <p className="text-sm text-gray-400 text-center py-4">No chapters added.</p>
                        )}
                     </div>

                     {/* Chapter Editor */}
                     <div className="md:col-span-2 bg-white dark:bg-gray-800 p-4 rounded-xl border border-gray-200 dark:border-gray-700">
                        {activeChapterId ? (
                           (() => {
                              const chapter = (currentBook.chapters || []).find(c => c.id === activeChapterId);
                              if (!chapter) return null;
                              return (
                                 <div className="space-y-4">
                                    <div>
                                       <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Chapter Title</label>
                                       <input 
                                          className="w-full p-2 border rounded dark:bg-gray-900 dark:text-white font-bold" 
                                          value={chapter.title} 
                                          onChange={(e) => updateChapter(chapter.id, 'title', e.target.value)} 
                                       />
                                    </div>
                                    <div>
                                       <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Content</label>
                                       <textarea 
                                          rows={12} 
                                          className="w-full p-3 border rounded dark:bg-gray-900 dark:text-white font-mono text-sm leading-relaxed" 
                                          value={chapter.content} 
                                          onChange={(e) => updateChapter(chapter.id, 'content', e.target.value)} 
                                          placeholder="Enter chapter text..."
                                       />
                                    </div>
                                 </div>
                              );
                           })()
                        ) : (
                           <div className="h-full flex items-center justify-center text-gray-400 font-bold text-sm">Select or add a chapter</div>
                        )}
                     </div>
                  </div>
               </div>

               <div className="flex justify-end gap-3 mt-8 border-t border-gray-200 dark:border-gray-700 pt-4">
                 <button onClick={() => setIsEditingBook(false)} className="px-4 py-2 bg-gray-300 text-gray-800 rounded-lg font-bold">{t('cancel', lang)}</button>
                 <button onClick={handleSaveBook} className="px-4 py-2 bg-brand-600 text-white rounded-lg font-bold">{t('save', lang)}</button>
               </div>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-gray-50 dark:bg-gray-900/50">
                   <tr>
                     <th className="p-3">Img</th>
                     <th className="p-3">{t('title', lang)}</th>
                     <th className="p-3">Chapters</th>
                     <th className="p-3">Access</th>
                     <th className="p-3">Status</th>
                     <th className="p-3">{t('actions', lang)}</th>
                   </tr>
                </thead>
                <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                  {books.map(b => (
                    <tr key={b.id} className={b.archived ? 'opacity-50 bg-gray-50 dark:bg-gray-900' : ''}>
                      <td className="p-3"><img src={b.coverUrl} className="w-10 h-14 object-cover rounded" /></td>
                      <td className="p-3 font-bold dark:text-white">{b.title}</td>
                      <td className="p-3 dark:text-white">{b.chapters?.length || 0}</td>
                      <td className="p-3">
                        <div className="flex flex-wrap gap-1">
                          {b.requiredPlan.map(p => (
                             <span key={p} className={`px-2 py-1 rounded text-xs font-bold bg-blue-100 text-blue-700`}>
                               {p}
                             </span>
                          ))}
                        </div>
                      </td>
                      <td className="p-3">
                        {b.archived ? <span className="text-red-500 font-bold text-xs flex items-center"><Archive size={12} className="mr-1"/> Archived</span> : <span className="text-green-500 font-bold text-xs">Active</span>}
                      </td>
                      <td className="p-3 flex gap-2">
                        <button onClick={() => handleEditBook(b)} className="p-2 bg-blue-100 text-blue-600 rounded hover:bg-blue-200"><Edit size={16} /></button>
                        <button onClick={() => handleArchiveBook(b)} className="p-2 bg-yellow-100 text-yellow-600 rounded hover:bg-yellow-200" title="Archive/Unarchive">
                           <Archive size={16} />
                        </button>
                        <button onClick={() => handleDeleteBook(b.id)} className="p-2 bg-red-100 text-red-600 rounded hover:bg-red-200"><Trash2 size={16} /></button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {/* --- USERS TAB --- */}
      {activeTab === 'USERS' && (
        <div className="bg-white dark:bg-gray-800 rounded-3xl p-6 border border-gray-100 dark:border-gray-700 shadow-sm">
           <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
            <h2 className="text-xl font-bold dark:text-white whitespace-nowrap">User List ({users.length})</h2>
            <div className="flex gap-2 w-full md:w-auto">
                <div className="relative flex-1 md:w-64">
                    <Search className="absolute left-3 top-2.5 text-gray-400" size={18} />
                    <input 
                        type="text" 
                        placeholder="Search name or email..." 
                        value={userSearchTerm}
                        onChange={(e) => setUserSearchTerm(e.target.value)}
                        className="w-full pl-10 pr-4 py-2 border rounded-lg dark:bg-gray-900 dark:border-gray-700 dark:text-white outline-none focus:ring-2 focus:ring-brand-500"
                    />
                </div>
                <button onClick={() => handleEditUser()} className="px-4 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg font-bold flex items-center whitespace-nowrap">
                  <Plus size={18} className="mr-2" /> {t('addUser', lang)}
                </button>
            </div>
          </div>

          {isEditingUser ? (
             <div className="bg-gray-50 dark:bg-gray-900 p-6 rounded-2xl animate-in slide-in-from-top-4">
                <h3 className="font-bold text-lg mb-4 dark:text-white">{targetUser.id ? t('edit', lang) : t('addUser', lang)}</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-bold text-gray-500 mb-1">{t('email', lang)}</label>
                    <input className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white" value={targetUser.email || ''} onChange={e => setTargetUser({...targetUser, email: e.target.value})} disabled={!!targetUser.id} />
                  </div>
                  <div>
                    <label className="block text-sm font-bold text-gray-500 mb-1">{t('displayName', lang)}</label>
                    <input className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white" value={targetUser.name || ''} onChange={e => setTargetUser({...targetUser, name: e.target.value})} />
                  </div>
                  <div>
                    <label className="block text-sm font-bold text-gray-500 mb-1">{t('password', lang)}</label>
                    <input className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white" value={targetUser.password || ''} onChange={e => setTargetUser({...targetUser, password: e.target.value})} placeholder={targetUser.id ? "Leave blank to keep same" : "Required"} />
                  </div>
                   <div>
                   <label className="block text-sm font-bold text-gray-500 mb-1">{t('role', lang)}</label>
                   <select className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white" value={targetUser.role || 'USER'} onChange={e => setTargetUser({...targetUser, role: e.target.value as any})}>
                      <option value="USER">USER</option>
                      <option value="ADMIN">ADMIN</option>
                   </select>
                 </div>

                 <div className="col-span-full border-t border-gray-200 dark:border-gray-700 pt-4 mt-2">
                    <h4 className="font-bold text-brand-600 mb-3">Subscription Management</h4>
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-sm font-bold text-gray-500 mb-1">Plan</label>
                        <select className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white" value={targetUser.plan || 'FREE'} onChange={e => setTargetUser({...targetUser, plan: e.target.value as PlanType})}>
                           {plans.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                        </select>
                      </div>
                      <div>
                        <label className="block text-sm font-bold text-gray-500 mb-1">Status</label>
                        <select className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white" value={targetUser.subscriptionStatus || 'ACTIVE'} onChange={e => setTargetUser({...targetUser, subscriptionStatus: e.target.value as SubscriptionStatus})}>
                            <option value="ACTIVE">ACTIVE</option>
                            <option value="TRIAL">TRIAL</option>
                            <option value="EXPIRED">EXPIRED</option>
                        </select>
                      </div>
                    </div>
                 </div>

                </div>
                <div className="flex justify-end gap-3 mt-4">
                 <button onClick={() => setIsEditingUser(false)} className="px-4 py-2 bg-gray-300 text-gray-800 rounded-lg font-bold">{t('cancel', lang)}</button>
                 <button onClick={handleSaveUser} className="px-4 py-2 bg-brand-600 text-white rounded-lg font-bold">{t('save', lang)}</button>
               </div>
             </div>
          ) : (
             <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-gray-50 dark:bg-gray-900/50">
                   <tr>
                     <th className="p-3">{t('email', lang)}</th>
                     <th className="p-3">{t('displayName', lang)}</th>
                     <th className="p-3">Plan</th>
                     <th className="p-3">Status</th>
                     <th className="p-3">{t('actions', lang)}</th>
                   </tr>
                </thead>
                <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                  {filteredUsers.map(u => (
                    <tr key={u.id}>
                      <td className="p-3 dark:text-white">{u.email}</td>
                      <td className="p-3 font-bold dark:text-white">{u.name}</td>
                      <td className="p-3"><span className="bg-brand-50 text-brand-600 px-2 py-1 rounded text-xs font-bold">{u.plan}</span></td>
                       <td className="p-3"><span className={`px-2 py-1 rounded text-xs font-bold ${u.subscriptionStatus === 'ACTIVE' ? 'bg-green-100 text-green-600' : 'bg-orange-100 text-orange-600'}`}>{u.subscriptionStatus}</span></td>
                      <td className="p-3 flex gap-2">
                        <button onClick={() => handleEditUser(u)} className="p-2 bg-blue-100 text-blue-600 rounded hover:bg-blue-200"><Edit size={16} /></button>
                        {u.role !== 'ADMIN' && (
                           <button onClick={() => handleDeleteUser(u.id)} className="p-2 bg-red-100 text-red-600 rounded hover:bg-red-200"><Trash2 size={16} /></button>
                        )}
                      </td>
                    </tr>
                  ))}
                  {filteredUsers.length === 0 && (
                      <tr>
                          <td colSpan={5} className="p-8 text-center text-gray-500 font-bold">
                             No users found matching "{userSearchTerm}"
                          </td>
                      </tr>
                  )}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {/* --- PLANS TAB --- */}
      {activeTab === 'PLANS' && (
         <div className="bg-white dark:bg-gray-800 rounded-3xl p-6 border border-gray-100 dark:border-gray-700 shadow-sm">
             <div className="flex justify-between items-center mb-6">
                <h2 className="text-xl font-bold dark:text-white">Manage Subscription Plans</h2>
                <button onClick={() => handleEditPlan()} className="px-4 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg font-bold flex items-center">
                   <Plus size={18} className="mr-2" /> Add Plan
                </button>
            </div>

            {isEditingPlan ? (
              <div className="bg-gray-50 dark:bg-gray-900 p-6 rounded-2xl animate-in slide-in-from-top-4">
                  <h3 className="font-bold text-lg mb-4 dark:text-white">{targetPlan.id ? `Edit ${targetPlan.name}` : 'New Plan'}</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                     <div>
                        <label className="block text-sm font-bold text-gray-500 mb-1">Plan Name</label>
                        <input className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white" value={targetPlan.name} onChange={e => setTargetPlan({...targetPlan, name: e.target.value})} />
                     </div>
                     <div>
                        <label className="block text-sm font-bold text-gray-500 mb-1">Price</label>
                        <input type="number" step="0.01" className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white" value={targetPlan.price} onChange={e => setTargetPlan({...targetPlan, price: parseFloat(e.target.value)})} />
                     </div>
                     <div>
                        <label className="block text-sm font-bold text-gray-500 mb-1">Duration (Days)</label>
                        <input type="number" className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white" value={targetPlan.durationDays} onChange={e => setTargetPlan({...targetPlan, durationDays: parseInt(e.target.value)})} />
                     </div>
                     <div className="col-span-full">
                        <label className="block text-sm font-bold text-gray-500 mb-1">Features (One per line)</label>
                        <textarea 
                          rows={5}
                          className="w-full p-2 border rounded dark:bg-gray-800 dark:text-white font-mono text-sm" 
                          value={planFeaturesText} 
                          onChange={e => setPlanFeaturesText(e.target.value)} 
                          placeholder="Unlimited Books&#10;Advanced Quizzes&#10;Offline Mode"
                        />
                     </div>
                  </div>
                  <div className="flex justify-end gap-3 mt-4">
                     <button onClick={() => setIsEditingPlan(false)} className="px-4 py-2 bg-gray-300 text-gray-800 rounded-lg font-bold">{t('cancel', lang)}</button>
                     <button onClick={handleSavePlan} className="px-4 py-2 bg-brand-600 text-white rounded-lg font-bold">{t('save', lang)}</button>
                  </div>
              </div>
            ) : (
               <div className="overflow-x-auto">
                 <table className="w-full text-left">
                   <thead className="bg-gray-50 dark:bg-gray-900/50">
                      <tr>
                        <th className="p-3">ID</th>
                        <th className="p-3">Name</th>
                        <th className="p-3">Price</th>
                        <th className="p-3">Duration</th>
                        <th className="p-3">Features Count</th>
                        <th className="p-3">Actions</th>
                      </tr>
                   </thead>
                   <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                     {plans.map(p => (
                       <tr key={p.id}>
                         <td className="p-3 font-mono text-sm dark:text-white">{p.id}</td>
                         <td className="p-3 font-bold dark:text-white">{p.name}</td>
                         <td className="p-3 text-brand-600 font-bold">${p.price}</td>
                         <td className="p-3 dark:text-gray-400">{p.durationDays} Days</td>
                         <td className="p-3 dark:text-gray-400">{p.features.length}</td>
                         <td className="p-3 flex gap-2">
                           <button onClick={() => handleEditPlan(p)} className="p-2 bg-blue-100 text-blue-600 rounded hover:bg-blue-200"><Edit size={16} /></button>
                           <button onClick={() => handleDeletePlan(p.id)} className="p-2 bg-red-100 text-red-600 rounded hover:bg-red-200"><Trash2 size={16} /></button>
                         </td>
                       </tr>
                     ))}
                   </tbody>
                 </table>
               </div>
            )}
         </div>
      )}
    </div>
  );
};

export default AdminPanel;

import React, { useState, useEffect } from 'react';
import { Book, User, CEFRLevel, PlanConfig, PlanType, SubscriptionStatus, Chapter } from '../types';
import { getBooks, saveBook, deleteBook, getUsers, saveUser, deleteUser, getPlans, savePlans } from '../services/storage';
import { Trash2, Edit, Plus, Users, Book as BookIcon, Save, X, Archive, DollarSign, Lock, CheckSquare, Square, Loader2, Search, List, ChevronRight } from 'lucide-react';
import { t } from '../services/i18n';

interface AdminPanelProps {
  currentUser: User;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ currentUser }) => {
  const [activeTab, setActiveTab] = useState<'BOOKS' | 'USERS' | 'PLANS'>('BOOKS');

  // Data
  const [books, setBooks] = useState<Book[]>([]);
  const [users, setUsersList] = useState<User[]>([]);
  const [plans, setPlansList] = useState<PlanConfig[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  // Search State
  const [userSearchTerm, setUserSearchTerm] = useState('');

  // Forms
  const [isEditingBook, setIsEditingBook] = useState(false);
  const [currentBook, setCurrentBook] = useState<Partial<Book>>({});
  const [activeChapterId, setActiveChapterId] = useState<string | null>(null);

  const [isEditingUser, setIsEditingUser] = useState(false);
  const [targetUser, setTargetUser] = useState<Partial<User>>({});

  const [isEditingPlan, setIsEditingPlan] = useState(false);
  const [targetPlan, setTargetPlan] = useState<Partial<PlanConfig>>({});
  const [planFeaturesText, setPlanFeaturesText] = useState(''); 

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = async () => {
    setIsLoading(true);
    const [b, u, p] = await Promise.all([getBooks(), getUsers(), getPlans()]);
    setBooks(b);
    setUsersList(u);
    setPlansList(p);
    setIsLoading(false);
  };

  // --- Book Handlers ---
  const handleEditBook = (book?: Book) => {
    const initBook = book ? { ...book } : { 
      id: '', 
      title: '', 
      author: '', 
      level: 'A1' as CEFRLevel, 
      coverUrl: 'https://picsum.photos/300/450', 
      chapters: [], 
      excerpt: '', 
      totalWords: 0, 
      requiredPlan: ['FREE'], 
      archived: false 
    };
    setCurrentBook(initBook);

    // Set active chapter to first one if exists
    if (initBook.chapters && initBook.chapters.length > 0) {
      setActiveChapterId(initBook.chapters[0].id);
    } else {
      setActiveChapterId(null);
    }

    setIsEditingBook(true);
  };

  const togglePlanForBook = (plan: PlanType) => {
    const currentPlans = currentBook.requiredPlan || [];
    if (currentPlans.includes(plan)) {
      setCurrentBook({ ...currentBook, requiredPlan: currentPlans.filter(p => p !== plan) });
    } else {
      setCurrentBook({ ...currentBook, requiredPlan: [...currentPlans, plan] });
    }
  };

  // Chapter Logic
  const handleAddChapter = () => {
    const newChapter: Chapter = {
      // Use random suffix to ensure uniqueness
      id: `c-${Date.now()}-${Math.floor(Math.random() * 100000)}`,
      title: 'New Chapter',
      content: ''
    };

    setCurrentBook(prevBook => {
        const updatedChapters = [...(prevBook.chapters || []), newChapter];
        return { ...prevBook, chapters: updatedChapters };
    });

    // Immediately select the new chapter
    setActiveChapterId(newChapter.id);
  };

  // UPDATED: Delete by index to handle duplicate IDs gracefully
  const handleDeleteChapter = (indexToDelete: number) => {
    if (!window.confirm("Delete this chapter?")) return;

    // Get current chapters from state to determine next active ID
    const currentChapters = currentBook.chapters || [];
    const chapterToDelete = currentChapters[indexToDelete];

    // Create new array without the item at indexToDelete
    const updatedChapters = currentChapters.filter((_, idx) => idx !== indexToDelete);

    // Update Book State
    setCurrentBook(prev => ({ ...prev, chapters: updatedChapters }));

    // If the deleted chapter was the active one, switch to another
    if (chapterToDelete && activeChapterId === chapterToDelete.id) {
       // Try to select the one at the same index (now shifted) or the previous one
       const nextChapter = updatedChapters.length > 0 
            ? updatedChapters[Math.min(indexToDelete, updatedChapters.length - 1)] 
            : null;
       setActiveChapterId(nextChapter ? nextChapter.id : null);
    }
  };

  const updateChapter = (id: string, field: keyof Chapter, value: string) => {
     setCurrentBook(prev => {
        const updatedChapters = (prev.chapters || []).map(c => {
            if (c.id === id) return { ...c, [field]: value };
            return c;
        });
        return { ...prev, chapters: updatedChapters };
     });
  };

  const handleSaveBook = async () => {
    if (!currentBook.title || (currentBook.chapters?.length === 0)) return alert("Title and at least one chapter required.");

    // Recalculate total words
    const totalWords = (currentBook.chapters || []).reduce((acc, c) => acc + c.content.split(' ').length, 0);

    const bookToSave: Book = {
      id: currentBook.id || 'b-' + Date.now(),
      title: currentBook.title!,
      author: currentBook.author || 'Unknown',
      level: currentBook.level as CEFRLevel,
      coverUrl: currentBook.coverUrl || '',
      chapters: currentBook.chapters || [],
      excerpt: currentBook.excerpt || (currentBook.chapters?.[0]?.content.substring(0, 100) || ''),
      totalWords: totalWords,
      requiredPlan: currentBook.requiredPlan && currentBook.requiredPlan.length > 0 ? currentBook.requiredPlan : ['FREE'],
      archived: currentBook.archived || false
    };

    await saveBook(bookToSave);
    setIsEditingBook(false);
    refreshData();
  };

  const handleArchiveBook = async (book: Book) => {
    const updatedBook = { ...book, archived: !book.archived };
    await saveBook(updatedBook);
    refreshData();
  };

  const handleDeleteBook = async (id: string) => {
    if (confirm(t('confirmDelete', currentUser.languagePreference))) {
      await deleteBook(id);
      refreshData();
    }
  };

  // --- User Handlers ---
  const handleEditUser = (u?: User) => {
    setTargetUser(u || {
      id: '', name: '', email: '', role: 'USER', password: '', plan: 'FREE', subscriptionStatus: 'ACTIVE'
    });
    setIsEditingUser(true);
  };

  const handleSaveUser = async () => {
