};

// --- Main App Component ---
const App = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [user, setUser] = useState<User | null>(null);
  const [currentPage, setCurrentPage] = useState('dashboard');

  // Selection State
  const [selectedBook, setSelectedBook] = useState<Book | null>(null);
  const [activeChapterIndex, setActiveChapterIndex] = useState<number | null>(null);

  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isQuizActive, setIsQuizActive] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  // Dynamic Data
  const [books, setBooks] = useState<Book[]>([]);
  const [savedWords, setSavedWords] = useState<VocabularyWord[]>([]);
  const [bookProgress, setBookProgress] = useState<Record<string, UserBookProgress>>({});
  const [plans, setPlans] = useState<PlanConfig[]>([]);

  // Initialization
  useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);
        await initStorage();
        const loadedPlans = await getPlans();
        setPlans(loadedPlans);

        const sessId = getSession();
        if (sessId) {
          const restoredUser = await getUserById(sessId);
          if (restoredUser) {
            setUser(restoredUser);
            setIsAuthenticated(true);
          }
        }
      } catch (e) {
        console.error("Initialization error:", e);
      } finally {
        setIsLoading(false);
      }
    };
    init();
  }, []);

  useEffect(() => {
    if (isDarkMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [isDarkMode]);

  useEffect(() => {
    if (user && user.subscriptionStatus === 'TRIAL') {
      if (Date.now() > user.trialEndsAt) {
         const downgradedUser: User = { 
           ...user, 
           subscriptionStatus: 'ACTIVE', 
           plan: 'FREE',
           trialEndsAt: 0 
         };
         setUser(downgradedUser);
         saveUser(downgradedUser);
         alert("Your trial period has ended. You have been downgraded to the Free plan.");
      }
    } else if (user && user.subscriptionStatus === 'ACTIVE' && user.plan !== 'FREE' && user.subscriptionEndsAt) {
       if (Date.now() > user.subscriptionEndsAt) {
         const downgradedUser: User = { 
           ...user, 
           subscriptionStatus: 'ACTIVE', 
           plan: 'FREE',
           subscriptionEndsAt: 0 
         };
         setUser(downgradedUser);
         saveUser(downgradedUser);
         alert("Your subscription has expired. You have been downgraded to the Free plan.");
       }
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      const loadUserData = async () => {
        const [loadedBooks, loadedVocab, loadedProgress] = await Promise.all([
            getBooks(),
            getUserVocab(user.id),
            getUserProgress(user.id)
        ]);
        setBooks(loadedBooks);
        setSavedWords(loadedVocab);
        setBookProgress(loadedProgress);
      };
      loadUserData();
    }
  }, [user, currentPage]); 

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    setIsAuthenticated(true);
    saveSession(loggedInUser.id);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setUser(null);
    setSelectedBook(null);
    setActiveChapterIndex(null);
    setCurrentPage('dashboard');
    clearSession();
  };

  const handleUpdateUser = (updatedUser: User) => {
    setUser(updatedUser);
    saveUser(updatedUser); 
  };

  const handleToggleLanguage = () => {
    if (!user) return;
    const newUser = { 
      ...user, 
      languagePreference: user.languagePreference === 'TR' ? 'EN' : 'TR' as 'EN' | 'TR'
    };
    handleUpdateUser(newUser);
  };

  const handleSaveWord = (word: VocabularyWord) => {
    if (!user) return;
    const newWords = [word, ...savedWords];
    setSavedWords(newWords);
    saveUserVocab(user.id, newWords);

    const wordsToday = getDailyWordCountInternal(newWords); 
    const currentGoal = user.dailyGoal || 25;

    if (wordsToday === currentGoal) {
       const newStreak = user.streak + 1;
       const newXp = user.xp + 50; 
       handleUpdateUser({ ...user, streak: newStreak, xp: newXp });
       alert(`Daily Goal Reached! Streak increased to ${newStreak}! +50 XP`);
    } else {
       handleUpdateUser({ ...user, xp: user.xp + 5 });
    }
  };

  const handleDeleteWord = (id: string) => {
    if (!user) return;
    const newWords = savedWords.filter(w => w.id !== id);
    setSavedWords(newWords);
    saveUserVocab(user.id, newWords);
  };

  // UPDATED: Added autoJump to handle resuming reading automatically
  const handleSelectBook = (book: Book, autoJump: boolean = false) => {
    if (!user) return;
    setSelectedBook(book);

    const progress = bookProgress[book.id];

    // Auto-initialization if not exists
    if (!progress) {
      const newEntry: UserBookProgress = {
          bookId: book.id,
          status: 'IN_PROGRESS',
          currentChapterIndex: 0,
          lastReadAt: new Date()
      };
      const newProgress = { ...bookProgress, [book.id]: newEntry };
      setBookProgress(newProgress);
      saveUserProgress(user.id, newProgress);

      if (autoJump) {
         setActiveChapterIndex(0);
      } else {
         setActiveChapterIndex(null);
      }
    } else {
       if (autoJump) {
          // If autoJump is true, jump to currentChapterIndex
          const chapters = book.chapters || [];
          const idx = progress.currentChapterIndex < chapters.length ? progress.currentChapterIndex : 0;
          setActiveChapterIndex(idx);
       } else {
          setActiveChapterIndex(null);
       }
    }
  };

  const handleSelectChapter = (chapterIndex: number) => {
    setActiveChapterIndex(chapterIndex);
  };

  const handleCompleteChapter = (bookId: string, chapterIndex: number) => {
    if (!user || !selectedBook) return;

    const currentProgress = bookProgress[bookId] || { 
        bookId, 
        status: 'IN_PROGRESS', 
        currentChapterIndex: 0, 
        lastReadAt: new Date() 
    };

    const nextChapterIndex = chapterIndex + 1;
    const newMaxIndex = Math.max(currentProgress.currentChapterIndex, nextChapterIndex);

    const chapters = selectedBook.chapters || [];
    let newStatus = currentProgress.status;

    if (chapters.length > 0 && chapterIndex >= chapters.length - 1) {
        newStatus = 'COMPLETED';
    }

    const newProgressEntry: UserBookProgress = {
        ...currentProgress,
        status: newStatus,
        currentChapterIndex: newMaxIndex,
        lastReadAt: new Date()
    };

    const newProgressMap = { ...bookProgress, [bookId]: newProgressEntry };
    setBookProgress(newProgressMap);
    saveUserProgress(user.id, newProgressMap);
  };

  const handleStartQuiz = () => {
    if (savedWords.length < 5) {
      alert("You need at least 5 words to start a quiz.");
      return;
    }
    setIsQuizActive(true);
  };

  const handleQuizComplete = (result: QuizResult) => {
    if (!user) return;
    const newXp = user.xp + (result.score * 10);
    const updatedUser = { ...user, xp: newXp };
    setUser(updatedUser);
    saveUser(updatedUser);
    setIsQuizActive(false);
  };

  const handleUpgrade = (plan: PlanType) => {
    if(!user) return;

    const planConfig = plans.find(p => p.id === plan);
    const durationDays = planConfig ? planConfig.durationDays : (plan === 'YEARLY' ? 365 : 30);

    const updatedUser: User = {
      ...user,
      subscriptionStatus: 'ACTIVE',
      plan: plan,
      subscriptionEndsAt: Date.now() + durationDays * 24 * 60 * 60 * 1000
    };
    handleUpdateUser(updatedUser);
    setCurrentPage('dashboard');
    alert("Payment Successful! Welcome to ReadLex PRO.");
  };

  const getDailyWordCountInternal = (currentWords: VocabularyWord[]) => {
    const today = new Date();
    today.setHours(0,0,0,0);
    const todayTs = today.getTime();

    return currentWords.filter(w => {
       const wordTime = parseInt(w.id);
       return wordTime >= todayTs;
    }).length;
  }

  const getDailyWordCount = () => {
    return getDailyWordCountInternal(savedWords);
  }

  if (isLoading) {
      return (
          <div className="h-screen w-screen flex flex-col items-center justify-center bg-gray-50 dark:bg-gray-900">
             <Loader2 size={48} className="text-brand-600 animate-spin mb-4" />
             <p className="text-gray-500 font-bold animate-pulse">Loading ReadLex...</p>
          </div>
      );
  }

  if (!isAuthenticated || !user) {
    return (
      <div className={isDarkMode ? 'dark' : ''}>
         <Auth onLogin={handleLogin} />
      </div>
    );
  }

  const renderContent = () => {
    if (isQuizActive) {
      return (
        <div className="h-full flex flex-col items-center justify-center">
          <div className="w-full max-w-2xl mb-6 flex justify-between items-center">
            <h2 className="text-2xl font-black dark:text-white flex items-center">
              <Clock className="mr-3 text-brand-500" /> Practice Session
            </h2>
            <button onClick={() => setIsQuizActive(false)} className="px-5 py-2 rounded-xl bg-gray-200 hover:bg-gray-300 dark:bg-gray-800 dark:text-white text-gray-700 font-bold transition-colors">
              Exit
            </button>
          </div>
          <div className="w-full">
            <QuizEngine words={savedWords} onComplete={handleQuizComplete} onExit={() => setIsQuizActive(false)} />
          </div>
        </div>
      );
    }

    if (selectedBook) {
        if (activeChapterIndex !== null) {
            return (
                <BookReader 
                  book={selectedBook} 
                  initialChapterIndex={activeChapterIndex}
                  onBack={() => setActiveChapterIndex(null)} 
                  onSaveWord={handleSaveWord}
                  savedWords={savedWords}
                  onCompleteChapter={handleCompleteChapter}
                />
            );
        } else {
            return (
                <ChapterList 
                  book={selectedBook} 
                  progress={bookProgress[selectedBook.id]} 
                  onSelectChapter={handleSelectChapter}
                  onBack={() => setSelectedBook(null)}
                />
            );
        }
    }

    switch (currentPage) {
      case 'dashboard':
        return (
          <Dashboard 
            user={user} 
            vocabCount={savedWords.length} 
            wordsAddedToday={getDailyWordCount()} 
            onStartQuiz={handleStartQuiz} 
            onUpgradeClick={() => setCurrentPage('pricing')} 
            books={books}
            bookProgress={bookProgress}
            onContinueBook={handleSelectBook}
            onNavigateToLibrary={() => setCurrentPage('library')}
          />
        );
      case 'library':
        return <Library books={books} progressMap={bookProgress} onSelectBook={handleSelectBook} user={user} />;
      case 'vocabulary':
        return <VocabularyWrapper user={user} words={savedWords} onDelete={handleDeleteWord} />;
      case 'profile':
        return <Profile user={user} onUpdate={handleUpdateUser} />;
      case 'pricing':
        return <Pricing user={user} onUpgrade={handleUpgrade} />;
      case 'admin':
        if (user.role !== 'ADMIN') return <div className="p-10 text-center text-red-500 font-bold text-2xl">Access Denied</div>;
        return <AdminPanel currentUser={user} />;
      default:
        return (
          <Dashboard 
            user={user} 
            vocabCount={savedWords.length} 
            wordsAddedToday={getDailyWordCount()} 
            onStartQuiz={handleStartQuiz} 
            onUpgradeClick={() => setCurrentPage('pricing')} 
            books={books}
            bookProgress={bookProgress}
            onContinueBook={handleSelectBook}
            onNavigateToLibrary={() => setCurrentPage('library')}
          />
        );
    }
  };

  return (
    <Layout 
      activePage={currentPage} 
      onNavigate={(p) => {
        setCurrentPage(p);
        setSelectedBook(null);
        setActiveChapterIndex(null);
        setIsQuizActive(false);
      }}
      isDarkMode={isDarkMode}
      toggleTheme={() => setIsDarkMode(!isDarkMode)}
      currentUser={user}
      onToggleLang={handleToggleLanguage}
      onLogout={handleLogout}
    >
      {renderContent()}
    </Layout>
  );
};

export default App;

import React from 'react';
import { Book, UserBookProgress } from '../types';
import { PlayCircle, CheckCircle, Lock, ArrowLeft, BookOpen, Play } from 'lucide-react';

interface ChapterListProps {
  book: Book;
  progress?: UserBookProgress;
  onSelectChapter: (chapterIndex: number) => void;
  onBack: () => void;
}

const ChapterList: React.FC<ChapterListProps> = ({ book, progress, onSelectChapter, onBack }) => {
  const chapters = book.chapters || [];

  const completedChapters = progress?.currentChapterIndex || 0;
  const totalChapters = chapters.length;
  const percentage = totalChapters > 0 ? Math.round((completedChapters / totalChapters) * 100) : 0;

  // Find the index to "Continue"
  const continueIndex = Math.min(completedChapters, totalChapters - 1);

  return (
    <div className="min-h-screen bg-[#F0F4F8] dark:bg-gray-950 pb-20">
      {/* Header with Cover */}
      <div className="relative h-64 md:h-80 w-full bg-gray-900 overflow-hidden">
        <img src={book.coverUrl} className="absolute inset-0 w-full h-full object-cover opacity-40 blur-sm" />
        <div className="absolute inset-0 bg-gradient-to-t from-[#F0F4F8] dark:from-gray-950 to-transparent" />

        <div className="absolute top-0 left-0 p-6 z-20">
           <button onClick={onBack} className="bg-white/20 hover:bg-white/30 backdrop-blur-md p-3 rounded-full text-white transition-all">
             <ArrowLeft size={24} />
           </button>
        </div>

        <div className="absolute bottom-0 left-0 w-full p-6 md:p-10 z-20 flex flex-col md:flex-row items-end md:items-center gap-6">
           <img 
              src={book.coverUrl} 
              className="w-32 h-48 object-cover rounded-lg shadow-2xl border-4 border-white dark:border-gray-800 hidden md:block" 
           />
           <div className="flex-1">
             <span className={`px-3 py-1 rounded-md text-xs font-bold text-white mb-2 inline-block
                ${book.level.startsWith('A') ? 'bg-green-500' : book.level.startsWith('B') ? 'bg-yellow-500' : 'bg-red-500'}`}>
                {book.level}
             </span>
             <h1 className="text-3xl md:text-5xl font-black text-gray-900 dark:text-white mb-2 leading-tight">{book.title}</h1>
             <div className="flex items-center text-sm font-medium text-gray-500 dark:text-gray-400">
                <BookOpen size={16} className="mr-2" /> {totalChapters} Chapters
                <span className="mx-3">•</span>
                {book.totalWords} Words
             </div>
           </div>
        </div>
      </div>

      <div className="max-w-4xl mx-auto px-6 mt-8">
        <div className="flex flex-col md:flex-row gap-6 mb-8">
           {/* Progress Panel */}
           {progress && progress.status !== 'NOT_STARTED' && totalChapters > 0 && (
              <div className="flex-1 bg-white dark:bg-gray-800 p-6 rounded-[2rem] shadow-sm border border-gray-100 dark:border-gray-700">
                 <div className="flex justify-between items-center mb-2">
                    <span className="font-bold dark:text-white">İlerlemen</span>
                    <span className="font-black text-brand-600">{percentage}%</span>
                 </div>
                 <div className="w-full bg-gray-100 dark:bg-gray-700 rounded-full h-3 overflow-hidden">
                    <div className="bg-brand-600 h-full rounded-full transition-all duration-1000" style={{ width: `${percentage}%` }}></div>
                 </div>
              </div>
           )}

           {/* Continue Button */}
           {progress && progress.status === 'IN_PROGRESS' && totalChapters > 0 && (
              <button 
                onClick={() => onSelectChapter(continueIndex)}
                className="bg-brand-600 text-white px-8 py-6 rounded-[2rem] font-black text-lg shadow-xl shadow-brand-500/20 hover:bg-brand-700 hover:scale-[1.02] transition-all flex items-center justify-center gap-3"
              >
                 <Play className="fill-current" /> Kaldığın Yerden Devam Et
              </button>
           )}
        </div>

        <h2 className="text-xl font-black text-gray-900 dark:text-white mb-6">Bölümler</h2>

        <div className="space-y-4">
           {chapters.map((chapter, index) => {
              const isCompleted = index < completedChapters;
              const isCurrent = index === completedChapters;
              const canRead = index <= completedChapters || progress?.status === 'COMPLETED';

              return (
                <div 
                   key={chapter.id}
                   onClick={() => canRead && onSelectChapter(index)}
                   className={`group relative bg-white dark:bg-gray-800 p-5 rounded-2xl border transition-all duration-300 flex items-center
                      ${canRead ? 'cursor-pointer hover:border-brand-300 dark:hover:border-brand-700 hover:shadow-lg' : 'opacity-60 cursor-not-allowed border-gray-100 dark:border-gray-800'}
                      ${isCurrent ? 'border-brand-500 ring-2 ring-brand-500/20' : 'border-gray-100 dark:border-gray-700'}
                   `}
                >
                   <div className={`w-12 h-12 rounded-full flex items-center justify-center mr-5 font-black text-lg shrink-0
                      ${isCompleted ? 'bg-green-100 text-green-600' : isCurrent ? 'bg-brand-600 text-white' : 'bg-gray-100 dark:bg-gray-700 text-gray-500'}
                   `}>
                      {isCompleted ? <CheckCircle size={24} /> : index + 1}
                   </div>

                   <div className="flex-1">
                      <h3 className={`font-bold text-lg ${canRead ? 'text-gray-900 dark:text-white' : 'text-gray-500'}`}>
                         {chapter.title}
                      </h3>
                      <p className="text-xs text-gray-400 font-medium uppercase tracking-wider mt-1">
                         {Math.ceil((chapter.content || '').split(' ').length / 150)} min read
                      </p>
                   </div>

                   <div className="ml-4">
                      {canRead ? (
                        <PlayCircle size={28} className={`${isCurrent ? 'text-brand-600' : 'text-gray-300 group-hover:text-brand-500'}`} />
                      ) : (
                        <Lock size={24} className="text-gray-300" />
                      )}
                   </div>
                </div>
              );
           })}

           {chapters.length === 0 && (
             <div className="p-8 text-center text-gray-400 font-bold bg-white dark:bg-gray-800 rounded-2xl border border-dashed border-gray-300 dark:border-gray-700">
               No chapters available. Please update the book content.
             </div>
           )}
        </div>
      </div>
    </div>
  );
};

